function encodeSvgDataUri(svgMarkup) {
  return `data:image/svg+xml;charset=utf-8,${encodeURIComponent(
    String(svgMarkup || '')
      .replace(/\s{2,}/g, ' ')
      .trim()
  )}`;
}

function escapePokerSvgText(value) {
  return String(value || '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

function normalizeNoteText(value) {
  return String(value ?? '').replace(/\r\n?/g, '\n').slice(0, NOTE_TEXT_MAX_LENGTH);
}

function normalizeCoolJpegsArtistLabel(value) {
  return String(value || '')
    .trim()
    .toLowerCase()
    .replace(/\s+/g, ' ');
}

function normalizeCoolJpegsAuctionType(value) {
  return String(value || '')
    .trim()
    .toLowerCase()
    .replace(/\s+/g, ' ');
}

function normalizeAuctionSlotIndex(value) {
  const numeric = Number(value);
  if (Number.isInteger(numeric) && numeric === 1) {
    return 1;
  }
  return 0;
}

function getCardAuctionSlotIndex(cardState) {
  return normalizeAuctionSlotIndex(cardState?.auctionSlotIndex);
}

function resolveCoolJpegsAuctionTypeIconSrc(value) {
  const normalizedType = normalizeCoolJpegsAuctionType(value);
  if (!normalizedType) {
    return '';
  }
  return COOL_JPEGS_AUCTION_TYPE_ICON_BY_KEY[normalizedType] || '';
}

function getCoolJpegsCardNumberFromFrontSrc(frontSrc = '') {
  const normalized = String(frontSrc || '').trim().toLowerCase();
  if (!normalized) {
    return NaN;
  }
  const match = normalized.match(/(?:^|\/)(\d{4})(?:\.[a-z0-9]+)?(?:[?#].*)?$/i);
  if (!match) {
    return NaN;
  }
  const numeric = Number(match[1]);
  if (!Number.isInteger(numeric)) {
    return NaN;
  }
  return numeric;
}

function getCoolJpegsCardNumberFromCardId(cardId = '') {
  const normalized = String(cardId || '').trim();
  if (!normalized) {
    return NaN;
  }
  const inferredDeckId = inferDeckIdFromCardId(normalized);
  if (!isCoolDeckId(inferredDeckId)) {
    return NaN;
  }
  const suffixMatch = normalized.match(/-(\d{3})$/);
  if (!suffixMatch) {
    return NaN;
  }
  const ordinal = Number(suffixMatch[1]);
  if (!Number.isInteger(ordinal) || ordinal < 1) {
    return NaN;
  }
  return 999 + ordinal;
}

function resolveCoolJpegsCardInfo(cardPayload, cardId = '') {
  const payload = cardPayload && typeof cardPayload === 'object' ? cardPayload : {};
  const explicitArtist = normalizeCoolJpegsArtistLabel(payload.artist);
  const explicitAuctionType = normalizeCoolJpegsAuctionType(payload.auctionType);
  const cardNumberFromSrc = getCoolJpegsCardNumberFromFrontSrc(payload.frontSrc || '');
  const cardNumberFromId = getCoolJpegsCardNumberFromCardId(cardId);
  const cardNumber = Number.isInteger(cardNumberFromSrc)
    ? cardNumberFromSrc
    : (Number.isInteger(cardNumberFromId) ? cardNumberFromId : NaN);
  const mapped = Number.isInteger(cardNumber) ? COOL_JPEGS_CARD_INFO_BY_NUMBER[cardNumber] : null;
  const artist = explicitArtist || normalizeCoolJpegsArtistLabel(mapped?.artist || '');
  const auctionType = explicitAuctionType || normalizeCoolJpegsAuctionType(mapped?.auctionType || '');
  if (!artist || !auctionType) {
    return null;
  }
  const artistIconSrc = COOL_JPEGS_ARTIST_ICON_BY_KEY[artist] || '';
  return {
    cardNumber,
    artist,
    auctionType,
    artistIconSrc
  };
}

function splitNoteTextIntoFaceLines(rawText, maxCharsPerLine = NOTE_FACE_LINE_WRAP_CHARS, maxLines = NOTE_FACE_MAX_LINES) {
  const normalizedText = normalizeNoteText(rawText);
  if (!normalizedText) {
    return [];
  }
  const maxChars = Math.max(4, Math.floor(Number(maxCharsPerLine) || NOTE_FACE_LINE_WRAP_CHARS));
  const lineLimit = Math.max(1, Math.floor(Number(maxLines) || NOTE_FACE_MAX_LINES));
  const lines = [];
  const pushLine = (line) => {
    if (lines.length >= lineLimit) {
      return false;
    }
    lines.push(line);
    return lines.length < lineLimit;
  };
  const breakLongWord = (word) => {
    let remaining = String(word || '');
    while (remaining.length > maxChars && lines.length < lineLimit) {
      const segment = remaining.slice(0, maxChars);
      if (!pushLine(segment)) {
        return '';
      }
      remaining = remaining.slice(maxChars);
    }
    return remaining;
  };
  for (const paragraph of normalizedText.split('\n')) {
    if (lines.length >= lineLimit) {
      break;
    }
    const words = paragraph.trim().split(/\s+/).filter(Boolean);
    if (words.length === 0) {
      if (!pushLine('')) {
        break;
      }
      continue;
    }
    let currentLine = '';
    for (let word of words) {
      if (lines.length >= lineLimit) {
        break;
      }
      if (word.length > maxChars) {
        if (currentLine) {
          if (!pushLine(currentLine)) {
            currentLine = '';
            break;
          }
          currentLine = '';
        }
        word = breakLongWord(word);
        if (!word) {
          continue;
        }
      }
      const candidate = currentLine ? `${currentLine} ${word}` : word;
      if (candidate.length <= maxChars) {
        currentLine = candidate;
        continue;
      }
      if (!pushLine(currentLine)) {
        currentLine = '';
        break;
      }
      currentLine = word;
    }
    if (currentLine && lines.length < lineLimit) {
      if (!pushLine(currentLine)) {
        break;
      }
    }
  }
  return lines.slice(0, lineLimit);
}

function createNoteFaceSvgDataUri(rawText = '', face = 'front') {
  const safeFace = face === 'back' ? 'back' : 'front';
  const availableTextWidth = Math.max(
    8,
    NOTE_FACE_PAPER_SIZE - NOTE_FACE_TEXT_PADDING_LEFT - NOTE_FACE_TEXT_PADDING_RIGHT
  );
  const availableTextHeight = Math.max(
    10,
    NOTE_FACE_PAPER_SIZE - NOTE_FACE_TEXT_PADDING_TOP - NOTE_FACE_TEXT_PADDING_BOTTOM
  );
  const maxCharsPerLine = Math.max(
    4,
    Math.floor(availableTextWidth / Math.max(1, NOTE_FACE_TEXT_FONT_SIZE * NOTE_FACE_TEXT_CHAR_WIDTH_FACTOR))
  );
  const maxLines = Math.max(1, Math.floor(availableTextHeight / NOTE_FACE_TEXT_LINE_HEIGHT));
  const noteLines = splitNoteTextIntoFaceLines(rawText, maxCharsPerLine, maxLines);
  const textStartX = NOTE_FACE_PAPER_INSET + NOTE_FACE_TEXT_PADDING_LEFT;
  const textStartY = NOTE_FACE_PAPER_INSET + NOTE_FACE_TEXT_PADDING_TOP + NOTE_FACE_TEXT_FONT_SIZE * NOTE_FACE_TEXT_BASELINE_FACTOR;
  const textMarkup = noteLines
    .map((line, index) => {
      const safeLine = escapePokerSvgText(line);
      const lineY = textStartY + index * NOTE_FACE_TEXT_LINE_HEIGHT;
      return `<text x="${textStartX}" y="${lineY}" font-family="Trebuchet MS, Segoe UI, sans-serif" font-size="${NOTE_FACE_TEXT_FONT_SIZE}" fill="#3c341f">${safeLine}</text>`;
    })
    .join('');
  const paperFill = safeFace === 'back' ? '#e8ce78' : '#f2d97f';
  return encodeSvgDataUri(`
    <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${NOTE_FACE_SVG_SIZE} ${NOTE_FACE_SVG_SIZE}">
      <rect x="${NOTE_FACE_PAPER_INSET}" y="${NOTE_FACE_PAPER_INSET}" width="${NOTE_FACE_PAPER_SIZE}" height="${NOTE_FACE_PAPER_SIZE}" fill="${paperFill}" />
      <rect x="${NOTE_FACE_PAPER_INSET}" y="${NOTE_FACE_PAPER_INSET}" width="${NOTE_FACE_PAPER_SIZE}" height="${NOTE_FACE_PAPER_SIZE}" fill="none" stroke="rgba(85,68,27,0.34)" stroke-width="2"/>
      <g>${textMarkup}</g>
    </svg>
  `);
}

function createPokerFaceSvgDataUri(rank, suit) {
  const safeRank = escapePokerSvgText(rank);
  const safeSuit = escapePokerSvgText(suit?.symbol || '');
  const suitColor = String(suit?.color || '#17171a');
  const rankFontSize = 52;
  const rankLetterSpacingAttr = safeRank === '10' ? ' letter-spacing="-2.2"' : '';
  const cornerSuitSize = 40;
  const centerSuitSize = 154;
  const cardFaceWidth = 330;
  const cardFaceHeight = 462;
  const topRankX = 36;
  const topRankY = 66;
  const topSuitX = 37;
  const topSuitY = 108;
  const bottomRankX = cardFaceWidth - topRankX;
  const bottomRankY = cardFaceHeight - topRankY;
  const bottomSuitX = cardFaceWidth - topSuitX;
  const bottomSuitY = cardFaceHeight - topSuitY;
  const centerSuitX = 165;
  const centerSuitY = 222;
  return encodeSvgDataUri(`
    <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 330 462">
      <rect x="0" y="0" width="330" height="462" rx="24" fill="#ffffff"/>
      <rect x="8" y="8" width="314" height="446" rx="20" fill="none" stroke="#d5d9df" stroke-width="3.2"/>
      <g fill="${suitColor}">
        <text x="${topRankX}" y="${topRankY}" text-anchor="start" font-family="Georgia, 'Times New Roman', serif" font-size="${rankFontSize}" font-weight="700"${rankLetterSpacingAttr}>${safeRank}</text>
        <text x="${topSuitX}" y="${topSuitY}" text-anchor="start" font-family="Georgia, 'Times New Roman', serif" font-size="${cornerSuitSize}" font-weight="700">${safeSuit}</text>
        <text x="${bottomRankX}" y="${bottomRankY}" text-anchor="start" font-family="Georgia, 'Times New Roman', serif" font-size="${rankFontSize}" font-weight="700"${rankLetterSpacingAttr} transform="rotate(180 ${bottomRankX} ${bottomRankY})">${safeRank}</text>
        <text x="${bottomSuitX}" y="${bottomSuitY}" text-anchor="start" font-family="Georgia, 'Times New Roman', serif" font-size="${cornerSuitSize}" font-weight="700" transform="rotate(180 ${bottomSuitX} ${bottomSuitY})">${safeSuit}</text>
      </g>
      <text
        x="${centerSuitX}"
        y="${centerSuitY}"
        fill="${suitColor}"
        text-anchor="middle"
        dominant-baseline="middle"
        font-family="Georgia, 'Times New Roman', serif"
        font-size="${centerSuitSize}"
        font-weight="700"
      >${safeSuit}</text>
    </svg>
  `);
}

function createPokerBackSvgDataUri() {
  return encodeSvgDataUri(`
    <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 330 462">
      <defs>
        <linearGradient id="pokerBackGradient" x1="0" y1="0" x2="1" y2="1">
          <stop offset="0%" stop-color="#1c3f8f"/>
          <stop offset="100%" stop-color="#132d67"/>
        </linearGradient>
        <pattern id="pokerBackPattern" width="28" height="28" patternUnits="userSpaceOnUse" patternTransform="rotate(45)">
          <rect width="28" height="28" fill="#1f4ea9"/>
          <rect width="14" height="14" fill="#2b61c4"/>
          <rect x="14" y="14" width="14" height="14" fill="#2b61c4"/>
        </pattern>
      </defs>
      <rect x="0" y="0" width="330" height="462" rx="24" fill="#0f224d"/>
      <rect x="10" y="10" width="310" height="442" rx="20" fill="url(#pokerBackGradient)"/>
      <rect x="24" y="24" width="282" height="414" rx="15" fill="url(#pokerBackPattern)"/>
      <rect x="34" y="34" width="262" height="394" rx="14" fill="none" stroke="#f3f7ff" stroke-width="3" opacity="0.88"/>
      <rect x="52" y="52" width="226" height="358" rx="12" fill="none" stroke="#dce8ff" stroke-width="1.9" opacity="0.55"/>
    </svg>
  `);
}

function normalizeCodegameKeyIndexList(value, maxCount = CODEGAME_KEY_TOTAL_CELLS) {
  const source = Array.isArray(value) ? value : [];
  const limit = Math.max(0, Math.floor(Number(maxCount) || CODEGAME_KEY_TOTAL_CELLS));
  if (source.length === 0 || limit <= 0) {
    return [];
  }
  const seen = new Set();
  const normalized = [];
  for (const item of source) {
    const numeric = Number(item);
    if (!Number.isInteger(numeric)) {
      continue;
    }
    const clamped = clamp(numeric, 0, CODEGAME_KEY_TOTAL_CELLS - 1);
    if (seen.has(clamped)) {
      continue;
    }
    seen.add(clamped);
    normalized.push(clamped);
    if (normalized.length >= limit) {
      break;
    }
  }
  return normalized;
}

function normalizeCodegameMarkedType(value) {
  const normalized = String(value || '').trim().toLowerCase();
  if (
    normalized === 'blue' ||
    normalized === 'red' ||
    normalized === 'assassin' ||
    normalized === 'neutral'
  ) {
    return normalized;
  }
  return '';
}

function generateCodegameKeyPattern() {
  const indices = Array.from({ length: CODEGAME_KEY_TOTAL_CELLS }, (_, index) => index);
  for (let index = indices.length - 1; index > 0; index -= 1) {
    const swapIndex = Math.floor(Math.random() * (index + 1));
    const temp = indices[index];
    indices[index] = indices[swapIndex];
    indices[swapIndex] = temp;
  }
  const blue = indices.slice(0, CODEGAME_KEY_BLUE_COUNT);
  const red = indices.slice(CODEGAME_KEY_BLUE_COUNT, CODEGAME_KEY_BLUE_COUNT + CODEGAME_KEY_RED_COUNT);
  const assassin = indices[CODEGAME_KEY_BLUE_COUNT + CODEGAME_KEY_RED_COUNT] ?? 0;
  return {
    blue,
    red,
    assassin
  };
}

function createCodegameKeyFaceSvgDataUri(pattern) {
  const blueSet = new Set(Array.isArray(pattern?.blue) ? pattern.blue.map((value) => Math.max(0, Math.min(24, Math.floor(Number(value) || 0)))) : []);
  const redSet = new Set(Array.isArray(pattern?.red) ? pattern.red.map((value) => Math.max(0, Math.min(24, Math.floor(Number(value) || 0)))) : []);
  const assassinIndex = Math.max(0, Math.min(24, Math.floor(Number(pattern?.assassin) || 0)));
  const gridCell = 54;
  const gridGap = 3;
  const gridStart = 23;
  const cellSpan = gridCell + gridGap;
  const rows = CODEGAME_GRID_SIZE;
  const cols = CODEGAME_GRID_SIZE;
  let cellMarkup = '';
  for (let row = 0; row < rows; row += 1) {
    for (let col = 0; col < cols; col += 1) {
      const index = row * cols + col;
      const x = gridStart + col * cellSpan;
      const y = gridStart + row * cellSpan;
      let fill = '#e4e0d6';
      let stroke = 'rgba(86, 78, 65, 0.44)';
      let overlay = '';
      if (index === assassinIndex) {
        fill = '#17171a';
        stroke = 'rgba(64, 64, 64, 0.75)';
        overlay = `
          <path d="M${x + 13} ${y + 13}L${x + gridCell - 13} ${y + gridCell - 13}" stroke="rgba(198,198,198,0.8)" stroke-width="6" stroke-linecap="round"/>
          <path d="M${x + gridCell - 13} ${y + 13}L${x + 13} ${y + gridCell - 13}" stroke="rgba(198,198,198,0.8)" stroke-width="6" stroke-linecap="round"/>
        `;
      } else if (blueSet.has(index)) {
        fill = '#2b68de';
        stroke = 'rgba(162, 198, 255, 0.5)';
        const cx = x + gridCell / 2;
        const cy = y + gridCell / 2;
        overlay = `
          <circle cx="${cx}" cy="${cy}" r="${gridCell * 0.23}" fill="none" stroke="rgba(255,255,255,0.88)" stroke-width="3.8"/>
          <circle cx="${cx}" cy="${cy}" r="${gridCell * 0.31}" fill="none" stroke="rgba(255,255,255,0.28)" stroke-width="3"/>
        `;
      } else if (redSet.has(index)) {
        fill = '#d8474a';
        stroke = 'rgba(255, 207, 207, 0.48)';
        const cx = x + gridCell / 2;
        const cy = y + gridCell / 2;
        overlay = `
          <circle cx="${cx}" cy="${cy}" r="${gridCell * 0.23}" fill="none" stroke="rgba(255,255,255,0.88)" stroke-width="3.8"/>
          <circle cx="${cx}" cy="${cy}" r="${gridCell * 0.31}" fill="none" stroke="rgba(255,255,255,0.28)" stroke-width="3"/>
        `;
      }
      cellMarkup += `<rect x="${x}" y="${y}" width="${gridCell}" height="${gridCell}" rx="6" fill="${fill}" stroke="${stroke}" stroke-width="1.9"/>${overlay}`;
    }
  }
  return encodeSvgDataUri(`
    <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 330 330">
      <rect x="0" y="0" width="330" height="330" rx="24" fill="#f7f4ea"/>
      <rect x="8" y="8" width="314" height="314" rx="18" fill="none" stroke="#d4cdbf" stroke-width="2.8"/>
      ${cellMarkup}
    </svg>
  `);
}

function createCodegameKeyBackSvgDataUri() {
  return encodeSvgDataUri(`
    <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 330 330">
      <defs>
        <linearGradient id="codegameKeyBackGradient" x1="0" y1="0" x2="1" y2="1">
          <stop offset="0%" stop-color="#5b0f18"/>
          <stop offset="54%" stop-color="#431018"/>
          <stop offset="100%" stop-color="#2a0b12"/>
        </linearGradient>
        <radialGradient id="codegameKeyIconGlow" cx="50%" cy="50%" r="62%">
          <stop offset="0%" stop-color="rgba(255,225,210,0.22)"/>
          <stop offset="100%" stop-color="rgba(255,225,210,0)"/>
        </radialGradient>
        <filter id="codegameKeyBackGrain">
          <feTurbulence type="fractalNoise" baseFrequency="0.92" numOctaves="2" seed="19" stitchTiles="stitch" result="noise"/>
          <feColorMatrix in="noise" type="saturate" values="0"/>
          <feComponentTransfer>
            <feFuncA type="table" tableValues="0 0.12"/>
          </feComponentTransfer>
        </filter>
      </defs>
      <rect x="0" y="0" width="330" height="330" rx="24" fill="url(#codegameKeyBackGradient)"/>
      <rect x="0" y="0" width="330" height="330" rx="24" fill="#100508" opacity="0.16"/>
      <rect x="0" y="0" width="330" height="330" rx="24" fill="#ffffff" opacity="0.04"/>
      <rect x="0" y="0" width="330" height="330" rx="24" filter="url(#codegameKeyBackGrain)"/>
      <circle cx="166" cy="166" r="92" fill="url(#codegameKeyIconGlow)"/>
      <g transform="translate(166 166) rotate(-22)">
        <circle cx="-38" cy="0" r="34" fill="none" stroke="rgba(234,214,204,0.94)" stroke-width="10"/>
        <circle cx="-38" cy="0" r="11" fill="none" stroke="rgba(234,214,204,0.86)" stroke-width="5"/>
        <rect x="-6" y="-8" width="92" height="16" rx="6" fill="rgba(234,214,204,0.94)"/>
        <rect x="52" y="8" width="14" height="16" rx="2.4" fill="rgba(234,214,204,0.94)"/>
        <rect x="72" y="-16" width="14" height="16" rx="2.4" fill="rgba(234,214,204,0.94)"/>
      </g>
      <rect x="8" y="8" width="314" height="314" rx="18" fill="none" stroke="rgba(241, 222, 214, 0.22)" stroke-width="2.6"/>
    </svg>
  `);
}

function normalizeHexitamaActionPatternIndices(value) {
  const source = Array.isArray(value) ? value : [];
  const normalized = [];
  const seen = new Set();
  for (const item of source) {
    const numeric = Number(item);
    if (!Number.isInteger(numeric) || numeric < 1 || numeric > 18 || seen.has(numeric)) {
      continue;
    }
    seen.add(numeric);
    normalized.push(numeric);
  }
  return normalized;
}

const hexitamaPatternIndicesByFrontSrc = new Map();

function resolveHexitamaActionPatternIndicesFromFrontSrc(frontSrc = '') {
  const normalizedFrontSrc = String(frontSrc || '').trim();
  if (!normalizedFrontSrc) {
    return [];
  }
  if (hexitamaPatternIndicesByFrontSrc.has(normalizedFrontSrc)) {
    const cached = hexitamaPatternIndicesByFrontSrc.get(normalizedFrontSrc);
    return Array.isArray(cached) ? [...cached] : [];
  }
  for (const pattern of HEXITAMA_ACTION_CARD_PATTERNS) {
    const normalizedPattern = normalizeHexitamaActionPatternIndices(pattern);
    const candidateSrc = createHexitamaActionCardFaceSvgDataUri(normalizedPattern);
    if (candidateSrc === normalizedFrontSrc) {
      hexitamaPatternIndicesByFrontSrc.set(normalizedFrontSrc, normalizedPattern);
      return [...normalizedPattern];
    }
  }
  hexitamaPatternIndicesByFrontSrc.set(normalizedFrontSrc, []);
  return [];
}

function getHexitamaActionPatternIndicesForCard(cardState) {
  if (!cardState || typeof cardState !== 'object') {
    return [];
  }
  const explicit = normalizeHexitamaActionPatternIndices(cardState.hexitamaPatternIndices);
  if (explicit.length > 0) {
    return explicit;
  }
  return resolveHexitamaActionPatternIndicesFromFrontSrc(cardState.frontSrc || '');
}

function createHexitamaActionCardFaceSvgDataUri(patternIndices = []) {
  const selectedIndices = new Set(normalizeHexitamaActionPatternIndices(patternIndices));
  const cardSize = 360;
  const cardCenterX = cardSize / 2;
  const cardCenterY = cardSize / 2;
  const outerRadius = 170;
  const innerRadius = 28;
  const innerRotationDeg = HEXITAMA_TILE_ROTATION_DEG;
  const bottomDotRadius = 5;
  const bottomDotY = cardCenterY + outerRadius - 22;
  const colStep = innerRadius * 1.5;
  const rowStep = Math.sqrt(3) * innerRadius;
  const topY = cardCenterY - rowStep * 2;
  const centerHexY = topY + rowStep * 2;
  let cellsMarkup = '';
  for (const cell of HEXITAMA_CARD_CELL_LAYOUT) {
    const colOffset = Number(cell.colIndex) - 2;
    const x = cardCenterX + colOffset * colStep;
    const y = topY + Number(cell.rowValue) * rowStep;
    const isSelected = selectedIndices.has(Number(cell.index));
    const fill = isSelected ? '#2a47ff' : '#f2f4fa';
    const stroke = isSelected ? 'rgba(192, 212, 255, 0.46)' : 'rgba(20, 28, 54, 0.38)';
    cellsMarkup += `
      <polygon
        points="${getHexitamaHexPolygonPoints(x, y, innerRadius * 0.98, innerRotationDeg)}"
        fill="${fill}"
        stroke="${stroke}"
        stroke-width="1.85"
        vector-effect="non-scaling-stroke"
      />
    `;
  }
  const dataUri = encodeSvgDataUri(`
    <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${cardSize} ${cardSize}">
      <polygon
        points="${getHexitamaHexPolygonPoints(cardCenterX, cardCenterY, outerRadius, HEXITAMA_SLOT_ROTATION_DEG)}"
        fill="#4f2f20"
        stroke="#000000"
        stroke-width="3.1"
        stroke-linejoin="round"
        vector-effect="non-scaling-stroke"
      />
      <polygon
        points="${getHexitamaHexPolygonPoints(cardCenterX, centerHexY, innerRadius * 1.04, innerRotationDeg)}"
        fill="#ef2020"
        stroke="rgba(255, 191, 191, 0.45)"
        stroke-width="1.9"
        vector-effect="non-scaling-stroke"
      />
      ${cellsMarkup}
      <circle
        cx="${cardCenterX}"
        cy="${bottomDotY}"
        r="${bottomDotRadius}"
        fill="rgba(248, 248, 248, 0.96)"
      />
    </svg>
  `);
  const normalizedPattern = normalizeHexitamaActionPatternIndices(patternIndices);
  if (normalizedPattern.length > 0) {
    hexitamaPatternIndicesByFrontSrc.set(dataUri, normalizedPattern);
  }
  return dataUri;
}

function pickRandomHexitamaActionPatterns(count = HEXITAMA_CARD_SLOT_KEYS.length) {
  const limit = clamp(Math.floor(Number(count) || HEXITAMA_CARD_SLOT_KEYS.length), 1, HEXITAMA_ACTION_CARD_PATTERNS.length);
  const indices = Array.from({ length: HEXITAMA_ACTION_CARD_PATTERNS.length }, (_, index) => index);
  for (let index = indices.length - 1; index > 0; index -= 1) {
    const swapIndex = Math.floor(Math.random() * (index + 1));
    const temp = indices[index];
    indices[index] = indices[swapIndex];
    indices[swapIndex] = temp;
  }
  const selected = [];
  for (let index = 0; index < limit; index += 1) {
    selected.push(HEXITAMA_ACTION_CARD_PATTERNS[indices[index]] || HEXITAMA_ACTION_CARD_PATTERNS[0]);
  }
  return selected;
}

