function syncDeleteCursorLock() {
  const shouldHide = Boolean(deleteModeEnabled);
  const lockTargets = [document.documentElement, document.body, tableRoot];
  for (const target of lockTargets) {
    if (!(target instanceof HTMLElement)) {
      continue;
    }
    target.classList.toggle('tabletop-delete-cursor-hidden', shouldHide);
    if (shouldHide) {
      target.style.setProperty('cursor', 'none', 'important');
    } else {
      target.style.removeProperty('cursor');
    }
  }
}
let setDrawModeEnabled = (enabled) => {
  drawModeEnabled = Boolean(enabled);
  syncDrawModeUi();
};
let setDeleteModeEnabled = (enabled) => {
  const nextEnabled = Boolean(enabled);
  deleteModeEnabled = nextEnabled;
  if (nextEnabled && drawModeEnabled) {
    setDrawModeEnabled(false);
  }
  tableRoot?.classList.toggle('is-delete-mode', deleteModeEnabled);
  syncDeleteModeActionsUi();
  syncSelectionDeleteButtonUi();
  syncDeleteCursorLock();
};

const camera = {
  scale: 1,
  panX: 0,
  panY: 0
};
let lastAppliedGridScale = Number.NaN;
let lowZoomStabilityModeActive = false;

function getMonsPieceImageRendering() {
  return camera.scale >= MONS_PIECE_PIXELATE_SCALE ? 'pixelated' : 'auto';
}

function getMonsColumnLabelText(index, flipped = false) {
  const normalizedIndex = clamp(Math.round(Number(index) || 0), 0, MONS_BOARD_SIZE - 1);
  const labelIndex = flipped ? MONS_BOARD_SIZE - 1 - normalizedIndex : normalizedIndex;
  return MONS_BOARD_LABELS[labelIndex] || '';
}

function getMonsRowLabelText(index, flipped = false) {
  const normalizedIndex = clamp(Math.round(Number(index) || 0), 0, MONS_BOARD_SIZE - 1);
  return flipped ? String(normalizedIndex + 1) : String(MONS_BOARD_SIZE - normalizedIndex);
}

function getTaflColumnLabelText(index) {
  const normalizedIndex = clamp(Math.round(Number(index) || 0), 0, TAFL_BOARD_SIZE - 1);
  return MONS_BOARD_LABELS[normalizedIndex] || '';
}

function getTaflRowLabelText(index) {
  const normalizedIndex = clamp(Math.round(Number(index) || 0), 0, TAFL_BOARD_SIZE - 1);
  return String(TAFL_BOARD_SIZE - normalizedIndex);
}

function normalizeGoBoardSize(value) {
  const numeric = Math.round(Number(value));
  if (GO_BOARD_SIZE_OPTIONS.includes(numeric)) {
    return numeric;
  }
  return GO_BOARD_SIZE_DEFAULT;
}

function getGoStarPointCoords(boardSize = GO_BOARD_SIZE_DEFAULT) {
  const normalizedBoardSize = normalizeGoBoardSize(boardSize);
  return GO_STAR_POINT_COORDS_BY_SIZE[normalizedBoardSize] || GO_STAR_POINT_COORDS_BY_SIZE[GO_BOARD_SIZE_DEFAULT];
}

function getGoColumnLabelText(index, boardSize = GO_BOARD_SIZE_DEFAULT) {
  const normalizedBoardSize = normalizeGoBoardSize(boardSize);
  const normalizedIndex = clamp(Math.round(Number(index) || 0), 0, normalizedBoardSize - 1);
  return GO_BOARD_LABELS[normalizedIndex] || '';
}

function getGoRowLabelText(index, boardSize = GO_BOARD_SIZE_DEFAULT) {
  const normalizedBoardSize = normalizeGoBoardSize(boardSize);
  const normalizedIndex = clamp(Math.round(Number(index) || 0), 0, normalizedBoardSize - 1);
  return String(normalizedBoardSize - normalizedIndex);
}

function setMonsBoardCoordinatesVisibility(boardSvgElement, shouldShow = true) {
  if (!(boardSvgElement instanceof SVGElement)) {
    return;
  }
  boardSvgElement.classList.toggle('is-coordinates-hidden', shouldShow !== true);
}

function syncMonsBoardCoordinateLabels(boardSvgElement, flipped) {
  if (!(boardSvgElement instanceof SVGElement)) {
    return;
  }
  const labels = boardSvgElement.querySelectorAll('.mons-board-coordinate[data-mons-axis][data-mons-index]');
  for (const label of labels) {
    const axis = label.getAttribute('data-mons-axis');
    const index = Number(label.getAttribute('data-mons-index'));
    if (!Number.isFinite(index)) {
      continue;
    }
    if (axis === 'col') {
      label.textContent = getMonsColumnLabelText(index, flipped);
    } else if (axis === 'row') {
      label.textContent = getMonsRowLabelText(index, flipped);
    }
    if (flipped) {
      label.setAttribute('transform', `rotate(180 ${MONS_BOARD_CENTER} ${MONS_BOARD_CENTER})`);
    } else {
      label.removeAttribute('transform');
    }
  }
}

function isMonsBoardFlipped(gamePayload = monsGameState) {
  return gamePayload?.flipped === true;
}

function applyMonsBoardOrientation(boardSvgElement, flipped) {
  if (!(boardSvgElement instanceof SVGElement)) {
    return;
  }
  if (flipped) {
    boardSvgElement.style.transformOrigin = '50% 50%';
    boardSvgElement.style.transform = 'rotate(180deg)';
  } else {
    boardSvgElement.style.transform = '';
    boardSvgElement.style.transformOrigin = '';
  }
  syncMonsBoardCoordinateLabels(boardSvgElement, flipped);
}

function normalizedToWorld(position) {
  return {
    x: clamp(position.x, 0, 1) * WORLD_WIDTH,
    y: clamp(position.y, 0, 1) * WORLD_HEIGHT
  };
}

function worldToNormalized(position) {
  return {
    x: clamp(position.x / WORLD_WIDTH, 0, 1),
    y: clamp(position.y / WORLD_HEIGHT, 0, 1)
  };
}

function worldToScreen(position) {
  return {
    x: position.x * camera.scale + camera.panX,
    y: position.y * camera.scale + camera.panY
  };
}

function getScreenPoint(clientX, clientY) {
  if (!tableRoot) {
    return null;
  }
  const rect = tableRoot.getBoundingClientRect();
  if (!rect.width || !rect.height) {
    return null;
  }
  return {
    x: clientX - rect.left,
    y: clientY - rect.top,
    rect
  };
}

function screenToWorldFromClient(clientX, clientY) {
  const screen = getScreenPoint(clientX, clientY);
  if (!screen) {
    return null;
  }
  return {
    x: (screen.x - camera.panX) / camera.scale,
    y: (screen.y - camera.panY) / camera.scale
  };
}

function snapToDevicePixel(value, min = 1) {
  const dpr = window.devicePixelRatio || 1;
  return Math.max(min, Math.round(value * dpr) / dpr);
}

function setElementStyleValue(element, property, value) {
  if (!element || !property) {
    return;
  }
  if (element.style[property] === value) {
    return;
  }
  element.style[property] = value;
}

function setElementStylePx(element, property, value) {
  setElementStyleValue(element, property, `${value}px`);
}

function setElementStyleCustomProperty(element, property, value) {
  if (!element || !property) {
    return;
  }
  if (element.style.getPropertyValue(property) === value) {
    return;
  }
  element.style.setProperty(property, value);
}

function getViewportWorldCenter() {
  if (!tableRoot) {
    return {
      x: WORLD_WIDTH / 2,
      y: WORLD_HEIGHT / 2
    };
  }
  const rect = tableRoot.getBoundingClientRect();
  if (!rect.width || !rect.height || !Number.isFinite(camera.scale) || camera.scale <= 0) {
    return {
      x: WORLD_WIDTH / 2,
      y: WORLD_HEIGHT / 2
    };
  }
  const centerScreenX = rect.width / 2;
  const centerScreenY = rect.height / 2;
  return {
    x: clamp((centerScreenX - camera.panX) / camera.scale, 0, WORLD_WIDTH),
    y: clamp((centerScreenY - camera.panY) / camera.scale, 0, WORLD_HEIGHT)
  };
}

function getViewportWorldBounds(extraScreenMarginPx = 0) {
  const viewportWidth = tableRoot?.clientWidth || window.innerWidth || 0;
  const viewportHeight = tableRoot?.clientHeight || window.innerHeight || 0;
  const marginPx = Math.max(0, Number(extraScreenMarginPx) || 0);
  const effectiveScale = Math.max(0.0001, Number(camera.scale) || 1);
  const minX = (-camera.panX - marginPx) / effectiveScale;
  const minY = (-camera.panY - marginPx) / effectiveScale;
  const maxX = (viewportWidth - camera.panX + marginPx) / effectiveScale;
  const maxY = (viewportHeight - camera.panY + marginPx) / effectiveScale;
  return {
    minX,
    minY,
    maxX,
    maxY
  };
}

function isWorldRectLikelyVisible(centerX, centerY, width, height, extraScreenMarginPx = VIEWPORT_CULL_MARGIN_PX) {
  const bounds = getViewportWorldBounds(extraScreenMarginPx);
  return isWorldRectVisibleWithinBounds(bounds, centerX, centerY, width, height);
}

function isWorldRectVisibleWithinBounds(bounds, centerX, centerY, width, height) {
  if (!bounds || typeof bounds !== 'object') {
    return false;
  }
  const halfWidth = Math.max(0, Number(width) || 0) / 2;
  const halfHeight = Math.max(0, Number(height) || 0) / 2;
  const left = Number(centerX) - halfWidth;
  const right = Number(centerX) + halfWidth;
  const top = Number(centerY) - halfHeight;
  const bottom = Number(centerY) + halfHeight;
  return !(right < bounds.minX || left > bounds.maxX || bottom < bounds.minY || top > bounds.maxY);
}

function markCameraInteractionActive() {
  lastCameraInteractionAt = Date.now();
}

function isCameraInteractionActive(now = Date.now()) {
  return now - lastCameraInteractionAt <= CAMERA_INTERACTION_ACTIVE_MS;
}

function isLowZoomStabilityActive(scale = camera.scale) {
  const numericScale = Number(scale);
  if (!Number.isFinite(numericScale)) {
    return lowZoomStabilityModeActive;
  }
  if (lowZoomStabilityModeActive) {
    if (numericScale >= LOW_ZOOM_STABILITY_EXIT_SCALE) {
      lowZoomStabilityModeActive = false;
    }
  } else if (numericScale <= LOW_ZOOM_STABILITY_ENTER_SCALE) {
    lowZoomStabilityModeActive = true;
  }
  return lowZoomStabilityModeActive;
}

function shouldHideSecondaryModuleControlsAtLowZoom(scale = camera.scale) {
  const numericScale = Number(scale);
  if (!Number.isFinite(numericScale)) {
    return false;
  }
  return numericScale <= MODULE_SECONDARY_CONTROL_HIDE_SCALE;
}

function getViewportCullMarginPx() {
  if (isLowZoomStabilityActive()) {
    return Math.max(LOW_ZOOM_CULL_MARGIN_PX, VIEWPORT_CULL_MARGIN_ACTIVE_PX);
  }
  return isCameraInteractionActive() ? VIEWPORT_CULL_MARGIN_ACTIVE_PX : VIEWPORT_CULL_MARGIN_PX;
}

function getViewportGameCullMarginPx() {
  if (isLowZoomStabilityActive()) {
    return Math.max(LOW_ZOOM_CULL_MARGIN_PX_GAMES, VIEWPORT_CULL_MARGIN_ACTIVE_PX);
  }
  return Math.max(VIEWPORT_CULL_MARGIN_PX_GAMES, getViewportCullMarginPx());
}

function shouldKeepMountedDuringOffscreenGrace(offscreenSinceById, itemId, now = Date.now()) {
  if (!(offscreenSinceById instanceof Map)) {
    return false;
  }
  const normalizedItemId = String(itemId || '').trim();
  if (!normalizedItemId) {
    return false;
  }
  const previousSince = Number(offscreenSinceById.get(normalizedItemId) || 0);
  if (!previousSince) {
    offscreenSinceById.set(normalizedItemId, now);
    return true;
  }
  if (isLowZoomStabilityActive()) {
    return true;
  }
  if (isCameraInteractionActive(now)) {
    return true;
  }
  return now - previousSince < OFFSCREEN_UNMOUNT_GRACE_MS;
}

function clampCameraToViewport() {
  if (!tableRoot) {
    return;
  }

  const rect = tableRoot.getBoundingClientRect();
  if (!rect.width || !rect.height) {
    return;
  }

  const worldScreenWidth = WORLD_WIDTH * camera.scale;
  const worldScreenHeight = WORLD_HEIGHT * camera.scale;
  const marginScreen = WORLD_PAN_MARGIN * camera.scale;

  if (worldScreenWidth + marginScreen * 2 <= rect.width) {
    camera.panX = (rect.width - worldScreenWidth) / 2;
  } else {
    camera.panX = clamp(camera.panX, rect.width - worldScreenWidth - marginScreen, marginScreen);
  }

  if (worldScreenHeight + marginScreen * 2 <= rect.height) {
    camera.panY = (rect.height - worldScreenHeight) / 2;
  } else {
    camera.panY = clamp(camera.panY, rect.height - worldScreenHeight - marginScreen, marginScreen);
  }
}

function readStoredCameraView() {
  try {
    const raw = localStorage.getItem(cameraViewStorageKey);
    if (!raw) {
      return null;
    }
    const parsed = JSON.parse(raw);
    const scale = Number(parsed?.scale);
    const panX = Number(parsed?.panX);
    const panY = Number(parsed?.panY);
    if (!Number.isFinite(scale) || !Number.isFinite(panX) || !Number.isFinite(panY)) {
      return null;
    }
    return {
      scale: clamp(scale, MIN_SCALE, MAX_SCALE),
      panX,
      panY
    };
  } catch {
    return null;
  }
}

function persistCameraViewNow() {
  try {
    localStorage.setItem(
      cameraViewStorageKey,
      JSON.stringify({
        scale: Number(camera.scale.toFixed(5)),
        panX: Number(camera.panX.toFixed(2)),
        panY: Number(camera.panY.toFixed(2))
      })
    );
  } catch {
    // Ignore storage failures.
  }
}

function scheduleCameraViewPersist() {
  if (cameraPersistTimerId) {
    window.clearTimeout(cameraPersistTimerId);
  }
  cameraPersistTimerId = window.setTimeout(() => {
    cameraPersistTimerId = 0;
    persistCameraViewNow();
  }, 120);
}

function positionDot(dot) {
  const normalizedX = Number(dot.dataset.normalizedX ?? 0.5);
  const normalizedY = Number(dot.dataset.normalizedY ?? 0.5);
  const world = normalizedToWorld({ x: normalizedX, y: normalizedY });
  const screen = worldToScreen(world);
  setElementStylePx(dot, 'left', screen.x);
  setElementStylePx(dot, 'top', screen.y);
  return { world, screen };
}

function buildRemoteCursorVisibilityContext() {
  const codegameGridBounds = [];
  const codegameGridDimensions = getCodegameGridWorldDimensions();
  for (const rawDeckId of getDeckIdsInRoom()) {
    const deckId = normalizeDeckId(rawDeckId);
    if (getDeckKind(deckId) !== DECK_KIND_CODEGAME) {
      continue;
    }
    const state = getDeckStateById(deckId);
    if (!state || state.codegameGridActive !== true) {
      continue;
    }
    const center = getCodegameGridCenterPosition(deckId);
    codegameGridBounds.push({
      deckId,
      left: center.x - codegameGridDimensions.width / 2,
      right: center.x + codegameGridDimensions.width / 2,
      top: center.y - codegameGridDimensions.height / 2,
      bottom: center.y + codegameGridDimensions.height / 2
    });
  }

  const keyDeckIdsByOwner = new Map();
  for (const [cardId, cardState] of cards.entries()) {
    if (!isCodegameKeyCardState(cardState)) {
      continue;
    }
    const ownerId = String(getCardHandOwnerId(cardState) || '').trim();
    if (!ownerId) {
      continue;
    }
    const deckId = getCardDeckId(cardState, cardId);
    if (!deckId) {
      continue;
    }
    let ownerDeckIds = keyDeckIdsByOwner.get(ownerId);
    if (!ownerDeckIds) {
      ownerDeckIds = new Set();
      keyDeckIdsByOwner.set(ownerId, ownerDeckIds);
    }
    ownerDeckIds.add(deckId);
  }

  const arcadeScreenRects = [];
  if (tableRoot instanceof HTMLElement) {
    const screenElements = tableRoot.querySelectorAll('.table-die.table-die-arcade .table-arcade-screen');
    for (const screenElement of screenElements) {
      if (!(screenElement instanceof HTMLElement)) {
        continue;
      }
      const rect = screenElement.getBoundingClientRect();
      if (rect.width <= 0 || rect.height <= 0) {
        continue;
      }
      arcadeScreenRects.push(rect);
    }
  }

  return {
    codegameGridBounds,
    keyDeckIdsByOwner,
    arcadeScreenRects
  };
}

function isWorldPointInsideCodegameGridForOwner(x, y, ownerId, context) {
  if (!context || !ownerId) {
    return false;
  }
  const ownerDeckIds = context.keyDeckIdsByOwner.get(ownerId);
  if (!(ownerDeckIds instanceof Set) || ownerDeckIds.size === 0) {
    return false;
  }
  for (const gridBounds of context.codegameGridBounds) {
    if (!ownerDeckIds.has(gridBounds.deckId)) {
      continue;
    }
    if (
      x >= gridBounds.left &&
      x <= gridBounds.right &&
      y >= gridBounds.top &&
      y <= gridBounds.bottom
    ) {
      return true;
    }
  }
  return false;
}

function isScreenPointInsideAnyArcadeScreen(x, y, context) {
  if (!context) {
    return false;
  }
  for (const rect of context.arcadeScreenRects) {
    if (x >= rect.left && x <= rect.right && y >= rect.top && y <= rect.bottom) {
      return true;
    }
  }
  return false;
}

function applyRemoteCursorContextVisual(dot, dotPosition = null, context = null) {
  if (!(dot instanceof HTMLElement)) {
    return;
  }
  const visibilityContext = context || buildRemoteCursorVisibilityContext();
  const cursorPosition =
    dotPosition && dotPosition.world && dotPosition.screen
      ? dotPosition
      : positionDot(dot);
  const ownerId = String(dot.dataset.playerToken || dot.dataset.clientId || '').trim();
  const hiddenForCodegameKey =
    ownerId &&
    isWorldPointInsideCodegameGridForOwner(
      cursorPosition.world.x,
      cursorPosition.world.y,
      ownerId,
      visibilityContext
    );
  const dimmedForArcadeScreen =
    !hiddenForCodegameKey &&
    isScreenPointInsideAnyArcadeScreen(
      cursorPosition.screen.x,
      cursorPosition.screen.y,
      visibilityContext
    );
  const targetOpacity = hiddenForCodegameKey ? '0' : dimmedForArcadeScreen ? '0.3' : '';
  if (dot.dataset.contextOpacity !== targetOpacity) {
    dot.dataset.contextOpacity = targetOpacity;
    setElementStyleValue(dot, 'opacity', targetOpacity);
  }
}

function renderAllDots() {
  if (dots.size === 0) {
    return;
  }
  const visibilityContext = buildRemoteCursorVisibilityContext();
  for (const dot of dots.values()) {
    const dotPosition = positionDot(dot);
    applyRemoteCursorContextVisual(dot, dotPosition, visibilityContext);
  }
}

function setDiscardReturnAnimating(cardId, active) {
  const existingTimer = discardReturnAnimationTimers.get(cardId);
  if (existingTimer) {
    window.clearTimeout(existingTimer);
    discardReturnAnimationTimers.delete(cardId);
  }

  if (!active) {
    discardReturnAnimatingCardIds.delete(cardId);
    return;
  }

  discardReturnAnimatingCardIds.add(cardId);
  const timer = window.setTimeout(() => {
    discardReturnAnimationTimers.delete(cardId);
    if (!discardReturnAnimatingCardIds.has(cardId)) {
      return;
    }
    discardReturnAnimatingCardIds.delete(cardId);
    renderCardElement(cardId);
  }, DISCARD_RETURN_ANIMATION_MS + 40);
  discardReturnAnimationTimers.set(cardId, timer);
}

function normalizeDeckId(rawDeckId) {
  const normalized = String(rawDeckId || '').trim().toLowerCase();
  if (!normalized) {
    return DECK_KEY;
  }
  return normalized;
}

function normalizeOptionalDeckId(rawDeckId) {
  const normalized = String(rawDeckId || '').trim().toLowerCase();
  return normalized || '';
}

function isStandardDeckInstanceId(rawDeckId) {
  const deckId = normalizeDeckId(rawDeckId);
  return (
    deckId === DECK_KEY ||
    deckId === POKER_DECK_KEY ||
    deckId === CODEGAME_DECK_KEY ||
    deckId.startsWith(`${DECK_KEY}-copy-`) ||
    deckId.startsWith(`${POKER_DECK_KEY}-copy-`) ||
    deckId.startsWith(`${CODEGAME_DECK_KEY}-copy-`)
  );
}

function inferDeckIdFromCardId(cardId) {
  const normalizedCardId = String(cardId || '').trim().toLowerCase();
  if (!normalizedCardId) {
    return '';
  }
  const match = normalizedCardId.match(/^(.+)-\d{3}$/);
  if (!match || !match[1]) {
    return '';
  }
  const candidateDeckId = normalizeDeckId(match[1]);
  return isStandardDeckInstanceId(candidateDeckId) ? candidateDeckId : '';
}

function getCardDeckInstanceId(cardId, cardState) {
  const inferredDeckId = inferDeckIdFromCardId(cardId);
  if (inferredDeckId) {
    return inferredDeckId;
  }
  const explicitDeckId = normalizeOptionalDeckId(cardState?.deckId || '');
  return isStandardDeckInstanceId(explicitDeckId) ? explicitDeckId : '';
}

function isPokerDeckId(rawDeckId) {
  const normalizedDeckId = normalizeDeckId(rawDeckId);
  return normalizedDeckId === POKER_DECK_KEY || normalizedDeckId.startsWith(`${POKER_DECK_KEY}-copy-`);
}

function isCodegameDeckId(rawDeckId) {
  const normalizedDeckId = normalizeDeckId(rawDeckId);
  return normalizedDeckId === CODEGAME_DECK_KEY || normalizedDeckId.startsWith(`${CODEGAME_DECK_KEY}-copy-`);
}

function isCoolDeckId(rawDeckId) {
  const normalizedDeckId = normalizeDeckId(rawDeckId);
  return normalizedDeckId === DECK_KEY || normalizedDeckId.startsWith(`${DECK_KEY}-copy-`);
}

function isHexitamaCardDeckId(rawDeckId) {
  const normalizedDeckId = normalizeOptionalDeckId(rawDeckId);
  return Boolean(normalizedDeckId) && normalizedDeckId.startsWith(`${HEXITAMA_CARD_ID_PREFIX}-`);
}

function normalizeCardFamily(rawCardFamily, options = {}) {
  const normalizedFamily = String(rawCardFamily || '').trim().toLowerCase();
  if (normalizedFamily === CARD_FAMILY_COOL || normalizedFamily === DECK_KEY) {
    return CARD_FAMILY_COOL;
  }
  if (normalizedFamily === CARD_FAMILY_POKER || normalizedFamily === POKER_DECK_KEY) {
    return CARD_FAMILY_POKER;
  }
  if (normalizedFamily === CARD_FAMILY_CODEGAME || normalizedFamily === CODEGAME_DECK_KEY) {
    return CARD_FAMILY_CODEGAME;
  }
  if (normalizedFamily === CARD_FAMILY_HEXITAMA || normalizedFamily === HEXITAMA_GAME_KEY) {
    return CARD_FAMILY_HEXITAMA;
  }

  if (String(options.componentType || '').trim()) {
    return '';
  }
  if (options.hexitamaCard === true) {
    return CARD_FAMILY_HEXITAMA;
  }

  const normalizedDeckId = normalizeOptionalDeckId(options.deckId || '');
  if (isCoolDeckId(normalizedDeckId)) {
    return CARD_FAMILY_COOL;
  }
  if (isPokerDeckId(normalizedDeckId)) {
    return CARD_FAMILY_POKER;
  }
  if (isCodegameDeckId(normalizedDeckId)) {
    return CARD_FAMILY_CODEGAME;
  }

  if (normalizeCoolJpegsAuctionType(options.auctionType || '') || normalizeCoolJpegsArtistLabel(options.artist || '')) {
    return CARD_FAMILY_COOL;
  }

  const rawFrontSrc = String(options.frontSrc || '').trim();
  if (rawFrontSrc && (rawFrontSrc.startsWith(CARD_FRONT_HIGH_RES_PREFIX) || rawFrontSrc.startsWith(CARD_FRONT_LOW_RES_PREFIX))) {
    return CARD_FAMILY_COOL;
  }

  const parsedCardNumber = getCoolJpegsCardNumberFromCardId(options.cardId || '');
  if (Number.isInteger(parsedCardNumber) && parsedCardNumber >= 1000 && parsedCardNumber <= 1999) {
    return CARD_FAMILY_COOL;
  }

  return '';
}

function getCardFamily(cardState, cardId = '') {
  const normalizedCardId = String(cardId || '').trim();
  const deckIdForFamily =
    getCardDeckInstanceId(normalizedCardId, cardState) ||
    normalizeOptionalDeckId(cardState?.deckId || '');
  return normalizeCardFamily(cardState?.cardFamily, {
    deckId: deckIdForFamily,
    hexitamaCard: cardState?.hexitamaCard === true,
    componentType: cardState?.componentType || '',
    auctionType: cardState?.auctionType || '',
    artist: cardState?.artist || '',
    frontSrc: cardState?.frontSrc || '',
    cardId: normalizedCardId
  });
}

function isLikelyCoolJpegsCardState(cardState, cardId = '') {
  return getCardFamily(cardState, cardId) === CARD_FAMILY_COOL;
}

function getPrimaryDeckIdForCardFamily(cardFamily = '') {
  const normalizedFamily = normalizeCardFamily(cardFamily);
  if (normalizedFamily === CARD_FAMILY_COOL) {
    return DECK_KEY;
  }
  if (normalizedFamily === CARD_FAMILY_POKER) {
    return POKER_DECK_KEY;
  }
  if (normalizedFamily === CARD_FAMILY_CODEGAME) {
    return CODEGAME_DECK_KEY;
  }
  return '';
}

function resolveStandardDeckId(rawDeckId = '', fallbackCardFamily = '') {
  const normalizedDeckId = normalizeOptionalDeckId(rawDeckId);
  if (isStandardDeckInstanceId(normalizedDeckId)) {
    return normalizedDeckId;
  }
  return getPrimaryDeckIdForCardFamily(fallbackCardFamily);
}

function getCardDeckId(cardState, cardId = '') {
  if (!cardState || typeof cardState !== 'object') {
    return '';
  }
  if (isVisualImageComponentCard(cardState)) {
    return '';
  }
  const normalizedCardId = String(cardId || '').trim();
  const standardDeckInstanceId = getCardDeckInstanceId(normalizedCardId, cardState);
  if (standardDeckInstanceId) {
    return standardDeckInstanceId;
  }
  return resolveStandardDeckId(cardState?.deckId || '', getCardFamily(cardState, normalizedCardId));
}

function deckHasCoolJpegsCardData(deckId = activeDeckId) {
  const normalizedDeckId = normalizeOptionalDeckId(deckId);
  if (!normalizedDeckId) {
    return false;
  }
  const deckCardEntries = getDeckCardEntries(normalizedDeckId);
  if (!deckCardEntries.length) {
    return false;
  }
  for (const [cardId, cardState] of deckCardEntries) {
    if (isLikelyCoolJpegsCardState(cardState, cardId)) {
      return true;
    }
  }
  return false;
}

function normalizeDeckKind(rawKind, deckId = '') {
  // Deck ID is canonical for deck families; prefer it over persisted `kind` to
  // recover from stale/corrupted kind values.
  if (isHexitamaCardDeckId(deckId)) {
    return '';
  }
  if (isPokerDeckId(deckId)) {
    return DECK_KIND_POKER;
  }
  if (isCodegameDeckId(deckId)) {
    return DECK_KIND_CODEGAME;
  }
  if (isCoolDeckId(deckId)) {
    return DECK_KIND_COOL;
  }

  const normalizedKind = String(rawKind || '').trim().toLowerCase();
  if (normalizedKind === DECK_KIND_POKER || normalizedKind === POKER_DECK_KEY) {
    return DECK_KIND_POKER;
  }
  if (normalizedKind === DECK_KIND_CODEGAME || normalizedKind === CODEGAME_DECK_KEY) {
    return DECK_KIND_CODEGAME;
  }
  if (normalizedKind === DECK_KIND_COOL || normalizedKind === DECK_KEY) {
    return DECK_KIND_COOL;
  }
  return '';
}

function normalizeMonsGameId(rawMonsGameId) {
  const normalized = String(rawMonsGameId || '').trim().toLowerCase();
  if (!normalized) {
    return MONS_GAME_KEY;
  }
  return normalized;
}

function normalizeTaflGameId(rawTaflGameId) {
  const normalized = String(rawTaflGameId || '').trim().toLowerCase();
  if (!normalized) {
    return TAFL_GAME_KEY;
  }
  return normalized;
}

function normalizeGoGameId(rawGoGameId) {
  const normalized = String(rawGoGameId || '').trim().toLowerCase();
  if (!normalized) {
    return GO_GAME_KEY;
  }
  return normalized;
}

function normalizeHexitamaGameId(rawHexitamaGameId) {
  const normalized = String(rawHexitamaGameId || '').trim().toLowerCase();
  if (!normalized) {
    return HEXITAMA_GAME_KEY;
  }
  return normalized;
}

function getHexitamaCardDeckId(gameId = activeHexitamaGameId) {
  const normalizedGameId = normalizeHexitamaGameId(gameId);
  return `${HEXITAMA_CARD_ID_PREFIX}-${normalizedGameId}`;
}

function getHexitamaActionCardIds(gameId = activeHexitamaGameId) {
  const normalizedGameId = normalizeHexitamaGameId(gameId);
  return HEXITAMA_CARD_SLOT_KEYS.map((slotKey) => `${HEXITAMA_CARD_ID_PREFIX}-${normalizedGameId}-${slotKey}`);
}

function getHexitamaCardSlotKeyFromCardId(cardId = '') {
  const normalizedCardId = String(cardId || '').trim().toLowerCase();
  if (!normalizedCardId.startsWith(`${HEXITAMA_CARD_ID_PREFIX}-`)) {
    return '';
  }
  for (const slotKey of HEXITAMA_CARD_SLOT_KEYS) {
    if (normalizedCardId.endsWith(`-${slotKey}`)) {
      return slotKey;
    }
  }
  return '';
}

function getHexitamaCardGameIdFromCardId(cardId = '') {
  const normalizedCardId = String(cardId || '').trim().toLowerCase();
  const prefix = `${HEXITAMA_CARD_ID_PREFIX}-`;
  if (!normalizedCardId.startsWith(prefix)) {
    return '';
  }
  const slotKey = getHexitamaCardSlotKeyFromCardId(normalizedCardId);
  if (!slotKey) {
    return '';
  }
  const suffix = `-${slotKey}`;
  const rawGameId = normalizedCardId.slice(prefix.length, -suffix.length);
  return rawGameId ? normalizeHexitamaGameId(rawGameId) : '';
}

function getHexitamaActionCardIdsForGame(gameId = activeHexitamaGameId) {
  const normalizedGameId = normalizeHexitamaGameId(gameId);
  const ids = new Set(getHexitamaActionCardIds(normalizedGameId));
  for (const [cardId, cardState] of cards.entries()) {
    if (!isHexitamaActionCardState(cardState, cardId)) {
      continue;
    }
    const cardGameId = normalizeHexitamaGameId(
      String(cardState?.hexitamaGameId || '').trim() || getHexitamaCardGameIdFromCardId(cardId)
    );
    if (cardGameId !== normalizedGameId) {
      continue;
    }
    ids.add(cardId);
  }
  return Array.from(ids);
}

function getHexitamaCardSlotKey(cardState, cardId = '', options = {}) {
  if (!isHexitamaActionCardState(cardState, cardId)) {
    return '';
  }
  const rawSlotKey = String(cardState?.hexitamaSlotKey || '').trim().toLowerCase();
  if (HEXITAMA_CARD_SLOT_KEYS.includes(rawSlotKey)) {
    return rawSlotKey;
  }
  if (options?.allowInfer !== true) {
    return '';
  }
  const inferredSlotKey = getHexitamaCardSlotKeyFromCardId(cardId);
  return HEXITAMA_CARD_SLOT_KEYS.includes(inferredSlotKey) ? inferredSlotKey : '';
}

function getHexitamaActionCardIdForSlot(gameId = activeHexitamaGameId, slotKey = '', excludedCardId = '') {
  const normalizedGameId = normalizeHexitamaGameId(gameId);
  const normalizedSlotKey = String(slotKey || '').trim().toLowerCase();
  const normalizedExcludedCardId = String(excludedCardId || '').trim();
  if (!HEXITAMA_CARD_SLOT_KEYS.includes(normalizedSlotKey)) {
    return '';
  }
  let matchedCardId = '';
  let matchedRank = 0;
  let topZ = Number.NEGATIVE_INFINITY;
  const slotCenter = getHexitamaActionCardWorldPosition(normalizedGameId, normalizedSlotKey);
  const slotProximityThreshold = Math.max(8, HEXITAMA_CARD_SIZE * 0.58);
  for (const [cardId, cardState] of cards.entries()) {
    if (!isHexitamaActionCardState(cardState, cardId)) {
      continue;
    }
    if (normalizedExcludedCardId && cardId === normalizedExcludedCardId) {
      continue;
    }
    const cardGameId = normalizeHexitamaGameId(
      String(cardState?.hexitamaGameId || '').trim() || getHexitamaCardGameIdFromCardId(cardId)
    );
    if (cardGameId !== normalizedGameId) {
      continue;
    }
    if (cardState.inDeck || cardState.inDiscard || cardState.inAuction || getCardHandOwnerId(cardState)) {
      continue;
    }
    const explicitSlotKey = getHexitamaCardSlotKey(cardState, cardId);
    const inferredSlotKey = getHexitamaCardSlotKey(cardState, cardId, { allowInfer: true });
    let slotMatchRank = 0;
    if (explicitSlotKey === normalizedSlotKey) {
      slotMatchRank = 3;
    } else if (inferredSlotKey === normalizedSlotKey) {
      slotMatchRank = 2;
    } else if (slotCenter) {
      const cardX = Number(cardState?.x);
      const cardY = Number(cardState?.y);
      if (Number.isFinite(cardX) && Number.isFinite(cardY)) {
        const distance = Math.hypot(cardX - slotCenter.x, cardY - slotCenter.y);
        if (distance <= slotProximityThreshold) {
          slotMatchRank = 1;
        }
      }
    }
    if (slotMatchRank <= 0) {
      continue;
    }
    const cardZ = Number(cardState?.z) || 0;
    if (
      !matchedCardId ||
      slotMatchRank > matchedRank ||
      (slotMatchRank === matchedRank && cardZ >= topZ)
    ) {
      matchedCardId = cardId;
      matchedRank = slotMatchRank;
      topZ = cardZ;
    }
  }
  return matchedCardId;
}

function isMonsGameId(rawGameId) {
  const normalized = normalizeMonsGameId(rawGameId);
  return normalized === MONS_GAME_KEY || normalized.startsWith(`${MONS_GAME_KEY}-copy-`);
}

function isTaflGameId(rawGameId) {
  const normalized = normalizeTaflGameId(rawGameId);
  return normalized === TAFL_GAME_KEY || normalized.startsWith(`${TAFL_GAME_KEY}-copy-`);
}

function isGoGameId(rawGameId) {
  const normalized = normalizeGoGameId(rawGameId);
  return normalized === GO_GAME_KEY || normalized.startsWith(`${GO_GAME_KEY}-copy-`);
}

function isHexitamaGameId(rawGameId) {
  const normalized = normalizeHexitamaGameId(rawGameId);
  return normalized === HEXITAMA_GAME_KEY || normalized.startsWith(`${HEXITAMA_GAME_KEY}-copy-`);
}

function setActiveDeckId(nextDeckId) {
  const normalizedDeckId = normalizeDeckId(nextDeckId);
  activeDeckId = normalizedDeckId;
  deckState = deckStatesById.get(normalizedDeckId) || null;
}

function setActiveMonsGameId(nextMonsGameId) {
  const previousMonsGameId = normalizeMonsGameId(activeMonsGameId);
  const normalizedMonsGameId = normalizeMonsGameId(nextMonsGameId);
  activeMonsGameId = normalizedMonsGameId;
  monsGameState = monsGameStatesById.get(normalizedMonsGameId) || null;
  if (normalizedMonsGameId !== previousMonsGameId) {
    monsSelectionPieceId = '';
    monsPendingSpiritPush = null;
    monsPendingDemonRebound = null;
    lastRenderedMonsMoveTick = Number(monsGameState?.moveTick) || 0;
    lastActiveMonsLayerRenderKey = '';
    lastActiveMonsHudRenderKey = '';
    lastActiveMonsBoardFlipped = null;
  }
}

function setActiveTaflGameId(nextTaflGameId) {
  const previousTaflGameId = normalizeTaflGameId(activeTaflGameId);
  const normalizedTaflGameId = normalizeTaflGameId(nextTaflGameId);
  activeTaflGameId = normalizedTaflGameId;
  taflGameState = taflGameStatesById.get(normalizedTaflGameId) || null;
  if (normalizedTaflGameId !== previousTaflGameId) {
    taflSelectionPieceId = '';
    taflSelectionGameId = '';
  }
}

function setActiveGoGameId(nextGoGameId) {
  const normalizedGoGameId = normalizeGoGameId(nextGoGameId);
  activeGoGameId = normalizedGoGameId;
  goGameState = goGameStatesById.get(normalizedGoGameId) || null;
}

function setActiveHexitamaGameId(nextHexitamaGameId) {
  const previousHexitamaGameId = normalizeHexitamaGameId(activeHexitamaGameId);
  const normalizedHexitamaGameId = normalizeHexitamaGameId(nextHexitamaGameId);
  activeHexitamaGameId = normalizedHexitamaGameId;
  hexitamaGameState = hexitamaGameStatesById.get(normalizedHexitamaGameId) || null;
  if (normalizedHexitamaGameId !== previousHexitamaGameId) {
    hexitamaSelectedPieceId = '';
    hexitamaSelectedPieceGameId = '';
    hexitamaBlockedPieceId = '';
    hexitamaBlockedPieceGameId = '';
    hexitamaMoveTargets = [];
    if (hexitamaSelectedActionGameId && normalizeHexitamaGameId(hexitamaSelectedActionGameId) !== normalizedHexitamaGameId) {
      hexitamaSelectedActionCardId = '';
      hexitamaSelectedActionGameId = '';
    }
  }
}

function getDeckStateById(deckId = activeDeckId) {
  const rawDeckId = arguments.length === 0 ? activeDeckId : deckId;
  const normalizedDeckId = normalizeOptionalDeckId(rawDeckId);
  if (!normalizedDeckId) {
    return null;
  }
  return deckStatesById.get(normalizedDeckId) || null;
}

function getDeckKind(deckId = activeDeckId) {
  const rawDeckId = arguments.length === 0 ? activeDeckId : deckId;
  const normalizedDeckId = normalizeOptionalDeckId(rawDeckId);
  if (!normalizedDeckId) {
    return '';
  }
  const normalizedKind = normalizeDeckKind(getDeckStateById(normalizedDeckId)?.kind, normalizedDeckId);
  if (!normalizedKind && deckHasCoolJpegsCardData(normalizedDeckId)) {
    return DECK_KIND_COOL;
  }
  return normalizedKind;
}

function deckSupportsAuction(deckId = activeDeckId) {
  return getDeckKind(deckId) === DECK_KIND_COOL;
}

function deckSupportsDiscard(deckId = activeDeckId) {
  const deckKind = getDeckKind(deckId);
  return deckKind === DECK_KIND_COOL || deckKind === DECK_KIND_POKER;
}

function deckSupportsShuffle(deckId = activeDeckId) {
  const deckKind = getDeckKind(deckId);
  return deckKind === DECK_KIND_COOL || deckKind === DECK_KIND_POKER;
}

function deckSupportsDealOne(deckId = activeDeckId) {
  const deckKind = getDeckKind(deckId);
  return deckKind === DECK_KIND_COOL || deckKind === DECK_KIND_POKER;
}

function deckShowsCountBadge(deckId = activeDeckId) {
  const deckKind = getDeckKind(deckId);
  return deckKind === DECK_KIND_COOL || deckKind === DECK_KIND_POKER;
}

function deckShowsPlayButton(deckId = activeDeckId) {
  return getDeckKind(deckId) === DECK_KIND_CODEGAME;
}

function deckShowsJoinButton(deckId = activeDeckId) {
  return getDeckKind(deckId) === DECK_KIND_COOL;
}

function setDeckPlayerJoinButtonMode(buttonElement, mode = 'join') {
  if (!(buttonElement instanceof HTMLElement)) {
    return;
  }
  const nextMode = mode === 'leave' ? 'leave' : 'join';
  if (buttonElement.dataset.deckPlayerMode === nextMode) {
    return;
  }
  buttonElement.dataset.deckPlayerMode = nextMode;
  buttonElement.classList.toggle('is-leave-mode', nextMode === 'leave');
  if (nextMode === 'leave') {
    buttonElement.setAttribute('aria-label', 'leave cool jpegs game');
    buttonElement.innerHTML =
      '<svg viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden="true"><path d="M5 12H19" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"/></svg>';
    return;
  }
  buttonElement.setAttribute('aria-label', 'join cool jpegs game');
  buttonElement.innerHTML =
    '<svg viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden="true"><path d="M12 5V19M5 12H19" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"/></svg>';
}

function buildDeckCoolJpegsPlayersRenderKey(payload) {
  const normalizedPlayers = normalizeDeckCoolJpegsPlayersPayload(payload);
  if (normalizedPlayers.length === 0) {
    return '';
  }
  return normalizedPlayers
    .map((entry) => {
      const token = String(entry?.token || '').trim();
      const name = String(entry?.name || '').trim().slice(0, DECK_PLAYER_NAME_MAX_LENGTH);
      const color = normalizeHexColor(entry?.color || '#ff7a59');
      const joinedAt = Number(entry?.joinedAt) || 0;
      const money = Math.max(0, Math.round(Number(entry?.money) || 0));
      const wonCards = normalizeCoolJpegsWonCardsPayload(entry?.wonCards);
      const wonCardsTailKey = wonCards
        .slice(-10)
        .map((wonCard) => `${wonCard.awardId}:${wonCard.frontSrc}:${wonCard.awardedAt}`)
        .join(',');
      return `${token}:${name}:${color}:${joinedAt}:${money}:${wonCards.length}:${wonCardsTailKey}`;
    })
    .join('|');
}

function getDeckCoolJpegsPlayers(deckId = activeDeckId) {
  const normalizedDeckId = normalizeDeckId(deckId);
  if (!normalizedDeckId || getDeckKind(normalizedDeckId) !== DECK_KIND_COOL) {
    return [];
  }
  if (coolJpegsPlayersByDeckId.has(normalizedDeckId)) {
    return normalizeDeckCoolJpegsPlayersPayload(coolJpegsPlayersByDeckId.get(normalizedDeckId));
  }
  return normalizeDeckCoolJpegsPlayersPayload(getDeckStateById(normalizedDeckId)?.coolJpegsPlayers);
}

function getLocalCoolJpegsPlayerToken() {
  return String(localPlayerToken || localClientId || '').trim();
}

function getLocalCoolJpegsMembership() {
  const playerToken = getLocalCoolJpegsPlayerToken();
  if (!playerToken) {
    return { deckId: '', entry: null };
  }
  let matchedDeckId = '';
  let matchedEntry = null;
  let matchedJoinedAt = -1;
  const sourceDeckIds = new Set([
    ...Array.from(coolJpegsPlayersByDeckId.keys()),
    ...Array.from(deckStatesById.keys())
  ]);
  for (const rawDeckId of sourceDeckIds) {
    const deckId = normalizeDeckId(rawDeckId);
    if (!deckId || getDeckKind(deckId) !== DECK_KIND_COOL) {
      continue;
    }
    const deckPlayers = getDeckCoolJpegsPlayers(deckId);
    const entry = deckPlayers.find((playerEntry) => String(playerEntry?.token || '').trim() === playerToken) || null;
    if (!entry) {
      continue;
    }
    const joinedAt = Number(entry?.joinedAt) || 0;
    if (!matchedEntry || joinedAt >= matchedJoinedAt) {
      matchedDeckId = deckId;
      matchedEntry = entry;
      matchedJoinedAt = joinedAt;
    }
  }
  return {
    deckId: matchedDeckId,
    entry: matchedEntry
  };
}

function getDeckCoolJpegsPlayerEntry(deckId = activeDeckId, playerToken = '', playerEntries = null) {
  const normalizedDeckId = normalizeDeckId(deckId);
  const normalizedPlayerToken = String(playerToken || '').trim();
  if (!normalizedDeckId || getDeckKind(normalizedDeckId) !== DECK_KIND_COOL || !normalizedPlayerToken) {
    return null;
  }
  const sourcePlayers = Array.isArray(playerEntries)
    ? normalizeDeckCoolJpegsPlayersPayload(playerEntries)
    : getDeckCoolJpegsPlayers(normalizedDeckId);
  return sourcePlayers.find((entry) => String(entry?.token || '').trim() === normalizedPlayerToken) || null;
}

function getCoolJpegsPlayerMoney(deckId = activeDeckId, playerToken = '', playerEntries = null) {
  const playerEntry = getDeckCoolJpegsPlayerEntry(deckId, playerToken, playerEntries);
  if (!playerEntry) {
    return null;
  }
  const numericMoney = Number(playerEntry?.money);
  return Number.isFinite(numericMoney)
    ? Math.max(0, Math.round(numericMoney))
    : COOL_JPEGS_STARTING_MONEY;
}

function getCoolJpegsAmountValidationMessage(
  deckId = activeDeckId,
  playerToken = '',
  amount = 0,
  playerEntries = null,
  amountLabel = 'amount'
) {
  const normalizedDeckId = normalizeDeckId(deckId);
  const normalizedPlayerToken = String(playerToken || '').trim();
  const numericAmount = Number(amount);
  const normalizedAmountLabel = String(amountLabel || 'amount').trim().toLowerCase() || 'amount';
  if (
    !normalizedDeckId ||
    getDeckKind(normalizedDeckId) !== DECK_KIND_COOL ||
    !normalizedPlayerToken ||
    !Number.isFinite(numericAmount) ||
    numericAmount < 0
  ) {
    return '';
  }
  const availableMoney = getCoolJpegsPlayerMoney(normalizedDeckId, normalizedPlayerToken, playerEntries);
  if (!Number.isFinite(availableMoney)) {
    return 'join this cool jpegs game first';
  }
  if (numericAmount > availableMoney) {
    return `${normalizedAmountLabel} exceeds available money`;
  }
  return '';
}

function formatCoolJpegsMoney(amount) {
  const numeric = Number(amount);
  const normalized = Number.isFinite(numeric) ? Math.max(0, Math.round(numeric)) : 0;
  return `$${normalized.toLocaleString('en-US')}`;
}

function waitForTimeoutDuration(durationMs = 0) {
  return new Promise((resolve) => {
    window.setTimeout(resolve, Math.max(0, Math.round(Number(durationMs) || 0)));
  });
}

function getCoolJpegsRoundLiquidationEntriesForPlayer(liquidationEvent, playerToken = '') {
  const normalizedEvent = normalizeCoolJpegsRoundLiquidationEventPayload(liquidationEvent);
  const normalizedPlayerToken = String(playerToken || '').trim();
  if (!normalizedEvent || !normalizedPlayerToken) {
    return [];
  }
  return normalizedEvent.entries.filter(
    (entry) => String(entry?.playerToken || '').trim() === normalizedPlayerToken
  );
}

function getCoolJpegsHudLiquidationState(deckId = activeDeckId) {
  const normalizedDeckId = normalizeDeckId(deckId);
  const localPlayerToken = getLocalCoolJpegsPlayerToken();
  if (
    !coolJpegsHudLiquidationState ||
    normalizeDeckId(coolJpegsHudLiquidationState.deckId) !== normalizedDeckId ||
    String(coolJpegsHudLiquidationState.playerToken || '').trim() !== localPlayerToken
  ) {
    return null;
  }
  return coolJpegsHudLiquidationState;
}

function hideCoolJpegsRoundLiquidationLayer() {
  coolJpegsRoundLiquidationCard?.classList.add('hidden');
  coolJpegsRoundLiquidationCard?.setAttribute('aria-hidden', 'true');
  if (coolJpegsRoundLiquidationCard instanceof HTMLElement) {
    coolJpegsRoundLiquidationCard.style.opacity = '0';
    coolJpegsRoundLiquidationCard.style.left = '50%';
    coolJpegsRoundLiquidationCard.style.top = '50%';
    coolJpegsRoundLiquidationCard.style.transform = 'translate(-50%, -50%) scale(0.52)';
    coolJpegsRoundLiquidationCard.style.transition = 'none';
  }
  if (coolJpegsRoundLiquidationCardImage instanceof HTMLImageElement) {
    coolJpegsRoundLiquidationCardImage.removeAttribute('src');
  }
  coolJpegsRoundLiquidationValue?.classList.add('hidden');
  coolJpegsRoundLiquidationValue?.setAttribute('aria-hidden', 'true');
  if (coolJpegsRoundLiquidationValue instanceof HTMLElement) {
    coolJpegsRoundLiquidationValue.textContent = '';
    coolJpegsRoundLiquidationValue.style.opacity = '0';
    coolJpegsRoundLiquidationValue.style.transform = 'translate(-50%, -50%) scale(0.9)';
    coolJpegsRoundLiquidationValue.style.transition = 'none';
  }
  coolJpegsRoundLiquidationLayer?.classList.add('hidden');
  coolJpegsRoundLiquidationLayer?.setAttribute('aria-hidden', 'true');
}

function getCoolJpegsRoundLiquidationCenterScreenPosition() {
  const viewportWidth = tableRoot?.clientWidth || window.innerWidth || 0;
  const viewportHeight = tableRoot?.clientHeight || window.innerHeight || 0;
  return {
    x: viewportWidth * 0.5,
    y: viewportHeight * 0.42
  };
}

function getCoolJpegsRoundLiquidationStartScreenPosition(deckId, playerToken) {
  const normalizedPlayerToken = String(playerToken || '').trim();
  const tableRect = tableRoot?.getBoundingClientRect();
  if (!tableRect) {
    return getCoolJpegsRoundLiquidationCenterScreenPosition();
  }
  const centerScreen = getCoolJpegsRoundLiquidationCenterScreenPosition();
  const leftTravelX = Math.max(64, centerScreen.x - Math.max(180, tableRect.width * 0.26));
  const localPlayerToken = getLocalCoolJpegsPlayerToken();
  if (
    normalizedPlayerToken &&
    normalizedPlayerToken === localPlayerToken &&
    coolJpegsHud instanceof HTMLElement &&
    !coolJpegsHud.classList.contains('hidden')
  ) {
    const hudRect = coolJpegsHud.getBoundingClientRect();
    if (hudRect.width > 0 && hudRect.height > 0) {
      return {
        x: leftTravelX,
        y: clamp(
          hudRect.top - tableRect.top + hudRect.height * 0.42,
          tableRect.height * 0.24,
          tableRect.height * 0.82
        )
      };
    }
  }
  return {
    x: leftTravelX,
    y: clamp(centerScreen.y + tableRect.height * 0.12, tableRect.height * 0.24, tableRect.height * 0.82)
  };
}

function createCoolJpegsHudLiquidationWonCards(entries, eventId = '') {
  return (Array.isArray(entries) ? entries : []).map((entry, index) => ({
    awardId: `liquidation-${eventId || 'event'}-${index}`,
    cardId: String(entry?.cardId || ''),
    frontSrc: String(entry?.frontSrc || ''),
    awardedAt: index + 1
  }));
}

function initializeCoolJpegsHudLiquidationState(deckId, playerEntries, liquidationEvent) {
  const normalizedDeckId = normalizeDeckId(deckId);
  const normalizedEvent = normalizeCoolJpegsRoundLiquidationEventPayload(liquidationEvent);
  const localPlayerToken = getLocalCoolJpegsPlayerToken();
  if (!normalizedDeckId || !normalizedEvent || !localPlayerToken) {
    coolJpegsHudLiquidationState = null;
    return;
  }
  const localEntries = getCoolJpegsRoundLiquidationEntriesForPlayer(normalizedEvent, localPlayerToken);
  if (localEntries.length === 0) {
    coolJpegsHudLiquidationState = null;
    return;
  }
  const finalMoney = getCoolJpegsPlayerMoney(normalizedDeckId, localPlayerToken, playerEntries);
  if (!Number.isFinite(finalMoney)) {
    coolJpegsHudLiquidationState = null;
    return;
  }
  const pendingValueTotal = localEntries.reduce(
    (sum, entry) => sum + Math.max(0, Number(entry?.amount) || 0),
    0
  );
  coolJpegsHudLiquidationState = {
    deckId: normalizedDeckId,
    eventId: normalizedEvent.id,
    playerToken: localPlayerToken,
    displayMoney: Math.max(0, finalMoney - pendingValueTotal),
    remainingWonCards: createCoolJpegsHudLiquidationWonCards(localEntries, normalizedEvent.id)
  };
}

function applyCoolJpegsHudLiquidationCredit(liquidationEntry, deckId, liquidationEvent) {
  const normalizedDeckId = normalizeDeckId(deckId);
  const normalizedEventId = String(liquidationEvent?.id || '').trim();
  if (
    !coolJpegsHudLiquidationState ||
    normalizeDeckId(coolJpegsHudLiquidationState.deckId) !== normalizedDeckId ||
    String(coolJpegsHudLiquidationState.eventId || '').trim() !== normalizedEventId
  ) {
    return;
  }
  if (String(liquidationEntry?.playerToken || '').trim() !== String(coolJpegsHudLiquidationState.playerToken || '').trim()) {
    return;
  }
  coolJpegsHudLiquidationState.displayMoney = Math.max(
    0,
    Math.round(Number(coolJpegsHudLiquidationState.displayMoney) || 0) +
      Math.max(0, Math.round(Number(liquidationEntry?.amount) || 0))
  );
  const nextRemainingWonCards = Array.isArray(coolJpegsHudLiquidationState.remainingWonCards)
    ? [...coolJpegsHudLiquidationState.remainingWonCards]
    : [];
  const removalIndex = nextRemainingWonCards.findIndex(
    (entry) =>
      String(entry?.cardId || '') === String(liquidationEntry?.cardId || '') &&
      String(entry?.frontSrc || '') === String(liquidationEntry?.frontSrc || '')
  );
  if (removalIndex >= 0) {
    nextRemainingWonCards.splice(removalIndex, 1);
  }
  coolJpegsHudLiquidationState.remainingWonCards = nextRemainingWonCards;
  renderCoolJpegsHud();
}

function clearCoolJpegsHudLiquidationState(deckId = '', eventId = '') {
  if (!coolJpegsHudLiquidationState) {
    return;
  }
  const normalizedDeckId = normalizeDeckId(deckId || coolJpegsHudLiquidationState.deckId);
  const normalizedEventId = String(eventId || coolJpegsHudLiquidationState.eventId || '').trim();
  if (
    normalizeDeckId(coolJpegsHudLiquidationState.deckId) !== normalizedDeckId ||
    String(coolJpegsHudLiquidationState.eventId || '').trim() !== normalizedEventId
  ) {
    return;
  }
  coolJpegsHudLiquidationState = null;
  renderCoolJpegsHud();
}

async function fadeOutCoolJpegsRoundLiquidationValue() {
  if (!(coolJpegsRoundLiquidationValue instanceof HTMLElement) || coolJpegsRoundLiquidationValue.classList.contains('hidden')) {
    return;
  }
  coolJpegsRoundLiquidationValue.style.transition =
    `opacity ${COOL_JPEGS_ROUND_LIQUIDATION_VALUE_FADE_MS}ms ease-out, transform ${COOL_JPEGS_ROUND_LIQUIDATION_VALUE_FADE_MS}ms ease-out`;
  coolJpegsRoundLiquidationValue.style.opacity = '0';
  coolJpegsRoundLiquidationValue.style.transform = 'translate(-50%, -50%) scale(0.9)';
  await waitForTimeoutDuration(COOL_JPEGS_ROUND_LIQUIDATION_VALUE_FADE_MS);
  coolJpegsRoundLiquidationValue.classList.add('hidden');
  coolJpegsRoundLiquidationValue.setAttribute('aria-hidden', 'true');
  coolJpegsRoundLiquidationValue.textContent = '';
}

async function showCoolJpegsRoundLiquidationValue(amount = 0) {
  if (!(coolJpegsRoundLiquidationValue instanceof HTMLElement)) {
    return;
  }
  coolJpegsRoundLiquidationValue.textContent = formatCoolJpegsMoney(amount);
  coolJpegsRoundLiquidationValue.classList.remove('hidden');
  coolJpegsRoundLiquidationValue.setAttribute('aria-hidden', 'false');
  coolJpegsRoundLiquidationValue.style.transition = 'none';
  coolJpegsRoundLiquidationValue.style.opacity = '0';
  coolJpegsRoundLiquidationValue.style.transform = 'translate(-50%, -50%) scale(0.86)';
  await waitForNextPaintFrame();
  coolJpegsRoundLiquidationValue.style.transition = 'opacity 140ms ease-out, transform 180ms ease-out';
  coolJpegsRoundLiquidationValue.style.opacity = '1';
  coolJpegsRoundLiquidationValue.style.transform = 'translate(-50%, -50%) scale(1)';
}

async function animateCoolJpegsRoundLiquidationCard(liquidationEntry, deckId) {
  if (
    !(coolJpegsRoundLiquidationLayer instanceof HTMLElement) ||
    !(coolJpegsRoundLiquidationCard instanceof HTMLElement) ||
    !(coolJpegsRoundLiquidationCardImage instanceof HTMLImageElement)
  ) {
    return;
  }
  const normalizedFrontSrc = toHighResFrontSrc(normalizeImageComponentSrc(liquidationEntry?.frontSrc || ''));
  if (!normalizedFrontSrc) {
    return;
  }
  const startScreen = getCoolJpegsRoundLiquidationStartScreenPosition(deckId, liquidationEntry?.playerToken || '');
  const centerScreen = getCoolJpegsRoundLiquidationCenterScreenPosition();
  coolJpegsRoundLiquidationLayer.classList.remove('hidden');
  coolJpegsRoundLiquidationLayer.setAttribute('aria-hidden', 'false');
  coolJpegsRoundLiquidationCard.classList.remove('hidden');
  coolJpegsRoundLiquidationCard.setAttribute('aria-hidden', 'false');
  coolJpegsRoundLiquidationCardImage.src = normalizedFrontSrc;
  coolJpegsRoundLiquidationCard.style.transition = 'none';
  coolJpegsRoundLiquidationCard.style.left = `${startScreen.x}px`;
  coolJpegsRoundLiquidationCard.style.top = `${startScreen.y}px`;
  coolJpegsRoundLiquidationCard.style.transform = 'translate(-50%, -50%) scale(0.54)';
  coolJpegsRoundLiquidationCard.style.opacity = '0';
  await waitForNextPaintFrame();
  coolJpegsRoundLiquidationCard.style.transition =
    `left ${COOL_JPEGS_ROUND_LIQUIDATION_ENTRY_TRAVEL_MS}ms cubic-bezier(0.16, 1, 0.3, 1), ` +
    `top ${COOL_JPEGS_ROUND_LIQUIDATION_ENTRY_TRAVEL_MS}ms cubic-bezier(0.16, 1, 0.3, 1), ` +
    `transform ${COOL_JPEGS_ROUND_LIQUIDATION_ENTRY_TRAVEL_MS}ms cubic-bezier(0.16, 1, 0.3, 1), ` +
    'opacity 140ms ease-out';
  coolJpegsRoundLiquidationCard.style.left = `${centerScreen.x}px`;
  coolJpegsRoundLiquidationCard.style.top = `${centerScreen.y}px`;
  coolJpegsRoundLiquidationCard.style.transform = 'translate(-50%, -50%) scale(1)';
  coolJpegsRoundLiquidationCard.style.opacity = '1';
  await waitForTimeoutDuration(COOL_JPEGS_ROUND_LIQUIDATION_ENTRY_TRAVEL_MS);
  await waitForTimeoutDuration(COOL_JPEGS_ROUND_LIQUIDATION_ENTRY_HOLD_MS);
  coolJpegsRoundLiquidationCard.style.transition =
    `transform ${COOL_JPEGS_ROUND_LIQUIDATION_ENTRY_PULSE_MS}ms ease-out`;
  coolJpegsRoundLiquidationCard.style.transform = 'translate(-50%, -50%) scale(1.08)';
  await waitForTimeoutDuration(COOL_JPEGS_ROUND_LIQUIDATION_ENTRY_PULSE_MS);
  coolJpegsRoundLiquidationCard.style.transition =
    `transform ${COOL_JPEGS_ROUND_LIQUIDATION_ENTRY_EXIT_MS}ms cubic-bezier(0.3, 0, 0.25, 1), ` +
    `opacity ${COOL_JPEGS_ROUND_LIQUIDATION_ENTRY_EXIT_MS}ms ease-out`;
  coolJpegsRoundLiquidationCard.style.transform = 'translate(-50%, -50%) scale(0.06)';
  coolJpegsRoundLiquidationCard.style.opacity = '0';
  await waitForTimeoutDuration(COOL_JPEGS_ROUND_LIQUIDATION_ENTRY_EXIT_MS);
  coolJpegsRoundLiquidationCard.classList.add('hidden');
  coolJpegsRoundLiquidationCard.setAttribute('aria-hidden', 'true');
  coolJpegsRoundLiquidationCard.style.transition = 'none';
}

async function playCoolJpegsRoundLiquidationEvent(deckId, playerEntries, liquidationEvent) {
  const normalizedDeckId = normalizeDeckId(deckId);
  const normalizedEvent = normalizeCoolJpegsRoundLiquidationEventPayload(liquidationEvent);
  const localPlayerToken = getLocalCoolJpegsPlayerToken();
  const localEntries = getCoolJpegsRoundLiquidationEntriesForPlayer(normalizedEvent, localPlayerToken);
  if (!normalizedDeckId || !normalizedEvent || localEntries.length === 0) {
    return;
  }
  initializeCoolJpegsHudLiquidationState(normalizedDeckId, playerEntries, normalizedEvent);
  renderCoolJpegsHud();
  let hasVisibleValue = false;
  for (const liquidationEntry of localEntries) {
    if (hasVisibleValue) {
      void fadeOutCoolJpegsRoundLiquidationValue();
    }
    await animateCoolJpegsRoundLiquidationCard(liquidationEntry, normalizedDeckId);
    await showCoolJpegsRoundLiquidationValue(liquidationEntry.amount);
    applyCoolJpegsHudLiquidationCredit(liquidationEntry, normalizedDeckId, normalizedEvent);
    await waitForTimeoutDuration(COOL_JPEGS_ROUND_LIQUIDATION_VALUE_HOLD_MS);
    hasVisibleValue = true;
  }
  if (hasVisibleValue) {
    await waitForTimeoutDuration(180);
    await fadeOutCoolJpegsRoundLiquidationValue();
  }
  hideCoolJpegsRoundLiquidationLayer();
  clearCoolJpegsHudLiquidationState(normalizedDeckId, normalizedEvent.id);
}

function queueCoolJpegsRoundLiquidationPlayback(deckId, previousPlayerEntries, nextPlayerEntries, roundStatePayload) {
  const normalizedDeckId = normalizeDeckId(deckId);
  const roundState = normalizeCoolJpegsRoundStatePayload(roundStatePayload, normalizedDeckId);
  const liquidationEvent = normalizeCoolJpegsRoundLiquidationEventPayload(roundState?.latestLiquidationEvent);
  if (!normalizedDeckId || !liquidationEvent) {
    return;
  }
  const lastHandledEventId = String(coolJpegsRoundLiquidationHandledEventIdByDeckId.get(normalizedDeckId) || '').trim();
  if (lastHandledEventId === liquidationEvent.id) {
    return;
  }
  const localPlayerToken = getLocalCoolJpegsPlayerToken();
  const localEntries = getCoolJpegsRoundLiquidationEntriesForPlayer(liquidationEvent, localPlayerToken);
  if (localEntries.length === 0) {
    coolJpegsRoundLiquidationHandledEventIdByDeckId.set(normalizedDeckId, liquidationEvent.id);
    return;
  }
  const previousLocalEntry = getDeckCoolJpegsPlayerEntry(normalizedDeckId, localPlayerToken, previousPlayerEntries);
  const nextLocalEntry = getDeckCoolJpegsPlayerEntry(normalizedDeckId, localPlayerToken, nextPlayerEntries);
  const previousWonCardCount = normalizeCoolJpegsWonCardsPayload(previousLocalEntry?.wonCards).length;
  const nextWonCardCount = normalizeCoolJpegsWonCardsPayload(nextLocalEntry?.wonCards).length;
  const shouldPlayLocally = previousWonCardCount > 0 && nextWonCardCount === 0;
  coolJpegsRoundLiquidationHandledEventIdByDeckId.set(normalizedDeckId, liquidationEvent.id);
  if (!shouldPlayLocally) {
    return;
  }
  coolJpegsRoundLiquidationPlaybackQueue = coolJpegsRoundLiquidationPlaybackQueue
    .then(() => playCoolJpegsRoundLiquidationEvent(normalizedDeckId, nextPlayerEntries, liquidationEvent))
    .catch((error) => {
      console.error(error);
      hideCoolJpegsRoundLiquidationLayer();
      clearCoolJpegsHudLiquidationState(normalizedDeckId, liquidationEvent.id);
    });
}

function hideCoolJpegsHudPreview() {
  if (!coolJpegsHudPreview || !coolJpegsHudPreviewImage) {
    return;
  }
  coolJpegsHudPreview.classList.add('hidden');
  coolJpegsHudPreview.setAttribute('aria-hidden', 'true');
  coolJpegsHudPreviewImage.removeAttribute('src');
  coolJpegsHudPreviewSrc = '';
}

function showCoolJpegsHudPreview(frontSrc = '') {
  if (!coolJpegsHudPreview || !coolJpegsHudPreviewImage) {
    return;
  }
  const normalizedFrontSrc = toHighResFrontSrc(normalizeImageComponentSrc(frontSrc || ''));
  if (!normalizedFrontSrc) {
    hideCoolJpegsHudPreview();
    return;
  }
  if (coolJpegsHudPreviewSrc !== normalizedFrontSrc) {
    coolJpegsHudPreviewImage.setAttribute('src', normalizedFrontSrc);
    coolJpegsHudPreviewSrc = normalizedFrontSrc;
  }
  coolJpegsHudPreview.classList.remove('hidden');
  coolJpegsHudPreview.setAttribute('aria-hidden', 'false');
}

function renderCoolJpegsHudWonCards(wonCardsPayload) {
  if (!coolJpegsHudWonCards) {
    return;
  }
  const wonCards = normalizeCoolJpegsWonCardsPayload(wonCardsPayload);
  const visibleCards = wonCards.slice(-COOL_JPEGS_HUD_WON_CARD_MAX_VISIBLE);
  const renderKey = visibleCards
    .map((entry) => `${entry.awardId}:${entry.frontSrc}:${entry.awardedAt}`)
    .join('|');
  if (renderKey === coolJpegsHudWonCardsRenderKey) {
    return;
  }
  hideCoolJpegsHudPreview();
  coolJpegsHudWonCardsRenderKey = renderKey;
  coolJpegsHudWonCards.textContent = '';
  if (visibleCards.length === 0) {
    coolJpegsHudWonCards.classList.add('hidden');
    coolJpegsHudWonCards.setAttribute('aria-hidden', 'true');
    return;
  }
  const fragment = document.createDocumentFragment();
  for (const wonCard of visibleCards) {
    const entry = document.createElement('div');
    entry.className = 'cool-jpegs-hud-won-entry';

    const cardImage = document.createElement('img');
    cardImage.className = 'cool-jpegs-hud-won-card';
    cardImage.src = wonCard.frontSrc;
    cardImage.alt = '';
    cardImage.decoding = 'async';
    cardImage.loading = 'lazy';
    cardImage.draggable = false;
    entry.appendChild(cardImage);

    const cardInfo = resolveCoolJpegsCardInfo(
      { frontSrc: wonCard.frontSrc },
      String(wonCard.cardId || '')
    );
    const artistIcon = document.createElement('img');
    artistIcon.className = 'cool-jpegs-hud-won-artist';
    artistIcon.alt = '';
    artistIcon.decoding = 'async';
    artistIcon.loading = 'lazy';
    artistIcon.draggable = false;
    if (cardInfo?.artistIconSrc) {
      artistIcon.src = cardInfo.artistIconSrc;
      artistIcon.setAttribute('aria-hidden', 'false');
    } else {
      artistIcon.classList.add('hidden');
      artistIcon.setAttribute('aria-hidden', 'true');
    }
    entry.appendChild(artistIcon);
    entry.addEventListener('pointerenter', () => {
      showCoolJpegsHudPreview(wonCard.frontSrc);
    });
    entry.addEventListener('pointerleave', () => {
      hideCoolJpegsHudPreview();
    });
    entry.addEventListener('pointercancel', () => {
      hideCoolJpegsHudPreview();
    });
    fragment.appendChild(entry);
  }
  coolJpegsHudWonCards.appendChild(fragment);
  coolJpegsHudWonCards.classList.remove('hidden');
  coolJpegsHudWonCards.setAttribute('aria-hidden', 'false');
}

function renderCoolJpegsHud() {
  if (!coolJpegsHud || !coolJpegsHudMoneyValue) {
    return;
  }
  const membership = getLocalCoolJpegsMembership();
  const activeDeckId = normalizeDeckId(membership.deckId);
  const activeDeckState = activeDeckId ? getDeckStateById(activeDeckId) : null;
  const visible = Boolean(activeDeckId && activeDeckState && membership.entry);
  coolJpegsHud.classList.toggle('hidden', !visible);
  coolJpegsHud.setAttribute('aria-hidden', visible ? 'false' : 'true');
  if (!visible) {
    coolJpegsHudMoneyValue.textContent = formatCoolJpegsMoney(COOL_JPEGS_STARTING_MONEY);
    renderCoolJpegsHudWonCards([]);
    hideCoolJpegsHudPreview();
    return;
  }
  const liquidationHudState = getCoolJpegsHudLiquidationState(activeDeckId);
  const money = liquidationHudState
    ? Number(liquidationHudState.displayMoney)
    : Number(membership.entry?.money);
  coolJpegsHudMoneyValue.textContent = formatCoolJpegsMoney(
    Number.isFinite(money) ? money : COOL_JPEGS_STARTING_MONEY
  );
  renderCoolJpegsHudWonCards(
    liquidationHudState ? liquidationHudState.remainingWonCards : membership.entry?.wonCards
  );
}

function createCoolJpegsArtistBoardRoundCounts() {
  return Array.from(
    { length: COOL_JPEGS_ARTIST_BOARD_ROUND_COUNT },
    () => createEmptyCoolJpegsArtistCounts()
  );
}

function buildCoolJpegsArtistCountsFromWonCards(wonCardsPayload) {
  const counts = createEmptyCoolJpegsArtistCounts();
  const wonCards = normalizeCoolJpegsWonCardsPayload(wonCardsPayload);
  for (const wonCard of wonCards) {
    const cardInfo = resolveCoolJpegsCardInfo(
      { frontSrc: wonCard?.frontSrc || '' },
      String(wonCard?.cardId || '')
    );
    const artist = normalizeCoolJpegsArtistLabel(cardInfo?.artist || '');
    if (!artist || !Object.prototype.hasOwnProperty.call(counts, artist)) {
      continue;
    }
    counts[artist] += 1;
  }
  return counts;
}

function buildCoolJpegsArtistCountsFromPlayers(playerEntries) {
  const counts = createEmptyCoolJpegsArtistCounts();
  const normalizedEntries = normalizeDeckCoolJpegsPlayersPayload(playerEntries);
  for (const playerEntry of normalizedEntries) {
    const playerCounts = buildCoolJpegsArtistCountsFromWonCards(playerEntry?.wonCards);
    for (const artist of COOL_JPEGS_ARTIST_BOARD_ARTIST_ORDER) {
      counts[artist] += Math.max(0, Number(playerCounts?.[artist]) || 0);
    }
  }
  return counts;
}

function buildCoolJpegsArtistCountsFromPlayersPayloadObject(playersPayload) {
  return buildCoolJpegsArtistCountsFromPlayers(
    normalizeDeckCoolJpegsPlayersPayload(playersPayload)
  );
}

function getDeckCoolJpegsRoundState(deckId = activeDeckId) {
  const normalizedDeckId = normalizeDeckId(deckId);
  if (!normalizedDeckId || getDeckKind(normalizedDeckId) !== DECK_KIND_COOL) {
    return normalizeCoolJpegsRoundStatePayload(null, normalizedDeckId);
  }
  if (coolJpegsRoundStateByDeckId.has(normalizedDeckId)) {
    const { roundState: repairedRoundState } = buildCoolJpegsRoundStateWithLatestLiquidationBackfill(
      coolJpegsRoundStateByDeckId.get(normalizedDeckId),
      normalizedDeckId
    );
    return repairedRoundState;
  }
  return normalizeCoolJpegsRoundStatePayload(null, normalizedDeckId);
}

function getCoolJpegsArtistOrderIndex(artist) {
  const normalizedArtist = normalizeCoolJpegsArtistLabel(artist);
  const index = COOL_JPEGS_ARTIST_BOARD_ARTIST_ORDER.indexOf(normalizedArtist);
  return index >= 0 ? index : COOL_JPEGS_ARTIST_BOARD_ARTIST_ORDER.length;
}

function getCoolJpegsRoundPayoutByArtist(roundCountsPayload) {
  const roundCounts = normalizeCoolJpegsArtistCountsPayload(roundCountsPayload);
  const rankedArtists = [...COOL_JPEGS_ARTIST_BOARD_ARTIST_ORDER].sort((leftArtist, rightArtist) => {
    const countDelta = roundCounts[rightArtist] - roundCounts[leftArtist];
    if (countDelta !== 0) {
      return countDelta;
    }
    return getCoolJpegsArtistOrderIndex(rightArtist) - getCoolJpegsArtistOrderIndex(leftArtist);
  });
  const payoutByArtist = createEmptyCoolJpegsArtistCounts();
  rankedArtists.forEach((artist, index) => {
    payoutByArtist[artist] = COOL_JPEGS_ROUND_PAYOUTS_BY_PLACE[index] || 0;
  });
  return payoutByArtist;
}

function getCoolJpegsCompletedRoundPayoutDisplayByArtist(roundStatePayload, roundIndex) {
  const normalizedRoundState = normalizeCoolJpegsRoundStatePayload(roundStatePayload);
  const normalizedRoundIndex = clamp(
    Number.isInteger(Number(roundIndex)) ? Number(roundIndex) : 0,
    0,
    COOL_JPEGS_ARTIST_BOARD_ROUND_COUNT - 1
  );
  const completedRoundCounts = normalizeCoolJpegsArtistCountsPayload(
    normalizedRoundState.completedRoundCountsByIndex?.[normalizedRoundIndex]
  );
  if (hasAnyCoolJpegsArtistCounts(completedRoundCounts)) {
    return getCoolJpegsRoundBoardPayoutDisplayByArtist(completedRoundCounts);
  }
  const persistedPayoutDisplay = normalizeCoolJpegsArtistCountsPayload(
    normalizedRoundState.completedRoundPayoutDisplayByIndex?.[normalizedRoundIndex]
  );
  return hasAnyCoolJpegsArtistCounts(persistedPayoutDisplay)
    ? persistedPayoutDisplay
    : createEmptyCoolJpegsArtistCounts();
}

function getCoolJpegsHistoricalRoundPayoutBonusByArtist(roundStatePayload, roundIndexExclusive) {
  const normalizedRoundState = normalizeCoolJpegsRoundStatePayload(roundStatePayload);
  const cappedRoundIndexExclusive = clamp(
    Number.isInteger(Number(roundIndexExclusive)) ? Number(roundIndexExclusive) : 0,
    0,
    COOL_JPEGS_ARTIST_BOARD_ROUND_COUNT
  );
  const payoutBonusByArtist = createEmptyCoolJpegsArtistCounts();
  for (let roundIndex = 0; roundIndex < cappedRoundIndexExclusive; roundIndex += 1) {
    const completedRoundPayoutDisplay = getCoolJpegsCompletedRoundPayoutDisplayByArtist(
      normalizedRoundState,
      roundIndex
    );
    for (const artist of COOL_JPEGS_ARTIST_BOARD_ARTIST_ORDER) {
      payoutBonusByArtist[artist] += Math.max(
        0,
        Math.round(Number(completedRoundPayoutDisplay?.[artist]) || 0) * 1000
      );
    }
  }
  return payoutBonusByArtist;
}

function getCoolJpegsRoundLiquidationPayoutByArtist(
  roundCountsPayload,
  roundStatePayload,
  roundIndex = 0
) {
  const basePayoutByArtist = getCoolJpegsRoundPayoutByArtist(roundCountsPayload);
  const normalizedRoundIndex = clamp(
    Number.isInteger(Number(roundIndex)) ? Number(roundIndex) : 0,
    0,
    COOL_JPEGS_ARTIST_BOARD_ROUND_COUNT
  );
  if (normalizedRoundIndex <= 0) {
    return basePayoutByArtist;
  }
  const historicalBonusByArtist = getCoolJpegsHistoricalRoundPayoutBonusByArtist(
    roundStatePayload,
    normalizedRoundIndex
  );
  const liquidationPayoutByArtist = createEmptyCoolJpegsArtistCounts();
  for (const artist of COOL_JPEGS_ARTIST_BOARD_ARTIST_ORDER) {
    const basePayout = Math.max(0, Number(basePayoutByArtist?.[artist]) || 0);
    liquidationPayoutByArtist[artist] = basePayout > 0
      ? basePayout + Math.max(0, Number(historicalBonusByArtist?.[artist]) || 0)
      : 0;
  }
  return liquidationPayoutByArtist;
}

function getCoolJpegsRoundBoardPayoutDisplayByArtist(roundCountsPayload) {
  const payoutByArtist = getCoolJpegsRoundPayoutByArtist(roundCountsPayload);
  const displayByArtist = createEmptyCoolJpegsArtistCounts();
  for (const artist of COOL_JPEGS_ARTIST_BOARD_ARTIST_ORDER) {
    displayByArtist[artist] = Math.max(0, Math.round((Number(payoutByArtist?.[artist]) || 0) / 1000));
  }
  return displayByArtist;
}

function hasAnyCoolJpegsArtistCounts(countsPayload) {
  const normalizedCounts = normalizeCoolJpegsArtistCountsPayload(countsPayload);
  return COOL_JPEGS_ARTIST_BOARD_ARTIST_ORDER.some((artist) => normalizedCounts[artist] > 0);
}

function buildCoolJpegsArtistCountsFromLiquidationEvent(liquidationEvent, roundIndex = null) {
  const normalizedEvent = normalizeCoolJpegsRoundLiquidationEventPayload(liquidationEvent);
  const targetRoundIndex = Number.isInteger(Number(roundIndex)) ? Number(roundIndex) : null;
  const counts = createEmptyCoolJpegsArtistCounts();
  if (!normalizedEvent) {
    return counts;
  }
  if (targetRoundIndex !== null && normalizedEvent.roundIndex !== targetRoundIndex) {
    return counts;
  }
  for (const entry of normalizedEvent.entries) {
    const cardInfo = resolveCoolJpegsCardInfo(
      { frontSrc: entry?.frontSrc || '' },
      String(entry?.cardId || '')
    );
    const artist = normalizeCoolJpegsArtistLabel(cardInfo?.artist || '');
    if (!artist || !Object.prototype.hasOwnProperty.call(counts, artist)) {
      continue;
    }
    counts[artist] += 1;
  }
  return counts;
}

function buildCoolJpegsRoundStateWithLatestLiquidationBackfill(roundStatePayload, deckId = '') {
  const normalizedDeckId = normalizeDeckId(deckId);
  const roundState = normalizeCoolJpegsRoundStatePayload(roundStatePayload, normalizedDeckId);
  const liquidationEvent = normalizeCoolJpegsRoundLiquidationEventPayload(roundState.latestLiquidationEvent);
  if (!liquidationEvent) {
    return { roundState, changed: false };
  }
  const roundIndex = clamp(liquidationEvent.roundIndex, 0, COOL_JPEGS_ARTIST_BOARD_ROUND_COUNT - 1);
  const roundIsCompleted =
    roundIndex < roundState.currentRoundIndex ||
    roundState.currentRoundIndex >= COOL_JPEGS_ARTIST_BOARD_ROUND_COUNT;
  if (!roundIsCompleted) {
    return { roundState, changed: false };
  }
  const derivedCounts = buildCoolJpegsArtistCountsFromLiquidationEvent(liquidationEvent, roundIndex);
  const hasDerivedCounts = COOL_JPEGS_ARTIST_BOARD_ARTIST_ORDER.some((artist) => derivedCounts[artist] > 0);
  if (!hasDerivedCounts) {
    return { roundState, changed: false };
  }
  const nextCompletedRoundCountsByIndex = roundState.completedRoundCountsByIndex.map((counts) =>
    normalizeCoolJpegsArtistCountsPayload(counts)
  );
  const nextCompletedRoundPayoutDisplayByIndex = roundState.completedRoundPayoutDisplayByIndex.map((counts) =>
    normalizeCoolJpegsArtistCountsPayload(counts)
  );
  let changed = false;
  const storedCounts = normalizeCoolJpegsArtistCountsPayload(nextCompletedRoundCountsByIndex[roundIndex]);
  const hasStoredCounts = COOL_JPEGS_ARTIST_BOARD_ARTIST_ORDER.some((artist) => storedCounts[artist] > 0);
  if (!hasStoredCounts) {
    nextCompletedRoundCountsByIndex[roundIndex] = derivedCounts;
    changed = true;
  }
  const storedPayoutDisplay = normalizeCoolJpegsArtistCountsPayload(
    nextCompletedRoundPayoutDisplayByIndex[roundIndex]
  );
  const hasStoredPayoutDisplay = COOL_JPEGS_ARTIST_BOARD_ARTIST_ORDER.some(
    (artist) => storedPayoutDisplay[artist] > 0
  );
  if (!hasStoredPayoutDisplay) {
    nextCompletedRoundPayoutDisplayByIndex[roundIndex] = getCoolJpegsRoundBoardPayoutDisplayByArtist(
      hasStoredCounts ? storedCounts : derivedCounts
    );
    changed = true;
  }
  if (!changed) {
    return { roundState, changed: false };
  }
  return {
    roundState: {
      ...roundState,
      completedRoundCountsByIndex: nextCompletedRoundCountsByIndex,
      completedRoundPayoutDisplayByIndex: nextCompletedRoundPayoutDisplayByIndex
    },
    changed: true
  };
}

function shouldEndCoolJpegsRound(roundCountsPayload) {
  const roundCounts = normalizeCoolJpegsArtistCountsPayload(roundCountsPayload);
  return COOL_JPEGS_ARTIST_BOARD_ARTIST_ORDER.some(
    (artist) => roundCounts[artist] >= COOL_JPEGS_ROUND_END_ARTIST_SALE_THRESHOLD
  );
}

function getCoolJpegsArtistBoardRoundCounts(deckId = activeDeckId) {
  const normalizedDeckId = normalizeDeckId(deckId);
  const roundCounts = createCoolJpegsArtistBoardRoundCounts();
  if (!normalizedDeckId || getDeckKind(normalizedDeckId) !== DECK_KIND_COOL) {
    return roundCounts;
  }
  const roundState = getDeckCoolJpegsRoundState(normalizedDeckId);
  let activeRoundIndexForDisplay = -1;
  for (let roundIndex = 0; roundIndex < COOL_JPEGS_ARTIST_BOARD_ROUND_COUNT; roundIndex += 1) {
    const storedCompletedCounts = normalizeCoolJpegsArtistCountsPayload(
      roundState.completedRoundCountsByIndex[roundIndex]
    );
    const storedCompletedPayoutDisplay = normalizeCoolJpegsArtistCountsPayload(
      roundState.completedRoundPayoutDisplayByIndex?.[roundIndex]
    );
    if (hasAnyCoolJpegsArtistCounts(storedCompletedCounts) || hasAnyCoolJpegsArtistCounts(storedCompletedPayoutDisplay)) {
      roundCounts[roundIndex] = storedCompletedCounts;
      continue;
    }
    if (activeRoundIndexForDisplay === -1) {
      activeRoundIndexForDisplay = roundIndex;
    }
  }
  if (activeRoundIndexForDisplay >= 0 && activeRoundIndexForDisplay < COOL_JPEGS_ARTIST_BOARD_ROUND_COUNT) {
    roundCounts[activeRoundIndexForDisplay] = buildCoolJpegsArtistCountsFromPlayers(
      getDeckCoolJpegsPlayers(normalizedDeckId)
    );
  }
  return roundCounts;
}

function getCoolJpegsArtistBoardDisplayValues(deckId = activeDeckId) {
  const normalizedDeckId = normalizeDeckId(deckId);
  const displayValues = createCoolJpegsArtistBoardRoundCounts();
  if (!normalizedDeckId || getDeckKind(normalizedDeckId) !== DECK_KIND_COOL) {
    return displayValues;
  }
  const roundState = getDeckCoolJpegsRoundState(normalizedDeckId);
  const roundCounts = getCoolJpegsArtistBoardRoundCounts(normalizedDeckId);
  let activeRoundIndexForDisplay = -1;
  for (let roundIndex = 0; roundIndex < COOL_JPEGS_ARTIST_BOARD_ROUND_COUNT; roundIndex += 1) {
    const completedRoundCounts = normalizeCoolJpegsArtistCountsPayload(
      roundState.completedRoundCountsByIndex[roundIndex]
    );
    const persistedPayoutDisplay = normalizeCoolJpegsArtistCountsPayload(
      roundState.completedRoundPayoutDisplayByIndex?.[roundIndex]
    );
    const hasAnySales = COOL_JPEGS_ARTIST_BOARD_ARTIST_ORDER.some(
      (artist) => (Number(completedRoundCounts?.[artist]) || 0) > 0
    );
    const hasPersistedPayoutDisplay = COOL_JPEGS_ARTIST_BOARD_ARTIST_ORDER.some(
      (artist) => (Number(persistedPayoutDisplay?.[artist]) || 0) > 0
    );
    if (hasAnySales) {
      displayValues[roundIndex] = getCoolJpegsRoundBoardPayoutDisplayByArtist(completedRoundCounts);
      continue;
    }
    if (hasPersistedPayoutDisplay) {
      displayValues[roundIndex] = persistedPayoutDisplay;
      continue;
    }
    if (activeRoundIndexForDisplay === -1) {
      activeRoundIndexForDisplay = roundIndex;
    }
  }
  if (activeRoundIndexForDisplay >= 0 && activeRoundIndexForDisplay < COOL_JPEGS_ARTIST_BOARD_ROUND_COUNT) {
    displayValues[activeRoundIndexForDisplay] = normalizeCoolJpegsArtistCountsPayload(
      roundCounts[activeRoundIndexForDisplay]
    );
  }
  return displayValues;
}

function buildCoolJpegsArtistBoardRoundCountsRenderKey(roundDisplayValues) {
  return (Array.isArray(roundDisplayValues) ? roundDisplayValues : [])
    .map((roundCountsForRow) =>
      COOL_JPEGS_ARTIST_BOARD_ARTIST_ORDER
        .map((artist) => `${artist}:${Math.max(0, Number(roundCountsForRow?.[artist]) || 0)}`)
        .join(',')
    )
    .join('|');
}

function getCoolJpegsArtistBoardRankByArtist(roundDisplayValuesPayload) {
  const normalizedDisplayValues = normalizeCoolJpegsArtistCountsPayload(roundDisplayValuesPayload);
  const rankedArtists = [...COOL_JPEGS_ARTIST_BOARD_ARTIST_ORDER].sort((leftArtist, rightArtist) => {
    const valueDelta = normalizedDisplayValues[rightArtist] - normalizedDisplayValues[leftArtist];
    if (valueDelta !== 0) {
      return valueDelta;
    }
    return getCoolJpegsArtistOrderIndex(rightArtist) - getCoolJpegsArtistOrderIndex(leftArtist);
  });
  const rankByArtist = {};
  rankedArtists.forEach((artist, index) => {
    rankByArtist[artist] = index;
  });
  return rankByArtist;
}

function renderCoolJpegsArtistBoardCounts(deckUi, deckId = activeDeckId) {
  if (!deckUi?.coolJpegsArtistBoard || !Array.isArray(deckUi.coolJpegsArtistBoardMarkers)) {
    return;
  }
  const roundDisplayValues = getCoolJpegsArtistBoardDisplayValues(deckId);
  const rankByArtistByRound = roundDisplayValues.map((roundDisplayValuesForRow) =>
    getCoolJpegsArtistBoardRankByArtist(roundDisplayValuesForRow)
  );
  const renderKey = buildCoolJpegsArtistBoardRoundCountsRenderKey(roundDisplayValues);
  if (deckUi.coolJpegsArtistBoard.dataset.roundCountsKey === renderKey) {
    return;
  }
  deckUi.coolJpegsArtistBoard.dataset.roundCountsKey = renderKey;
  for (const marker of deckUi.coolJpegsArtistBoardMarkers) {
    if (!(marker instanceof HTMLElement)) {
      continue;
    }
    const parsedRoundIndex = Number.parseInt(String(marker.dataset.roundIndex || ''), 10);
    const roundIndex = Number.isInteger(parsedRoundIndex)
      ? clamp(parsedRoundIndex, 0, COOL_JPEGS_ARTIST_BOARD_ROUND_COUNT - 1)
      : 0;
    const artist = normalizeCoolJpegsArtistLabel(marker.dataset.artist || '');
    const displayValue = Math.max(0, Number(roundDisplayValues?.[roundIndex]?.[artist]) || 0);
    const artistRank = Math.max(
      0,
      Math.floor(Number(rankByArtistByRound?.[roundIndex]?.[artist]))
    );
    const visible = displayValue > 0;
    marker.classList.toggle('hidden', !visible);
    marker.classList.toggle('is-rank-first', visible && artistRank === 0);
    marker.classList.toggle('is-rank-second', visible && artistRank === 1);
    marker.classList.toggle('is-rank-third', visible && artistRank === 2);
    marker.setAttribute('aria-hidden', visible ? 'false' : 'true');
    if (visible && marker.textContent !== String(displayValue)) {
      marker.textContent = String(displayValue);
    }
  }
}

function resolveDeckCoolJpegsPlayerDisplay(entry) {
  const token = typeof entry?.token === 'string' ? entry.token : '';
  const isLocal = Boolean(localPlayerToken) && token === localPlayerToken;
  const livePayload = isLocal ? null : getCursorPayloadByPlayerToken(token);
  const name = String(isLocal ? playerState.name : livePayload?.name || entry?.name || '').trim();
  const color = normalizeHexColor(isLocal ? playerState.color : livePayload?.color || entry?.color || '#ff7a59');
  return {
    token,
    name: name || 'anon',
    color
  };
}

function renderDeckCoolJpegsPlayersList(listElement, playersPayload) {
  if (!(listElement instanceof HTMLElement)) {
    return;
  }
  const players = normalizeDeckCoolJpegsPlayersPayload(playersPayload);
  listElement.textContent = '';
  if (players.length === 0) {
    listElement.classList.add('hidden');
    return;
  }
  const fragment = document.createDocumentFragment();
  for (const playerEntry of players) {
    const display = resolveDeckCoolJpegsPlayerDisplay(playerEntry);
    const row = document.createElement('div');
    row.className = 'mons-side-claim-row';
    row.dataset.playerToken = String(playerEntry?.token || '').trim();
    const dot = document.createElement('span');
    dot.className = 'mons-side-claim-dot';
    dot.style.background = display.color;
    row.appendChild(dot);
    const name = document.createElement('span');
    name.className = 'mons-side-claim-name';
    name.textContent = display.name;
    name.style.color = display.color;
    row.appendChild(name);
    fragment.appendChild(row);
  }
  listElement.appendChild(fragment);
  listElement.classList.remove('hidden');
}

function joinCoolJpegsDeckAsLocalPlayer(deckId = activeDeckId) {
  const normalizedDeckId = normalizeDeckId(deckId);
  if (!normalizedDeckId || getDeckKind(normalizedDeckId) !== DECK_KIND_COOL) {
    return;
  }
  const playerToken = getLocalCoolJpegsPlayerToken();
  if (!playerToken) {
    return;
  }
  const activeMembership = getLocalCoolJpegsMembership();
  if (activeMembership.deckId && activeMembership.deckId !== normalizedDeckId) {
    showStatusMessage('leave your current cool jpegs game first');
    return;
  }
  const existingPlayers = getDeckCoolJpegsPlayers(normalizedDeckId);
  if (existingPlayers.some((entry) => entry?.token === playerToken)) {
    return;
  }
  const nextPlayers = normalizeDeckCoolJpegsPlayersPayload([
    ...existingPlayers,
    {
      token: playerToken,
      name: String(playerState?.name || '').trim().slice(0, DECK_PLAYER_NAME_MAX_LENGTH),
      color: normalizeHexColor(playerState?.color || '#ff7a59'),
      joinedAt: Date.now(),
      money: COOL_JPEGS_STARTING_MONEY
    }
  ]);
  coolJpegsPlayersByDeckId.set(normalizedDeckId, nextPlayers);
  runRenderSafely('joinCoolJpegsDeckAsLocalPlayer', () => {
    renderDeckControls(buildDeckCardMetrics());
  });
  const joinedEntry = nextPlayers.find((entry) => entry?.token === playerToken) || null;
  publishCoolJpegsDeckPlayerJoin(normalizedDeckId, joinedEntry).catch((error) => {
    console.error(error);
    setRealtimeStatus('firebase: write blocked');
  });
}

function leaveCoolJpegsDeckAsLocalPlayer(deckId = activeDeckId) {
  const normalizedDeckId = normalizeDeckId(deckId);
  if (!normalizedDeckId || getDeckKind(normalizedDeckId) !== DECK_KIND_COOL) {
    return;
  }
  const playerToken = getLocalCoolJpegsPlayerToken();
  if (!playerToken) {
    return;
  }
  const existingPlayers = getDeckCoolJpegsPlayers(normalizedDeckId);
  if (!existingPlayers.some((entry) => entry?.token === playerToken)) {
    return;
  }
  const nextPlayers = normalizeDeckCoolJpegsPlayersPayload(
    existingPlayers.filter((entry) => String(entry?.token || '').trim() !== playerToken)
  );
  coolJpegsPlayersByDeckId.set(normalizedDeckId, nextPlayers);
  runRenderSafely('leaveCoolJpegsDeckAsLocalPlayer', () => {
    renderDeckControls(buildDeckCardMetrics());
  });
  publishCoolJpegsDeckPlayerLeave(normalizedDeckId, playerToken).catch((error) => {
    console.error(error);
    setRealtimeStatus('firebase: write blocked');
  });
}

function getLocalCoolJpegsHandCardCount() {
  let count = 0;
  for (const [cardId, cardState] of cards.entries()) {
    if (!cardState || typeof cardState !== 'object') {
      continue;
    }
    if (!isCardOwnedByLocalHandOwner(getCardHandOwnerId(cardState))) {
      continue;
    }
    const cardDeckId = getCardDeckInstanceId(cardId, cardState);
    if (getDeckKind(cardDeckId) !== DECK_KIND_COOL) {
      continue;
    }
    count += 1;
  }
  return count;
}

async function toggleCoolJpegsDeckMembership(deckId = activeDeckId) {
  const normalizedDeckId = normalizeDeckId(deckId);
  if (!normalizedDeckId || getDeckKind(normalizedDeckId) !== DECK_KIND_COOL) {
    return;
  }
  const playerToken = getLocalCoolJpegsPlayerToken();
  if (!playerToken) {
    return;
  }
  const players = getDeckCoolJpegsPlayers(normalizedDeckId);
  const isJoined = players.some((entry) => String(entry?.token || '').trim() === playerToken);
  if (isJoined) {
    const localEntry =
      players.find((entry) => String(entry?.token || '').trim() === playerToken) || null;
    const localMoney = Math.max(
      0,
      Math.round(Number(localEntry?.money) || COOL_JPEGS_STARTING_MONEY)
    );
    const hasCoolJpegsCardsInHand = getLocalCoolJpegsHandCardCount() > 0;
    const hasCustomMoney = localMoney !== COOL_JPEGS_STARTING_MONEY;
    if (hasCoolJpegsCardsInHand || hasCustomMoney) {
      const shouldContinue = await openClearTableWarningModal();
      if (!shouldContinue) {
        return;
      }
    }
    leaveCoolJpegsDeckAsLocalPlayer(normalizedDeckId);
    return;
  }
  const activeMembership = getLocalCoolJpegsMembership();
  if (activeMembership.deckId && activeMembership.deckId !== normalizedDeckId) {
    showStatusMessage('you can only be in one cool jpegs game at a time');
    return;
  }
  joinCoolJpegsDeckAsLocalPlayer(normalizedDeckId);
}

function getDeckDisplayName(deckId = activeDeckId) {
  const deckKind = getDeckKind(deckId);
  if (deckKind === DECK_KIND_POKER) {
    return 'poker deck';
  }
  if (deckKind === DECK_KIND_CODEGAME) {
    return 'codegame';
  }
  if (deckKind === DECK_KIND_COOL) {
    return 'cool jpegs';
  }
  return 'deck';
}

function isDeckDiscardEnabled(deckId = activeDeckId) {
  const normalizedDeckId = normalizeDeckId(deckId);
  if (!deckSupportsDiscard(normalizedDeckId)) {
    return false;
  }
  return getDeckStateById(normalizedDeckId)?.includeDiscard !== false;
}

function getMonsGameStateById(gameId = activeMonsGameId) {
  const normalizedMonsGameId = normalizeMonsGameId(gameId);
  return monsGameStatesById.get(normalizedMonsGameId) || null;
}

function getTaflGameStateById(gameId = activeTaflGameId) {
  const normalizedTaflGameId = normalizeTaflGameId(gameId);
  return taflGameStatesById.get(normalizedTaflGameId) || null;
}

function getGoGameStateById(gameId = activeGoGameId) {
  const normalizedGoGameId = normalizeGoGameId(gameId);
  return goGameStatesById.get(normalizedGoGameId) || null;
}

function getHexitamaGameStateById(gameId = activeHexitamaGameId) {
  const normalizedHexitamaGameId = normalizeHexitamaGameId(gameId);
  return hexitamaGameStatesById.get(normalizedHexitamaGameId) || null;
}

function patchTouchesPosition(patch) {
  if (!patch || typeof patch !== 'object') {
    return false;
  }
  return (
    Object.prototype.hasOwnProperty.call(patch, 'x') ||
    Object.prototype.hasOwnProperty.call(patch, 'y')
  );
}

function isDeckCoverDrawingsEnabled(deckId = activeDeckId) {
  return Boolean(getDeckStateById(deckId)?.coverDrawings === true);
}

function isMonsShowCoordinatesEnabled(gameId = activeMonsGameId) {
  return Boolean(getMonsGameStateById(gameId)?.showCoordinates !== false);
}

function isTaflShowCoordinatesEnabled(gameId = activeTaflGameId) {
  return Boolean(getTaflGameStateById(gameId)?.showCoordinates !== false);
}

function isGoShowCoordinatesEnabled(gameId = activeGoGameId) {
  return Boolean(getGoGameStateById(gameId)?.showCoordinates !== false);
}

function isMonsCoverDrawingsEnabled(gameId = activeMonsGameId) {
  return Boolean(getMonsGameStateById(gameId)?.coverDrawings === true);
}

function isTaflCoverDrawingsEnabled(gameId = activeTaflGameId) {
  return Boolean(getTaflGameStateById(gameId)?.coverDrawings === true);
}

function isGoCoverDrawingsEnabled(gameId = activeGoGameId) {
  return Boolean(getGoGameStateById(gameId)?.coverDrawings === true);
}

function isHexitamaCoverDrawingsEnabled(gameId = activeHexitamaGameId) {
  return Boolean(getHexitamaGameStateById(gameId)?.coverDrawings === true);
}

function hasAnyCoverDrawingsGames() {
  for (const deckState of deckStatesById.values()) {
    if (deckState?.coverDrawings === true) {
      return true;
    }
  }
  for (const gameState of monsGameStatesById.values()) {
    if (gameState?.enabled !== false && gameState?.coverDrawings === true) {
      return true;
    }
  }
  for (const gameState of taflGameStatesById.values()) {
    if (gameState?.enabled !== false && gameState?.coverDrawings === true) {
      return true;
    }
  }
  for (const gameState of goGameStatesById.values()) {
    if (gameState?.enabled !== false && gameState?.coverDrawings === true) {
      return true;
    }
  }
  for (const gameState of hexitamaGameStatesById.values()) {
    if (gameState?.enabled !== false && gameState?.coverDrawings === true) {
      return true;
    }
  }
  return false;
}

function syncCoverDrawingsGamesLayerState() {
  tableRoot?.classList.toggle('has-cover-drawings-games', hasAnyCoverDrawingsGames());
}

function createEmptyDeckCardMetricsEntry() {
  return {
    inDeckIds: [],
    inDiscardIds: [],
    inAuctionIds: [],
    inAuctionPrimaryIds: [],
    inAuctionSecondaryIds: [],
    inDeckCount: 0,
    inDiscardCount: 0,
    inAuctionCount: 0,
    inAuctionPrimaryCount: 0,
    inAuctionSecondaryCount: 0,
    topDeckZ: 1,
    topDiscardZ: 1,
    topAuctionZ: 1,
    topAuctionPrimaryZ: 1,
    topAuctionSecondaryZ: 1,
    topDeckCardId: '',
    topDiscardCardId: '',
    topAuctionCardId: '',
    topAuctionPrimaryCardId: '',
    topAuctionSecondaryCardId: ''
  };
}

function markCardDeckMetricsCacheDirty() {
  cardDeckMetricsCacheDirty = true;
}

function markCameraLooseRenderableCardIdsDirty() {
  cameraLooseRenderableCardIdsDirty = true;
}

function getCameraLooseRenderableCardIdsCache() {
  if (!cameraLooseRenderableCardIdsDirty) {
    return cameraLooseRenderableCardIds;
  }
  const nextIds = new Set();
  for (const [cardId, cardState] of cards.entries()) {
    if (!cardState || typeof cardState !== 'object') {
      continue;
    }
    if (getCardHandOwnerId(cardState)) {
      continue;
    }
    if (cardState.inDeck || cardState.inDiscard || cardState.inAuction) {
      continue;
    }
    nextIds.add(cardId);
  }
  cameraLooseRenderableCardIds = nextIds;
  cameraLooseRenderableCardIdsDirty = false;
  return cameraLooseRenderableCardIds;
}

function didCardDeckMetricsFieldsChange(previousCardState, nextCardState) {
  if (!previousCardState || !nextCardState) {
    return true;
  }
  if (getCardDeckId(previousCardState) !== getCardDeckId(nextCardState)) {
    return true;
  }
  if (Boolean(previousCardState.inDeck) !== Boolean(nextCardState.inDeck)) {
    return true;
  }
  if (Boolean(previousCardState.inDiscard) !== Boolean(nextCardState.inDiscard)) {
    return true;
  }
  if (Boolean(previousCardState.inAuction) !== Boolean(nextCardState.inAuction)) {
    return true;
  }
  if (
    previousCardState.inAuction === true &&
    nextCardState.inAuction === true &&
    getCardAuctionSlotIndex(previousCardState) !== getCardAuctionSlotIndex(nextCardState)
  ) {
    return true;
  }
  const previousInStack =
    previousCardState.inDeck === true ||
    previousCardState.inDiscard === true ||
    previousCardState.inAuction === true;
  const nextInStack =
    nextCardState.inDeck === true ||
    nextCardState.inDiscard === true ||
    nextCardState.inAuction === true;
  if (!previousInStack && !nextInStack) {
    return false;
  }
  return (Number(previousCardState.z) || 1) !== (Number(nextCardState.z) || 1);
}

function getCardDeckMetricsCache() {
  if (!cardDeckMetricsCacheDirty) {
    return cardDeckMetricsCache;
  }
  const metricsByDeck = new Map();
  for (const [cardId, cardState] of cards.entries()) {
    if (!cardState || typeof cardState !== 'object') {
      continue;
    }
    const normalizedDeckId = getCardDeckId(cardState, cardId);
    if (!normalizedDeckId) {
      continue;
    }
    let metrics = metricsByDeck.get(normalizedDeckId);
    if (!metrics) {
      metrics = createEmptyDeckCardMetricsEntry();
      metricsByDeck.set(normalizedDeckId, metrics);
    }
    const zoneZ = Number(cardState.z) || 1;
    if (cardState.inDeck) {
      metrics.inDeckIds.push(cardId);
      metrics.inDeckCount += 1;
      if (zoneZ >= metrics.topDeckZ) {
        metrics.topDeckZ = zoneZ;
        metrics.topDeckCardId = cardId;
      }
    }
    if (cardState.inDiscard) {
      metrics.inDiscardIds.push(cardId);
      metrics.inDiscardCount += 1;
      if (zoneZ >= metrics.topDiscardZ) {
        metrics.topDiscardZ = zoneZ;
        metrics.topDiscardCardId = cardId;
      }
    }
    if (cardState.inAuction) {
      const auctionSlotIndex = normalizeAuctionSlotIndex(cardState.auctionSlotIndex);
      metrics.inAuctionIds.push(cardId);
      metrics.inAuctionCount += 1;
      if (zoneZ >= metrics.topAuctionZ) {
        metrics.topAuctionZ = zoneZ;
        metrics.topAuctionCardId = cardId;
      }
      if (auctionSlotIndex === 1) {
        metrics.inAuctionSecondaryIds.push(cardId);
        metrics.inAuctionSecondaryCount += 1;
        if (zoneZ >= metrics.topAuctionSecondaryZ) {
          metrics.topAuctionSecondaryZ = zoneZ;
          metrics.topAuctionSecondaryCardId = cardId;
        }
      } else {
        metrics.inAuctionPrimaryIds.push(cardId);
        metrics.inAuctionPrimaryCount += 1;
        if (zoneZ >= metrics.topAuctionPrimaryZ) {
          metrics.topAuctionPrimaryZ = zoneZ;
          metrics.topAuctionPrimaryCardId = cardId;
        }
      }
    }
  }
  cardDeckMetricsCache = {
    deckIds: Array.from(metricsByDeck.keys()),
    metricsByDeck
  };
  cardDeckMetricsCacheDirty = false;
  return cardDeckMetricsCache;
}

function getDeckMetricsEntry(deckId = activeDeckId) {
  const normalizedDeckId = normalizeDeckId(deckId);
  return getCardDeckMetricsCache().metricsByDeck.get(normalizedDeckId) || null;
}

function getDeckIdsInRoom() {
  const cardCache = getCardDeckMetricsCache();
  if (deckStatesById.size === 0) {
    return cardCache.deckIds.filter((deckId) => !isHexitamaCardDeckId(deckId));
  }
  const deckIds = new Set(
    Array.from(deckStatesById.keys()).filter((deckId) => !isHexitamaCardDeckId(deckId))
  );
  for (const deckId of cardCache.deckIds) {
    if (isHexitamaCardDeckId(deckId)) {
      continue;
    }
    deckIds.add(deckId);
  }
  return Array.from(deckIds);
}

function buildDeckCardMetrics() {
  return {
    deckIds: getDeckIdsInRoom(),
    metricsByDeck: getCardDeckMetricsCache().metricsByDeck
  };
}

function getVisibleStackCardIdsFromMetrics(metricsByDeck) {
  const visibleIds = new Set();
  if (!(metricsByDeck instanceof Map)) {
    return visibleIds;
  }
  for (const metrics of metricsByDeck.values()) {
    if (!metrics || typeof metrics !== 'object') {
      continue;
    }
    const topDeckCardId = String(metrics.topDeckCardId || '').trim();
    const topDiscardCardId = String(metrics.topDiscardCardId || '').trim();
    const topAuctionCardId = String(metrics.topAuctionCardId || '').trim();
    const topAuctionPrimaryCardId = String(metrics.topAuctionPrimaryCardId || '').trim();
    const topAuctionSecondaryCardId = String(metrics.topAuctionSecondaryCardId || '').trim();
    if (topDeckCardId) {
      visibleIds.add(topDeckCardId);
    }
    if (topDiscardCardId) {
      visibleIds.add(topDiscardCardId);
    }
    if (topAuctionCardId) {
      visibleIds.add(topAuctionCardId);
    }
    if (topAuctionPrimaryCardId) {
      visibleIds.add(topAuctionPrimaryCardId);
    }
    if (topAuctionSecondaryCardId) {
      visibleIds.add(topAuctionSecondaryCardId);
    }
  }
  return visibleIds;
}

function getDeckCenterPosition(deckId = activeDeckId) {
  const state = getDeckStateById(deckId);
  if (state) {
    return {
      x: state.x,
      y: state.y
    };
  }
  return {
    x: WORLD_WIDTH / 2,
    y: WORLD_HEIGHT / 2
  };
}

function getDeckBaseCardDimensions(deckId = activeDeckId) {
  const deckKind = getDeckKind(deckId);
  if (deckKind === DECK_KIND_CODEGAME) {
    return {
      width: CODEGAME_CARD_SIZE,
      height: CODEGAME_CARD_SIZE
    };
  }
  return {
    width: CARD_WIDTH,
    height: CARD_HEIGHT
  };
}

function getDeckControlScale(deckId = activeDeckId) {
  return getDeckKind(deckId) === DECK_KIND_CODEGAME ? CODEGAME_MODULE_SCALE : 1;
}

function isComboAuctionSecondarySlotVisibleForDeck(deckId = activeDeckId) {
  const normalizedDeckId = normalizeDeckId(deckId);
  if (!normalizedDeckId) {
    return false;
  }
  if (getDeckKind(normalizedDeckId) !== DECK_KIND_COOL) {
    return false;
  }

  // Prefer the full helper when available (it may be defined in a deeper scope in
  // some builds). Fall back to a local-safe calculation to avoid render crashes.
  if (typeof isComboAuctionSecondarySlotVisible === 'function') {
    try {
      return Boolean(isComboAuctionSecondarySlotVisible(normalizedDeckId));
    } catch (error) {
      console.error(error);
    }
  }

  const secondaryAuctionCardId = String(getDeckMetricsEntry(normalizedDeckId)?.topAuctionSecondaryCardId || '').trim();
  if (secondaryAuctionCardId) {
    return true;
  }
  const primaryAuctionCardId = String(getDeckMetricsEntry(normalizedDeckId)?.topAuctionPrimaryCardId || '').trim();
  if (!primaryAuctionCardId) {
    return false;
  }
  const primaryCardState = cards.get(primaryAuctionCardId);
  const info = resolveCoolJpegsCardInfo(primaryCardState, primaryAuctionCardId);
  return normalizeCoolJpegsAuctionType(info?.auctionType || '') === 'combo';
}

function getDeckModuleWorldDimensions(deckId = activeDeckId, deckStateOverride = null) {
  const normalizedDeckId = normalizeDeckId(deckId);
  const deckState = deckStateOverride && typeof deckStateOverride === 'object'
    ? deckStateOverride
    : getDeckStateById(normalizedDeckId);
  const deckDimensions = getDeckBaseCardDimensions(normalizedDeckId);
  const controlScale = getDeckControlScale(normalizedDeckId);
  const controlSize = DECK_CONTROL_SIZE * controlScale;
  if (getDeckKind(normalizedDeckId) === DECK_KIND_COOL) {
    const deckCenter = getDeckCenterPosition(normalizedDeckId);
    const boardCenter = getCoolJpegsArtistsBoardCenterPosition(normalizedDeckId);
    const boardSize = getCoolJpegsArtistsBoardWorldSize(normalizedDeckId);
    const discardCenter = getCoolJpegsDiscardCenterPosition(normalizedDeckId);
    const auctionCenter = getCoolJpegsAuctionCenterPosition(normalizedDeckId, 0);
    const secondaryAuctionVisible = isComboAuctionSecondarySlotVisibleForDeck(normalizedDeckId);
    const auctionSecondaryCenter = secondaryAuctionVisible
      ? getCoolJpegsAuctionCenterPosition(normalizedDeckId, 1)
      : null;
    const auctionSize = {
      width: deckDimensions.width + AUCTION_SLOT_EXTRA_SIZE,
      height: deckDimensions.height + AUCTION_SLOT_EXTRA_SIZE
    };
    const left = Math.min(
      deckCenter.x - deckDimensions.width / 2,
      discardCenter.x - deckDimensions.width / 2,
      boardCenter.x - boardSize.width / 2,
      auctionCenter.x - auctionSize.width / 2
    );
    let right = Math.max(
      deckCenter.x + deckDimensions.width / 2,
      discardCenter.x + deckDimensions.width / 2,
      boardCenter.x + boardSize.width / 2,
      auctionCenter.x + auctionSize.width / 2
    );
    right = Math.max(right, auctionCenter.x + auctionSize.width / 2 + controlSize * 2.8);
    let top = Math.min(
      deckCenter.y - deckDimensions.height / 2,
      discardCenter.y - deckDimensions.height / 2,
      boardCenter.y - boardSize.height / 2,
      auctionCenter.y - auctionSize.height / 2
    );
    if (auctionSecondaryCenter) {
      top = Math.min(top, auctionSecondaryCenter.y - auctionSize.height / 2);
    }
    const bottom = Math.max(
      deckCenter.y + deckDimensions.height / 2 + controlSize * 2.3,
      discardCenter.y + deckDimensions.height / 2,
      boardCenter.y + boardSize.height / 2,
      auctionCenter.y + auctionSize.height / 2
    );
    const radiusX = Math.max(Math.abs(left - deckCenter.x), Math.abs(right - deckCenter.x));
    const radiusY = Math.max(Math.abs(top - deckCenter.y), Math.abs(bottom - deckCenter.y));
    return {
      width: Math.max(deckDimensions.width, radiusX * 2),
      height: Math.max(deckDimensions.height, radiusY * 2)
    };
  }
  const supportsAuction = deckSupportsAuction(normalizedDeckId);
  let deckWorldWidth = supportsAuction
    ? Math.abs(AUCTION_STACK_OFFSET_X) + deckDimensions.width + AUCTION_SLOT_EXTRA_SIZE + controlSize * 2.6
    : deckDimensions.width + controlSize * 2.6;
  const isCodegameDeck = getDeckKind(normalizedDeckId) === DECK_KIND_CODEGAME;
  const codegameGridActive = isCodegameDeck && deckState?.codegameGridActive === true;
  let codegameGridDimensions = null;
  if (codegameGridActive) {
    codegameGridDimensions = getCodegameGridWorldDimensions();
    if (codegameGridDimensions) {
      deckWorldWidth = Math.max(deckWorldWidth, codegameGridDimensions.width);
    }
  }
  const deckWorldHeight = codegameGridActive && codegameGridDimensions
    ? deckDimensions.height + controlSize * 3.2 + CODEGAME_GRID_OFFSET_Y + codegameGridDimensions.height
    : deckDimensions.height + controlSize * 3.2;
  return {
    width: Math.max(deckDimensions.width, deckWorldWidth),
    height: Math.max(deckDimensions.height, deckWorldHeight)
  };
}

function getDiscardCenterPosition(deckId = activeDeckId) {
  if (getDeckKind(deckId) === DECK_KIND_COOL) {
    return getCoolJpegsDiscardCenterPosition(deckId);
  }
  const deckCenter = getDeckCenterPosition(deckId);
  return {
    x: deckCenter.x - DISCARD_STACK_OFFSET_X,
    y: deckCenter.y
  };
}

function getAuctionCenterPosition(deckId = activeDeckId, slotIndex = 0) {
  if (getDeckKind(deckId) === DECK_KIND_COOL) {
    return getCoolJpegsAuctionCenterPosition(deckId, slotIndex);
  }
  const deckCenter = getDeckCenterPosition(deckId);
  return {
    x: deckCenter.x + AUCTION_STACK_OFFSET_X,
    y: deckCenter.y
  };
}

function getCoolJpegsArtistsBoardWorldSize(deckId = activeDeckId) {
  const deckDimensions = getDeckBaseCardDimensions(deckId);
  const width = deckDimensions.width * COOL_JPEGS_ARTISTS_BOARD_WIDTH_MULTIPLIER;
  return {
    width,
    height: width * COOL_JPEGS_ARTISTS_BOARD_ASPECT_RATIO
  };
}

function getCoolJpegsArtistsBoardCenterPosition(deckId = activeDeckId) {
  const deckCenter = getDeckCenterPosition(deckId);
  const deckDimensions = getDeckBaseCardDimensions(deckId);
  const boardSize = getCoolJpegsArtistsBoardWorldSize(deckId);
  return {
    x: deckCenter.x + deckDimensions.width / 2 + deckDimensions.width * COOL_JPEGS_BOARD_GAP_X_MULTIPLIER + boardSize.width / 2,
    // Keep board bottom aligned with deck bottom.
    y: deckCenter.y + (deckDimensions.height - boardSize.height) / 2
  };
}

function getCoolJpegsDiscardCenterPosition(deckId = activeDeckId) {
  const boardCenter = getCoolJpegsArtistsBoardCenterPosition(deckId);
  const boardSize = getCoolJpegsArtistsBoardWorldSize(deckId);
  const deckDimensions = getDeckBaseCardDimensions(deckId);
  return {
    x: getDeckCenterPosition(deckId).x,
    // Keep discard top aligned with board top.
    y: boardCenter.y - boardSize.height / 2 + deckDimensions.height / 2
  };
}

function getCoolJpegsAuctionCenterPosition(deckId = activeDeckId, slotIndex = 0) {
  const deckCenter = getDeckCenterPosition(deckId);
  const deckDimensions = getDeckBaseCardDimensions(deckId);
  const boardCenter = getCoolJpegsArtistsBoardCenterPosition(deckId);
  const boardSize = getCoolJpegsArtistsBoardWorldSize(deckId);
  const auctionWidth = deckDimensions.width + AUCTION_SLOT_EXTRA_SIZE;
  const auctionHeight = deckDimensions.height + AUCTION_SLOT_EXTRA_SIZE;
  const normalizedSlotIndex = normalizeAuctionSlotIndex(slotIndex);
  const verticalOffset = normalizedSlotIndex === 1
    ? -(auctionHeight + COOL_JPEGS_COMBO_AUCTION_SLOT_GAP)
    : 0;
  return {
    x: boardCenter.x + boardSize.width / 2 + deckDimensions.width * COOL_JPEGS_AUCTION_GAP_X_MULTIPLIER + auctionWidth / 2,
    // Keep auction bottom aligned with board bottom.
    y: boardCenter.y + boardSize.height / 2 - auctionHeight / 2 + verticalOffset
  };
}

function getCoolJpegsModuleBoundsForDeckCenter(deckCenter, deckId = DECK_KEY) {
  const deckDimensions = getDeckBaseCardDimensions(deckId);
  const controlScale = getDeckControlScale(deckId);
  const controlSize = DECK_CONTROL_SIZE * controlScale;
  const deckWidth = deckDimensions.width;
  const deckHeight = deckDimensions.height;
  const boardWidth = deckWidth * COOL_JPEGS_ARTISTS_BOARD_WIDTH_MULTIPLIER;
  const boardHeight = boardWidth * COOL_JPEGS_ARTISTS_BOARD_ASPECT_RATIO;
  const boardCenterX =
    Number(deckCenter.x) +
    deckWidth / 2 +
    deckWidth * COOL_JPEGS_BOARD_GAP_X_MULTIPLIER +
    boardWidth / 2;
  const boardCenterY = Number(deckCenter.y) + (deckHeight - boardHeight) / 2;
  const discardCenterX = Number(deckCenter.x);
  const discardCenterY = boardCenterY - boardHeight / 2 + deckHeight / 2;
  const auctionWidth = deckWidth + AUCTION_SLOT_EXTRA_SIZE;
  const auctionHeight = deckHeight + AUCTION_SLOT_EXTRA_SIZE;
  const auctionCenterX =
    boardCenterX +
    boardWidth / 2 +
    deckWidth * COOL_JPEGS_AUCTION_GAP_X_MULTIPLIER +
    auctionWidth / 2;
  const auctionCenterY = boardCenterY + boardHeight / 2 - auctionHeight / 2;
  const left = Math.min(
    Number(deckCenter.x) - deckWidth / 2,
    discardCenterX - deckWidth / 2,
    boardCenterX - boardWidth / 2,
    auctionCenterX - auctionWidth / 2
  );
  const right = Math.max(
    Number(deckCenter.x) + deckWidth / 2,
    discardCenterX + deckWidth / 2,
    boardCenterX + boardWidth / 2,
    auctionCenterX + auctionWidth / 2 + controlSize * 2.8
  );
  const top = Math.min(
    Number(deckCenter.y) - deckHeight / 2,
    discardCenterY - deckHeight / 2,
    boardCenterY - boardHeight / 2,
    auctionCenterY - auctionHeight / 2
  );
  const bottom = Math.max(
    Number(deckCenter.y) + deckHeight / 2 + controlSize * 2.3,
    discardCenterY + deckHeight / 2,
    boardCenterY + boardHeight / 2,
    auctionCenterY + auctionHeight / 2
  );
  return { left, right, top, bottom };
}

function getCoolJpegsSpawnDeckCenterForViewport(viewportCenter) {
  const centerX = Number(viewportCenter?.x);
  const centerY = Number(viewportCenter?.y);
  const desiredViewportCenter = {
    x: Number.isFinite(centerX) ? centerX : WORLD_WIDTH / 2,
    y: Number.isFinite(centerY) ? centerY : WORLD_HEIGHT / 2
  };
  const deckDimensions = getDeckBaseCardDimensions(DECK_KEY);
  const minDeckX = deckDimensions.width / 2;
  const maxDeckX = WORLD_WIDTH - minDeckX;
  const minDeckY = deckDimensions.height / 2;
  const maxDeckY = WORLD_HEIGHT - minDeckY;
  const nextCenter = {
    x: clamp(desiredViewportCenter.x, minDeckX, maxDeckX),
    y: clamp(desiredViewportCenter.y, minDeckY, maxDeckY)
  };

  // Shift deck center so the full Cool Jpegs module is centered in view.
  let bounds = getCoolJpegsModuleBoundsForDeckCenter(nextCenter, DECK_KEY);
  const moduleCenterX = (bounds.left + bounds.right) / 2;
  const moduleCenterY = (bounds.top + bounds.bottom) / 2;
  nextCenter.x += desiredViewportCenter.x - moduleCenterX;
  nextCenter.y += desiredViewportCenter.y - moduleCenterY;

  // Keep the full module within world bounds.
  bounds = getCoolJpegsModuleBoundsForDeckCenter(nextCenter, DECK_KEY);
  if (bounds.left < 0) {
    nextCenter.x += -bounds.left;
  }
  if (bounds.right > WORLD_WIDTH) {
    nextCenter.x -= bounds.right - WORLD_WIDTH;
  }
  if (bounds.top < 0) {
    nextCenter.y += -bounds.top;
  }
  if (bounds.bottom > WORLD_HEIGHT) {
    nextCenter.y -= bounds.bottom - WORLD_HEIGHT;
  }

  nextCenter.x = clamp(nextCenter.x, minDeckX, maxDeckX);
  nextCenter.y = clamp(nextCenter.y, minDeckY, maxDeckY);
  return nextCenter;
}

function getCodegameGridWorldDimensions() {
  const cardSize = CODEGAME_CARD_SIZE;
  const totalCards = CODEGAME_GRID_SIZE;
  const totalGap = Math.max(0, totalCards - 1) * CODEGAME_GRID_GAP;
  const totalCardSpan = totalCards * cardSize;
  const side = totalCardSpan + totalGap + CODEGAME_GRID_PADDING * 2;
  return {
    width: side,
    height: side
  };
}

function getCodegameGridCenterPosition(deckId = activeDeckId) {
  const deckCenter = getDeckCenterPosition(deckId);
  const deckDimensions = getDeckBaseCardDimensions(deckId);
  const gridDimensions = getCodegameGridWorldDimensions();
  return {
    x: deckCenter.x,
    y: deckCenter.y - deckDimensions.height / 2 - CODEGAME_GRID_OFFSET_Y - gridDimensions.height / 2
  };
}

function getCodegameGridSlotWorldPosition(deckId = activeDeckId, slotIndex = 0) {
  const normalizedIndex = Math.max(0, Number(slotIndex) || 0);
  const row = Math.floor(normalizedIndex / CODEGAME_GRID_SIZE);
  const col = normalizedIndex % CODEGAME_GRID_SIZE;
  const gridCenter = getCodegameGridCenterPosition(deckId);
  const gridDimensions = getCodegameGridWorldDimensions();
  const gridLeft = gridCenter.x - gridDimensions.width / 2;
  const gridTop = gridCenter.y - gridDimensions.height / 2;
  const step = CODEGAME_CARD_SIZE + CODEGAME_GRID_GAP;
  const rawX = gridLeft + CODEGAME_GRID_PADDING + CODEGAME_CARD_SIZE / 2 + col * step;
  const rawY = gridTop + CODEGAME_GRID_PADDING + CODEGAME_CARD_SIZE / 2 + row * step;
  return {
    x: clamp(rawX, CODEGAME_CARD_SIZE / 2, WORLD_WIDTH - CODEGAME_CARD_SIZE / 2),
    y: clamp(rawY, CODEGAME_CARD_SIZE / 2, WORLD_HEIGHT - CODEGAME_CARD_SIZE / 2)
  };
}

function getCodegameKeyCardIds(deckId = activeDeckId) {
  const normalizedDeckId = normalizeDeckId(deckId);
  return CODEGAME_KEY_CARD_ID_SUFFIXES.map((suffix) => `${normalizedDeckId}-${suffix}`);
}

function getCodegameKeyCardIndex(cardId = '', cardState = null) {
  const normalizedCardId = String(cardId || '').trim();
  const resolvedCardState =
    cardState && typeof cardState === 'object'
      ? cardState
      : cards.get(normalizedCardId);
  if (!isCodegameKeyCardState(resolvedCardState)) {
    return -1;
  }
  const deckId = getCardDeckId(resolvedCardState, normalizedCardId);
  if (!deckId) {
    return -1;
  }
  if (normalizedCardId) {
    const indexedKeyIds = getCodegameKeyCardIds(deckId);
    const indexedMatch = indexedKeyIds.indexOf(normalizedCardId);
    if (indexedMatch >= 0) {
      return indexedMatch;
    }
  }
  if (normalizedCardId) {
    for (let index = 0; index < CODEGAME_KEY_CARD_ID_SUFFIXES.length; index += 1) {
      const suffix = CODEGAME_KEY_CARD_ID_SUFFIXES[index];
      if (normalizedCardId.endsWith(`-${suffix}`)) {
        return index;
      }
    }
  }
  return 0;
}

function getCodegameKeyCardWorldPosition(deckId = activeDeckId, keyIndex = 0) {
  const normalizedIndex = Math.max(0, Math.floor(Number(keyIndex) || 0));
  const gridCenter = getCodegameGridCenterPosition(deckId);
  const gridDimensions = getCodegameGridWorldDimensions();
  const verticalStep = CODEGAME_CARD_SIZE + CODEGAME_KEY_CARD_GAP_Y;
  const pairStartY = gridCenter.y - (verticalStep * (CODEGAME_KEY_CARD_ID_SUFFIXES.length - 1)) / 2;
  const rawX = gridCenter.x - gridDimensions.width / 2 - CODEGAME_CARD_SIZE / 2 - CODEGAME_KEY_CARD_OFFSET_X;
  const rawY = pairStartY + normalizedIndex * verticalStep;
  return {
    x: clamp(rawX, CODEGAME_CARD_SIZE / 2, WORLD_WIDTH - CODEGAME_CARD_SIZE / 2),
    y: clamp(rawY, CODEGAME_CARD_SIZE / 2, WORLD_HEIGHT - CODEGAME_CARD_SIZE / 2)
  };
}

function getCodegameKeyCardExpectedWorldCenter(cardId = '', cardState = null, options = {}) {
  const normalizedCardId = String(cardId || '').trim();
  const resolvedCardState =
    cardState && typeof cardState === 'object'
      ? cardState
      : cards.get(normalizedCardId);
  if (!isCodegameKeyCardState(resolvedCardState)) {
    return null;
  }
  const requireAnchored = options?.requireAnchored !== false;
  if (requireAnchored && resolvedCardState.codegameKeyAnchored !== true) {
    return null;
  }
  const requireAvailable = options?.requireAvailable !== false;
  if (
    requireAvailable &&
    (
      resolvedCardState.inDeck ||
      resolvedCardState.inDiscard ||
      resolvedCardState.inAuction ||
      Boolean(resolvedCardState.holderClientId) ||
      Boolean(getCardHandOwnerId(resolvedCardState))
    )
  ) {
    return null;
  }
  const deckId = getCardDeckId(resolvedCardState, normalizedCardId);
  if (!deckId) {
    return null;
  }
  const targetDeckState = getDeckStateById(deckId);
  if (!targetDeckState || targetDeckState.codegameGridActive !== true) {
    return null;
  }
  const keyIndex = getCodegameKeyCardIndex(normalizedCardId, resolvedCardState);
  if (keyIndex < 0) {
    return null;
  }
  return getCodegameKeyCardWorldPosition(deckId, keyIndex);
}

function getCodegameKeyCardWorldCenter(cardId = '', cardState = null) {
  return getCodegameKeyCardExpectedWorldCenter(cardId, cardState, { requireAnchored: true });
}

function isCodegameKeyCardState(cardState) {
  return isCodegameCardState(cardState) && cardState?.codegameKeyCard === true;
}

function invalidateLocalCodegameKeyHighlightsCache() {
  localCodegameKeyHighlightsCacheDirty = true;
}

function invalidateCodegameKeyPatternCache() {
  codegameKeyPatternCacheDirty = true;
}

function getLocalCodegameKeyHighlightsByDeck() {
  const cacheToken = `${localPlayerToken}|${localClientId}`;
  if (!localCodegameKeyHighlightsCacheDirty && localCodegameKeyHighlightsCacheToken === cacheToken) {
    return localCodegameKeyHighlightsByDeck;
  }
  localCodegameKeyHighlightsCacheToken = cacheToken;
  localCodegameKeyHighlightsByDeck = new Map();
  for (const [cardId, cardState] of cards.entries()) {
    if (!isCodegameKeyCardState(cardState)) {
      continue;
    }
    const handOwnerId = getCardHandOwnerId(cardState);
    if (!handOwnerId || !isCardOwnedByLocalHandOwner(handOwnerId)) {
      continue;
    }
    const deckId = getCardDeckId(cardState, cardId);
    if (!deckId) {
      continue;
    }
    const blue = normalizeCodegameKeyIndexList(cardState.codegameKeyBlueIndices, CODEGAME_KEY_BLUE_COUNT);
    const red = normalizeCodegameKeyIndexList(cardState.codegameKeyRedIndices, CODEGAME_KEY_RED_COUNT);
    const assassinValue = Number(cardState.codegameKeyAssassinIndex);
    const assassinIndex = Number.isInteger(assassinValue)
      ? clamp(assassinValue, 0, CODEGAME_KEY_TOTAL_CELLS - 1)
      : -1;
    localCodegameKeyHighlightsByDeck.set(deckId, {
      blue: new Set(blue),
      red: new Set(red),
      assassin: assassinIndex
    });
  }
  localCodegameKeyHighlightsCacheDirty = false;
  return localCodegameKeyHighlightsByDeck;
}

function getCodegameKeyPatternByDeck() {
  if (!codegameKeyPatternCacheDirty) {
    return codegameKeyPatternByDeck;
  }
  const nextPatternByDeck = new Map();
  for (const [cardId, cardState] of cards.entries()) {
    if (!isCodegameKeyCardState(cardState)) {
      continue;
    }
    const deckId = getCardDeckId(cardState, cardId);
    if (!deckId || nextPatternByDeck.has(deckId)) {
      continue;
    }
    const blue = normalizeCodegameKeyIndexList(cardState.codegameKeyBlueIndices, CODEGAME_KEY_BLUE_COUNT);
    const red = normalizeCodegameKeyIndexList(cardState.codegameKeyRedIndices, CODEGAME_KEY_RED_COUNT);
    const assassinValue = Number(cardState.codegameKeyAssassinIndex);
    const assassinIndex = Number.isInteger(assassinValue)
      ? clamp(assassinValue, 0, CODEGAME_KEY_TOTAL_CELLS - 1)
      : -1;
    nextPatternByDeck.set(deckId, {
      blue: new Set(blue),
      red: new Set(red),
      assassin: assassinIndex
    });
  }
  codegameKeyPatternByDeck = nextPatternByDeck;
  codegameKeyPatternCacheDirty = false;
  return codegameKeyPatternByDeck;
}

function getCodegameSharedMarkTypeForSlot(deckId, slotIndex) {
  const normalizedSlotIndex = Number(slotIndex);
  if (!Number.isInteger(normalizedSlotIndex) || normalizedSlotIndex < 0 || normalizedSlotIndex >= CODEGAME_GRID_SLOT_COUNT) {
    return 'neutral';
  }
  const normalizedDeckId = normalizeOptionalDeckId(deckId);
  if (!normalizedDeckId) {
    return 'neutral';
  }
  let pattern = null;
  for (const [cardId, cardState] of cards.entries()) {
    if (!isCodegameKeyCardState(cardState)) {
      continue;
    }
    if (normalizeOptionalDeckId(getCardDeckId(cardState, cardId)) !== normalizedDeckId) {
      continue;
    }
    const blue = normalizeCodegameKeyIndexList(cardState.codegameKeyBlueIndices, CODEGAME_KEY_BLUE_COUNT);
    const red = normalizeCodegameKeyIndexList(cardState.codegameKeyRedIndices, CODEGAME_KEY_RED_COUNT);
    const assassinValue = Number(cardState.codegameKeyAssassinIndex);
    pattern = {
      blue: new Set(blue),
      red: new Set(red),
      assassin: Number.isInteger(assassinValue)
        ? clamp(assassinValue, 0, CODEGAME_KEY_TOTAL_CELLS - 1)
        : -1
    };
    break;
  }
  if (!pattern) {
    pattern = getCodegameKeyPatternByDeck().get(normalizedDeckId) || null;
  }
  if (!pattern) {
    return 'neutral';
  }
  if (normalizedSlotIndex === pattern.assassin) {
    return 'assassin';
  }
  if (pattern.blue.has(normalizedSlotIndex)) {
    return 'blue';
  }
  if (pattern.red.has(normalizedSlotIndex)) {
    return 'red';
  }
  return 'neutral';
}

function createEmptyCodegameRevealedSlots() {
  return Array.from({ length: CODEGAME_GRID_SLOT_COUNT }, () => false);
}

function normalizeCodegameRevealedSlotsPayload(payload) {
  const revealedSlots = createEmptyCodegameRevealedSlots();
  const applyRevealedSlot = (slotKey, slotValue) => {
    const numericSlotIndex = Number(slotKey);
    if (!Number.isInteger(numericSlotIndex) || numericSlotIndex < 0 || numericSlotIndex >= CODEGAME_GRID_SLOT_COUNT) {
      return;
    }
    revealedSlots[numericSlotIndex] = slotValue === true || slotValue === 1 || slotValue === '1';
  };
  if (Array.isArray(payload)) {
    payload.forEach((slotValue, slotIndex) => {
      applyRevealedSlot(slotIndex, slotValue);
    });
    return revealedSlots;
  }
  if (payload && typeof payload === 'object') {
    for (const [slotKey, slotValue] of Object.entries(payload)) {
      applyRevealedSlot(slotKey, slotValue);
    }
  }
  return revealedSlots;
}

function buildCodegameRevealedSlotsWritePayload(payload) {
  const normalizedRevealedSlots = normalizeCodegameRevealedSlotsPayload(payload);
  const nextPayload = {};
  normalizedRevealedSlots.forEach((revealed, slotIndex) => {
    if (revealed) {
      nextPayload[String(slotIndex)] = true;
    }
  });
  return Object.keys(nextPayload).length > 0 ? nextPayload : null;
}

function buildCodegameRevealedSlotsRenderKey(payload) {
  return normalizeCodegameRevealedSlotsPayload(payload)
    .map((revealed) => (revealed ? '1' : '0'))
    .join('');
}

function isCodegameGridSlotRevealed(deckId, slotIndex) {
  const normalizedDeckId = normalizeOptionalDeckId(deckId);
  const normalizedSlotIndex = Number(slotIndex);
  if (!normalizedDeckId || getDeckKind(normalizedDeckId) !== DECK_KIND_CODEGAME) {
    return false;
  }
  if (!Number.isInteger(normalizedSlotIndex) || normalizedSlotIndex < 0 || normalizedSlotIndex >= CODEGAME_GRID_SLOT_COUNT) {
    return false;
  }
  const deckState = getDeckStateById(normalizedDeckId);
  const revealedSlots = normalizeCodegameRevealedSlotsPayload(deckState?.codegameRevealedSlots);
  return revealedSlots[normalizedSlotIndex] === true;
}

function resolveCodegameGridDeckAndSlot(cardId = '', cardState = null) {
  const normalizedCardId = String(cardId || '').trim();
  const resolvedCardState =
    cardState && typeof cardState === 'object'
      ? cardState
      : cards.get(normalizedCardId);
  if (!isCodegameCardState(resolvedCardState) || isCodegameKeyCardState(resolvedCardState)) {
    return { deckId: '', slotIndex: -1 };
  }
  if (
    resolvedCardState.inDeck ||
    resolvedCardState.inDiscard ||
    resolvedCardState.inAuction ||
    Boolean(getCardHandOwnerId(resolvedCardState))
  ) {
    return { deckId: '', slotIndex: -1 };
  }

  let deckId = normalizeOptionalDeckId(getCardDeckId(resolvedCardState, normalizedCardId) || resolvedCardState?.deckId || '');
  let slotIndex = getCodegameGridSlotIndex(resolvedCardState);
  const hasFinitePosition =
    Number.isFinite(Number(resolvedCardState?.x)) &&
    Number.isFinite(Number(resolvedCardState?.y));
  const shouldResolveFromPosition =
    hasFinitePosition &&
    (
      slotIndex < 0 ||
      !deckId ||
      getDeckKind(deckId) !== DECK_KIND_CODEGAME
    );
  if (shouldResolveFromPosition) {
    const slotTarget = getCodegameGridSlotAtPosition(
      Number(resolvedCardState.x) || 0,
      Number(resolvedCardState.y) || 0,
      deckId
    );
    if (slotTarget && getDeckKind(slotTarget.deckId) === DECK_KIND_CODEGAME) {
      deckId = normalizeOptionalDeckId(slotTarget.deckId || deckId);
      slotIndex = slotTarget.slotIndex;
    }
  }

  if (!deckId || getDeckKind(deckId) !== DECK_KIND_CODEGAME) {
    return { deckId: '', slotIndex: -1 };
  }
  if (!Number.isInteger(slotIndex) || slotIndex < 0 || slotIndex >= CODEGAME_GRID_SLOT_COUNT) {
    return { deckId, slotIndex: -1 };
  }
  return { deckId, slotIndex };
}

function getCodegameSharedMarkTypeForCard(cardState, cardId = '') {
  if (!cardState || typeof cardState !== 'object' || isCodegameKeyCardState(cardState)) {
    return '';
  }
  if (cardState.inDeck || cardState.inDiscard || cardState.inAuction || getCardHandOwnerId(cardState)) {
    return '';
  }
  const resolvedGrid = resolveCodegameGridDeckAndSlot(cardId, cardState);
  const deckId = resolvedGrid.deckId;
  const slotIndex = resolvedGrid.slotIndex;
  if (cardState.codegameTinted === true) {
    if (slotIndex < 0) {
      return normalizeCodegameMarkedType(cardState.codegameRevealColor || '');
    }
    return getCodegameSharedMarkTypeForSlot(deckId, slotIndex);
  }
  const markedType = normalizeCodegameMarkedType(cardState.codegameMarkedType || '');
  if (!markedType) {
    return '';
  }
  return markedType;
}

function getCodegameRevealColorForCard(cardState, cardId = '') {
  if (!cardState || typeof cardState !== 'object' || isCodegameKeyCardState(cardState)) {
    return '';
  }
  const resolvedGrid = resolveCodegameGridDeckAndSlot(cardId, cardState);
  const deckId = resolvedGrid.deckId;
  const slotIndex = resolvedGrid.slotIndex;
  if (slotIndex >= 0) {
    return isCodegameGridSlotRevealed(deckId, slotIndex)
      ? getCodegameSharedMarkTypeForSlot(deckId, slotIndex)
      : '';
  }
  const markedType = normalizeCodegameMarkedType(cardState.codegameMarkedType || '');
  if (markedType) {
    return markedType;
  }
  const explicitColor = normalizeCodegameMarkedType(cardState.codegameRevealColor || '');
  if (explicitColor) {
    return explicitColor;
  }
  return getCodegameSharedMarkTypeForCard(cardState, cardId);
}

function isCodegameGridPlayableCardState(cardState, cardId = '') {
  const normalizedCardId = String(cardId || '').trim();
  if (!normalizedCardId || !isCodegameCardState(cardState) || isCodegameKeyCardState(cardState)) {
    return false;
  }
  if (cardState.inDeck || cardState.inDiscard || cardState.inAuction || Boolean(getCardHandOwnerId(cardState))) {
    return false;
  }
  return resolveCodegameGridDeckAndSlot(normalizedCardId, cardState).slotIndex >= 0;
}

function applyCodegameMarkVisualToCardElement(cardId, markType) {
  const normalizedCardId = String(cardId || '').trim();
  if (!normalizedCardId) {
    return;
  }
  const card = cardElements.get(normalizedCardId);
  if (!(card instanceof HTMLElement)) {
    return;
  }
  const normalizedMarkType = normalizeCodegameMarkedType(markType || '');
  const hasMark = Boolean(normalizedMarkType);
  let codegameMarkFill =
    card._cardCodegameMarkFill instanceof HTMLElement
      ? card._cardCodegameMarkFill
      : card.querySelector('.table-card-codegame-mark-fill');
  if (!(codegameMarkFill instanceof HTMLElement)) {
    codegameMarkFill = document.createElement('div');
    codegameMarkFill.className = 'table-card-codegame-mark-fill';
    codegameMarkFill.setAttribute('aria-hidden', 'true');
    card.appendChild(codegameMarkFill);
    card._cardCodegameMarkFill = codegameMarkFill;
  }
  codegameMarkFill.classList.toggle('is-visible', hasMark);
  codegameMarkFill.setAttribute('aria-hidden', hasMark ? 'false' : 'true');
  codegameMarkFill.classList.toggle('is-blue', normalizedMarkType === 'blue');
  codegameMarkFill.classList.toggle('is-red', normalizedMarkType === 'red');
  codegameMarkFill.classList.toggle('is-assassin', normalizedMarkType === 'assassin');
  codegameMarkFill.classList.toggle('is-neutral', normalizedMarkType === 'neutral');
  card.classList.toggle('is-codegame-marked', hasMark);
  card.classList.toggle('is-codegame-mark-blue', normalizedMarkType === 'blue');
  card.classList.toggle('is-codegame-mark-red', normalizedMarkType === 'red');
  card.classList.toggle('is-codegame-mark-assassin', normalizedMarkType === 'assassin');
  card.classList.toggle('is-codegame-mark-neutral', normalizedMarkType === 'neutral');
}

function runRenderSafely(stepName, renderFn) {
  if (typeof renderFn !== 'function') {
    return;
  }
  try {
    renderFn();
  } catch (error) {
    console.error(`[state-render] ${stepName}`, error);
  }
}

function toggleCodegameGridCardMark(cardId) {
  const normalizedCardId = String(cardId || '').trim();
  if (!normalizedCardId) {
    return false;
  }
  try {
    const cardState = cards.get(normalizedCardId);
    if (!cardState || typeof cardState !== 'object' || isCodegameKeyCardState(cardState)) {
      if (CODEGAME_TINT_DEBUG) {
        codegameDebugStatusByCardId.set(normalizedCardId, 'reject:not-playable');
      }
      return false;
    }
    if (cardState.inDeck || cardState.inDiscard || cardState.inAuction || getCardHandOwnerId(cardState)) {
      if (CODEGAME_TINT_DEBUG) {
        codegameDebugStatusByCardId.set(normalizedCardId, 'reject:not-on-grid');
      }
      return false;
    }

    const resolvedGrid = resolveCodegameGridDeckAndSlot(normalizedCardId, cardState);
    const targetDeckId = resolvedGrid.deckId;
    const resolvedSlot = resolvedGrid.slotIndex;
    if (
      !targetDeckId ||
      getDeckKind(targetDeckId) !== DECK_KIND_CODEGAME ||
      !Number.isInteger(resolvedSlot) ||
      resolvedSlot < 0 ||
      resolvedSlot >= CODEGAME_GRID_SLOT_COUNT
    ) {
      if (CODEGAME_TINT_DEBUG) {
        codegameDebugStatusByCardId.set(normalizedCardId, 'reject:no-slot');
      }
      return false;
    }

    const isCurrentlyMarked = isCodegameGridSlotRevealed(targetDeckId, resolvedSlot);
    const nextMarkedType = isCurrentlyMarked
      ? ''
      : (getCodegameSharedMarkTypeForSlot(targetDeckId, resolvedSlot) || 'neutral');
    const nextRevealedSlots = normalizeCodegameRevealedSlotsPayload(
      getDeckStateById(targetDeckId)?.codegameRevealedSlots
    );
    nextRevealedSlots[resolvedSlot] = !isCurrentlyMarked;
    const nextRevealedSlotsWritePayload = buildCodegameRevealedSlotsWritePayload(nextRevealedSlots);
    if (!publishCodegameRevealedSlotsPatch(targetDeckId, nextRevealedSlots, nextRevealedSlotsWritePayload)) {
      return false;
    }
    if (CODEGAME_TINT_DEBUG) {
      codegameDebugStatusByCardId.set(
        normalizedCardId,
        `ok:${nextMarkedType || 'off'} slot:${resolvedSlot} deck:${targetDeckId || '-'} shared:deck`
      );
    }
    return true;
  } catch (error) {
    if (CODEGAME_TINT_DEBUG) {
      const message = String(error?.message || error || 'unknown').slice(0, 64);
      codegameDebugStatusByCardId.set(normalizedCardId, `error:${message}`);
    }
    return false;
  }
}

function toggleCodegameGridCardReveal(cardId) {
  const normalizedCardId = String(cardId || '').trim();
  if (!normalizedCardId) {
    return false;
  }
  const now = Date.now();
  const lastToggledAt = Number(codegameRevealToggleAtByCardId.get(normalizedCardId)) || 0;
  if (now - lastToggledAt < 80) {
    if (CODEGAME_TINT_DEBUG) {
      codegameDebugStatusByCardId.set(normalizedCardId, 'reject:debounced');
    }
    return false;
  }
  const toggled = toggleCodegameGridCardMark(normalizedCardId);
  if (toggled) {
    codegameRevealToggleAtByCardId.set(normalizedCardId, now);
  } else if (CODEGAME_TINT_DEBUG && !codegameDebugStatusByCardId.has(normalizedCardId)) {
    codegameDebugStatusByCardId.set(normalizedCardId, 'reject:toggle-false');
  }
  return toggled;
}

function getCodegameKeyHighlightTypeForCard(cardState) {
  if (!isCodegameCardState(cardState) || isCodegameKeyCardState(cardState)) {
    return '';
  }
  if (cardState.inDeck || cardState.inDiscard || cardState.inAuction || getCardHandOwnerId(cardState)) {
    return '';
  }
  const slotIndex = getCodegameGridSlotIndex(cardState);
  if (slotIndex < 0) {
    return '';
  }
  const deckId = getCardDeckId(cardState);
  const highlights = getLocalCodegameKeyHighlightsByDeck().get(deckId);
  if (!highlights) {
    return '';
  }
  if (slotIndex === highlights.assassin) {
    return 'assassin';
  }
  if (highlights.blue.has(slotIndex)) {
    return 'blue';
  }
  if (highlights.red.has(slotIndex)) {
    return 'red';
  }
  return '';
}

function getMovableAnchoredCodegameKeyCards(deckId = activeDeckId) {
  const targetDeckId = normalizeDeckId(deckId);
  if (getDeckKind(targetDeckId) !== DECK_KIND_CODEGAME) {
    return [];
  }
  const targetDeckState = getDeckStateById(targetDeckId);
  if (!targetDeckState || targetDeckState.codegameGridActive !== true) {
    return [];
  }
  const movableCards = [];
  const keyCardIds = getCodegameKeyCardIds(targetDeckId);
  for (let index = 0; index < keyCardIds.length; index += 1) {
    const keyCardId = keyCardIds[index];
    const cardState = cards.get(keyCardId);
    if (!isCodegameKeyCardState(cardState)) {
      continue;
    }
    if (cardState.holderClientId || getCardHandOwnerId(cardState)) {
      continue;
    }
    if (cardState.inDeck || cardState.inDiscard || cardState.inAuction) {
      continue;
    }
    const expectedPosition = getCodegameKeyCardWorldPosition(targetDeckId, index);
    const cardX = Number(cardState.x);
    const cardY = Number(cardState.y);
    const distanceToExpected = Number.isFinite(cardX) && Number.isFinite(cardY)
      ? Math.hypot(cardX - expectedPosition.x, cardY - expectedPosition.y)
      : Number.POSITIVE_INFINITY;
    const hasBeenMoved = cardState.codegameKeyMoved === true;
    const shouldFollow =
      !hasBeenMoved &&
      (cardState.codegameKeyAnchored === true || distanceToExpected <= 2);
    if (!shouldFollow) {
      continue;
    }
    movableCards.push({
      cardId: keyCardId,
      index
    });
  }
  return movableCards;
}

function syncAnchoredCodegameKeyCardsToDeck(deckId = activeDeckId, options = {}) {
  const targetDeckId = normalizeDeckId(deckId);
  const queue = options?.queue !== false;
  const persist = options?.persist === true;
  const movedCardIds = [];
  const movableCards = getMovableAnchoredCodegameKeyCards(targetDeckId);
  for (const entry of movableCards) {
    const cardId = entry.cardId;
    const nextPosition = getCodegameKeyCardWorldPosition(targetDeckId, entry.index);
    const currentCardState = cards.get(cardId);
    const patch = {
      x: nextPosition.x,
      y: nextPosition.y,
      codegameKeyAnchored: true,
      codegameKeyMoved: false,
      drawLifted: currentCardState?.drawLifted === true
    };
    patchLocalCard(cardId, patch);
    if (queue) {
      queueCardPatch(cardId, patch);
    }
    if (persist) {
      persistCardStateImmediately(cardId);
    }
    movedCardIds.push(cardId);
  }
  return movedCardIds;
}

function markCodegameKeyCardAsTouched(cardId) {
  const normalizedCardId = String(cardId || '').trim();
  if (!normalizedCardId) {
    return;
  }
  const cardState = cards.get(normalizedCardId);
  if (!isCodegameKeyCardState(cardState) || cardState.codegameKeyAnchored !== true) {
    return;
  }
  const patch = {
    codegameKeyAnchored: false,
    codegameKeyMoved: true,
    codegameGridSlot: -1
  };
  patchLocalCard(normalizedCardId, patch);
  queueCardPatch(normalizedCardId, patch);
}

function isCodegameCardState(cardState) {
  if (!cardState || typeof cardState !== 'object') {
    return false;
  }
  return getCardFamily(cardState) === CARD_FAMILY_CODEGAME;
}

function isHexitamaActionCardState(cardState, cardId = '') {
  if (!cardState || typeof cardState !== 'object') {
    return false;
  }
  if (cardState.hexitamaCard === true) {
    return true;
  }
  const normalizedCardId = String(cardId || '').trim();
  if (!normalizedCardId) {
    return false;
  }
  return Boolean(getHexitamaCardGameIdFromCardId(normalizedCardId));
}

function getCodegameGridSlotIndex(cardState) {
  const rawSlotValue = cardState?.codegameGridSlot;
  if (rawSlotValue === null || typeof rawSlotValue === 'undefined' || rawSlotValue === '') {
    return -1;
  }
  const rawSlotIndex = Number(rawSlotValue);
  if (!Number.isInteger(rawSlotIndex)) {
    return -1;
  }
  if (rawSlotIndex < 0 || rawSlotIndex >= CODEGAME_GRID_SLOT_COUNT) {
    return -1;
  }
  return rawSlotIndex;
}

function getCodegameEffectiveGridSlotIndex(cardId = '', cardState = null) {
  const resolvedCardState =
    cardState && typeof cardState === 'object'
      ? cardState
      : cards.get(String(cardId || '').trim());
  const normalizedCardId = String(cardId || '').trim();
  if (!isCodegameCardState(resolvedCardState) || isCodegameKeyCardState(resolvedCardState)) {
    return -1;
  }
  const resolvedGrid = resolveCodegameGridDeckAndSlot(normalizedCardId, resolvedCardState);
  if (resolvedGrid.slotIndex < 0 || !resolvedGrid.deckId) {
    return -1;
  }
  if (normalizedCardId) {
    const occupyingCardId = getCodegameCardIdForSlot(resolvedGrid.deckId, resolvedGrid.slotIndex, normalizedCardId);
    if (occupyingCardId && occupyingCardId !== normalizedCardId) {
      return -1;
    }
  }
  return resolvedGrid.slotIndex;
}

function getCodegameCardSlotWorldCenter(cardId = '', cardState = null, options = {}) {
  const normalizedCardId = String(cardId || '').trim();
  const resolvedCardState = cardState && typeof cardState === 'object'
    ? cardState
    : cards.get(normalizedCardId);
  if (!isCodegameCardState(resolvedCardState)) {
    return null;
  }
  if (isCodegameKeyCardState(resolvedCardState)) {
    return null;
  }
  if (resolvedCardState.inDeck || resolvedCardState.inDiscard || resolvedCardState.inAuction || getCardHandOwnerId(resolvedCardState)) {
    return null;
  }
  const slotIndex = getCodegameGridSlotIndex(resolvedCardState);
  if (slotIndex < 0) {
    return null;
  }
  const targetDeckId = getCardDeckId(resolvedCardState, normalizedCardId);
  const targetDeckState = getDeckStateById(targetDeckId);
  if (!targetDeckState) {
    return null;
  }
  const requireActiveGrid = options.requireActiveGrid !== false;
  if (requireActiveGrid && targetDeckState.codegameGridActive !== true) {
    return null;
  }
  return getCodegameGridSlotWorldPosition(targetDeckId, slotIndex);
}

function getCodegameCardIdForSlot(deckId = activeDeckId, slotIndex = -1, excludedCardId = '') {
  const normalizedDeckId = normalizeDeckId(deckId);
  const normalizedExcludedCardId = String(excludedCardId || '').trim();
  const normalizedSlotIndex = Math.max(0, Math.floor(Number(slotIndex) || 0));
  let matchedCardId = '';
  let topZ = Number.NEGATIVE_INFINITY;
  for (const [cardId, cardState] of cards.entries()) {
    if (!isCodegameCardState(cardState)) {
      continue;
    }
    if (getCardDeckId(cardState, cardId) !== normalizedDeckId) {
      continue;
    }
    if (normalizedExcludedCardId && cardId === normalizedExcludedCardId) {
      continue;
    }
    if (cardState.inDeck || cardState.inDiscard || cardState.inAuction || getCardHandOwnerId(cardState)) {
      continue;
    }
    if (getCodegameGridSlotIndex(cardState) !== normalizedSlotIndex) {
      continue;
    }
    const z = Number(cardState.z) || 0;
    if (!matchedCardId || z >= topZ) {
      matchedCardId = cardId;
      topZ = z;
    }
  }
  return matchedCardId;
}

function buildCodegameGridSlotOccupancyByDeck() {
  const occupancyByDeck = new Map();
  for (const [cardId, cardState] of cards.entries()) {
    if (!isCodegameCardState(cardState) || isCodegameKeyCardState(cardState)) {
      continue;
    }
    const normalizedDeckId = getCardDeckId(cardState, cardId);
    if (!normalizedDeckId) {
      continue;
    }
    if (cardState.inDeck || cardState.inDiscard || cardState.inAuction || getCardHandOwnerId(cardState)) {
      continue;
    }
    const slotIndex = getCodegameGridSlotIndex(cardState);
    if (slotIndex < 0 || slotIndex >= CODEGAME_GRID_SLOT_COUNT) {
      continue;
    }
    let deckOccupancy = occupancyByDeck.get(normalizedDeckId);
    if (!deckOccupancy) {
      deckOccupancy = Array.from({ length: CODEGAME_GRID_SLOT_COUNT }, () => ({ cardId: '', z: Number.NEGATIVE_INFINITY }));
      occupancyByDeck.set(normalizedDeckId, deckOccupancy);
    }
    const z = Number(cardState.z) || 0;
    const existing = deckOccupancy[slotIndex];
    if (!existing || !existing.cardId || z >= existing.z) {
      deckOccupancy[slotIndex] = { cardId, z };
    }
  }
  return occupancyByDeck;
}

function getCodegameCardIdForSlotFromOccupancy(occupancyByDeck, deckId = activeDeckId, slotIndex = -1) {
  if (!(occupancyByDeck instanceof Map)) {
    return '';
  }
  const normalizedDeckId = normalizeDeckId(deckId);
  if (!normalizedDeckId) {
    return '';
  }
  const normalizedSlotIndex = Math.max(0, Math.floor(Number(slotIndex) || 0));
  if (normalizedSlotIndex >= CODEGAME_GRID_SLOT_COUNT) {
    return '';
  }
  const deckOccupancy = occupancyByDeck.get(normalizedDeckId);
  if (!Array.isArray(deckOccupancy)) {
    return '';
  }
  const entry = deckOccupancy[normalizedSlotIndex];
  return String(entry?.cardId || '').trim();
}

function getCodegameGridSlotAtPosition(x, y, preferredDeckId = '') {
  const targetX = Number(x);
  const targetY = Number(y);
  if (!Number.isFinite(targetX) || !Number.isFinite(targetY)) {
    return null;
  }
  const normalizedPreferredDeckId = normalizeDeckId(preferredDeckId);
  const candidateDeckIds = normalizedPreferredDeckId
    ? [normalizedPreferredDeckId, ...getDeckIdsInRoom().filter((deckId) => normalizeDeckId(deckId) !== normalizedPreferredDeckId)]
    : getDeckIdsInRoom();
  let bestMatch = null;
  let bestDistance = Number.POSITIVE_INFINITY;
  for (const candidateDeckId of candidateDeckIds) {
    const normalizedDeckId = normalizeDeckId(candidateDeckId);
    if (getDeckKind(normalizedDeckId) !== DECK_KIND_CODEGAME) {
      continue;
    }
    const candidateDeckState = getDeckStateById(normalizedDeckId);
    if (!candidateDeckState || candidateDeckState.codegameGridActive !== true) {
      continue;
    }
    const gridCenter = getCodegameGridCenterPosition(normalizedDeckId);
    const gridDimensions = getCodegameGridWorldDimensions();
    if (isWorldPointHiddenBySecretAreaForLocalViewer(gridCenter.x, gridCenter.y)) {
      continue;
    }
    const insideGridBounds =
      Math.abs(targetX - gridCenter.x) <= gridDimensions.width / 2 &&
      Math.abs(targetY - gridCenter.y) <= gridDimensions.height / 2;
    if (!insideGridBounds) {
      continue;
    }
    for (let slotIndex = 0; slotIndex < CODEGAME_GRID_SLOT_COUNT; slotIndex += 1) {
      const slotWorld = getCodegameGridSlotWorldPosition(normalizedDeckId, slotIndex);
      const insideSlotBounds =
        Math.abs(targetX - slotWorld.x) <= CODEGAME_CARD_SIZE / 2 &&
        Math.abs(targetY - slotWorld.y) <= CODEGAME_CARD_SIZE / 2;
      if (!insideSlotBounds) {
        continue;
      }
      const distance = Math.hypot(targetX - slotWorld.x, targetY - slotWorld.y);
      if (distance < bestDistance) {
        bestDistance = distance;
        bestMatch = {
          deckId: normalizedDeckId,
          slotIndex,
          center: slotWorld
        };
      }
    }
  }
  return bestMatch;
}

function getHexitamaActionCardSlotAtPosition(x, y, preferredGameId = '', excludedCardId = '') {
  const targetX = Number(x);
  const targetY = Number(y);
  if (!Number.isFinite(targetX) || !Number.isFinite(targetY)) {
    return null;
  }
  const normalizedPreferredGameId = normalizeHexitamaGameId(preferredGameId);
  const allGameIds = Array.from(hexitamaGameStatesById.keys()).map((gameId) => normalizeHexitamaGameId(gameId));
  const candidateGameIds = normalizedPreferredGameId
    ? [normalizedPreferredGameId, ...allGameIds.filter((gameId) => gameId !== normalizedPreferredGameId)]
    : allGameIds;
  let bestMatch = null;
  let bestDistance = Number.POSITIVE_INFINITY;
  for (const gameId of candidateGameIds) {
    const gameState = getHexitamaGameStateById(gameId);
    if (!gameState || gameState.enabled === false) {
      continue;
    }
    const slotLayout = getHexitamaActionCardSlotLayout();
    for (const slot of slotLayout) {
      if (!slot || !slot.slotKey) {
        continue;
      }
      const slotCenter = getHexitamaCardWorldPositionFromCanvas(gameState, slot.x, slot.y);
      if (isWorldPointHiddenBySecretAreaForLocalViewer(slotCenter.x, slotCenter.y)) {
        continue;
      }
      const insideSlotBounds =
        Math.abs(targetX - slotCenter.x) <= HEXITAMA_CARD_SIZE / 2 &&
        Math.abs(targetY - slotCenter.y) <= HEXITAMA_CARD_SIZE / 2;
      if (!insideSlotBounds) {
        continue;
      }
      const occupiedCardId = getHexitamaActionCardIdForSlot(gameId, slot.slotKey, excludedCardId);
      if (occupiedCardId) {
        continue;
      }
      const distance = Math.hypot(targetX - slotCenter.x, targetY - slotCenter.y);
      if (distance < bestDistance) {
        bestDistance = distance;
        bestMatch = {
          gameId,
          slotKey: slot.slotKey,
          center: slotCenter
        };
      }
    }
  }
  return bestMatch;
}

function normalizeDieType(type) {
  if (type === 'arcade') {
    return 'arcade';
  }
  if (type === 'label') {
    return 'label';
  }
  if (type === 'media') {
    return 'media';
  }
  if (type === 'counter') {
    return 'counter';
  }
  if (type === 'timer') {
    return 'timer';
  }
  if (type === 'marble') {
    return 'marble';
  }
  if (type === 'stack-point' || type === 'stackpoint' || type === 'stack_point') {
    return 'stack-point';
  }
  if (type === 'spinner') {
    return 'spinner';
  }
  if (type === 'coin') {
    return 'coin';
  }
  if (type === 'chip') {
    return 'chip';
  }
  return type === 'd20' ? 'd20' : 'd6';
}

function isLabelDieState(dieState) {
  return normalizeDieType(dieState?.type) === 'label';
}

function isStackPointDieState(dieState) {
  return normalizeDieType(dieState?.type) === 'stack-point';
}

function isArcadeDieState(dieState) {
  return normalizeDieType(dieState?.type) === 'arcade';
}

function normalizeArcadeStickAxis(value) {
  const numeric = Math.round(Number(value) || 0);
  if (!Number.isFinite(numeric)) {
    return 0;
  }
  return clamp(numeric, ARCADE_STICK_MIN_AXIS, ARCADE_STICK_MAX_AXIS);
}

function normalizeArcadeScreen(value) {
  if (
    value === ARCADE_SCREEN_INFO ||
    value === ARCADE_SCREEN_MANA_MENU ||
    value === ARCADE_SCREEN_MANA_SCORES ||
    value === ARCADE_SCREEN_MANA_PLAY
  ) {
    return value;
  }
  return ARCADE_SCREEN_MAIN;
}

function normalizeArcadeManaMenuIndex(value) {
  const numeric = Math.round(Number(value) || 0);
  if (!Number.isFinite(numeric)) {
    return 0;
  }
  return clamp(numeric, 0, Math.max(0, ARCADE_MANA_MENU_OPTION_LABELS.length - 1));
}

function normalizeArcadeGridCoord(value) {
  const raw = Number(value);
  if (!Number.isFinite(raw)) {
    return ARCADE_MANA_CENTER_TILE;
  }
  const numeric = Math.round(raw);
  return clamp(numeric, 0, ARCADE_MANA_GRID_SIZE - 1);
}

function normalizeArcadeDirectionVector(rawX, rawY) {
  const x = normalizeArcadeStickAxis(rawX);
  const y = normalizeArcadeStickAxis(rawY);
  if (x !== 0 && y !== 0) {
    return { x, y: 0 };
  }
  return { x, y };
}

function isArcadeDirectionInputKey(actionKey) {
  return actionKey === 'w' || actionKey === 'a' || actionKey === 's' || actionKey === 'd';
}

function getArcadeDirectionVectorFromKey(actionKey) {
  if (actionKey === 'w') {
    return { x: 0, y: -1 };
  }
  if (actionKey === 'a') {
    return { x: -1, y: 0 };
  }
  if (actionKey === 's') {
    return { x: 0, y: 1 };
  }
  if (actionKey === 'd') {
    return { x: 1, y: 0 };
  }
  return { x: 0, y: 0 };
}

function getArcadeDirectionQueueTokenFromVector(direction) {
  const normalizedDirection = normalizeArcadeDirectionVector(direction?.x, direction?.y);
  if (normalizedDirection.x === 0 && normalizedDirection.y === -1) {
    return 'U';
  }
  if (normalizedDirection.x === 1 && normalizedDirection.y === 0) {
    return 'R';
  }
  if (normalizedDirection.x === 0 && normalizedDirection.y === 1) {
    return 'D';
  }
  if (normalizedDirection.x === -1 && normalizedDirection.y === 0) {
    return 'L';
  }
  return '';
}

function getArcadeDirectionVectorFromQueueToken(token) {
  const normalizedToken = String(token || '').trim().toUpperCase();
  if (normalizedToken === 'U') {
    return { x: 0, y: -1 };
  }
  if (normalizedToken === 'R') {
    return { x: 1, y: 0 };
  }
  if (normalizedToken === 'D') {
    return { x: 0, y: 1 };
  }
  if (normalizedToken === 'L') {
    return { x: -1, y: 0 };
  }
  return { x: 0, y: 0 };
}

function parseArcadeInputQueuePath(value) {
  const raw = String(value || '').trim();
  if (!raw) {
    return [];
  }
  const entries = raw.split(';');
  const parsed = [];
  for (const entry of entries) {
    const token = String(entry || '').trim().toUpperCase();
    if (token !== 'U' && token !== 'R' && token !== 'D' && token !== 'L') {
      continue;
    }
    parsed.push(token);
    if (parsed.length >= ARCADE_MANA_INPUT_QUEUE_MAX) {
      break;
    }
  }
  return parsed;
}

function encodeArcadeInputQueuePath(tokens) {
  if (!Array.isArray(tokens) || tokens.length === 0) {
    return '';
  }
  const normalizedTokens = [];
  for (const token of tokens) {
    const normalizedToken = String(token || '').trim().toUpperCase();
    if (normalizedToken !== 'U' && normalizedToken !== 'R' && normalizedToken !== 'D' && normalizedToken !== 'L') {
      continue;
    }
    normalizedTokens.push(normalizedToken);
    if (normalizedTokens.length >= ARCADE_MANA_INPUT_QUEUE_MAX) {
      break;
    }
  }
  return normalizedTokens.join(';');
}

function normalizeArcadeInputQueuePath(value) {
  return encodeArcadeInputQueuePath(parseArcadeInputQueuePath(value));
}

function canArcadeMoveToTile(tileX, tileY) {
  return (
    tileX >= 0 &&
    tileX < ARCADE_MANA_GRID_SIZE &&
    tileY >= 0 &&
    tileY < ARCADE_MANA_GRID_SIZE
  );
}

function normalizeArcadeTimestamp(value) {
  const numeric = Math.floor(Number(value) || 0);
  if (!Number.isFinite(numeric)) {
    return 0;
  }
  return Math.max(0, numeric);
}

function normalizeArcadeManaType(value) {
  if (
    value === ARCADE_MANA_TYPE_SUPER ||
    value === 's' ||
    value === 'super' ||
    value === 'supermana'
  ) {
    return ARCADE_MANA_TYPE_SUPER;
  }
  if (value === ARCADE_MANA_TYPE_BLACK || value === 'b' || value === 'black') {
    return ARCADE_MANA_TYPE_BLACK;
  }
  return ARCADE_MANA_TYPE_WHITE;
}

function parseArcadeManaTailPath(value) {
  const raw = String(value || '').trim();
  if (!raw) {
    return [];
  }
  const entries = raw.split(';');
  const parsed = [];
  for (const entry of entries) {
    const parts = entry.split(',');
    if (parts.length < 2) {
      continue;
    }
    const x = normalizeArcadeGridCoord(parts[0]);
    const y = normalizeArcadeGridCoord(parts[1]);
    const type = normalizeArcadeManaType(parts[2]);
    parsed.push({ x, y, type });
    if (parsed.length >= ARCADE_MANA_TAIL_MAX_LENGTH) {
      break;
    }
  }
  return parsed;
}

function encodeArcadeManaTailPath(segments) {
  if (!Array.isArray(segments) || segments.length === 0) {
    return '';
  }
  const encodedParts = [];
  for (let index = 0; index < segments.length; index += 1) {
    const segment = segments[index];
    const x = normalizeArcadeGridCoord(segment?.x);
    const y = normalizeArcadeGridCoord(segment?.y);
    const normalizedType = normalizeArcadeManaType(segment?.type);
    const type = normalizedType === ARCADE_MANA_TYPE_BLACK
      ? 'b'
      : normalizedType === ARCADE_MANA_TYPE_SUPER
        ? 's'
        : 'w';
    encodedParts.push(`${x},${y},${type}`);
    if (encodedParts.length >= ARCADE_MANA_TAIL_MAX_LENGTH) {
      break;
    }
  }
  return encodedParts.join(';');
}

function normalizeArcadeManaTailPath(value) {
  return encodeArcadeManaTailPath(parseArcadeManaTailPath(value));
}

function normalizeArcadeDemonState(value) {
  const normalized = String(value || '').trim().toLowerCase();
  if (normalized === 's' || normalized === ARCADE_MANA_DEMON_STATE_SPAWN) {
    return ARCADE_MANA_DEMON_STATE_SPAWN;
  }
  if (normalized === 'a' || normalized === ARCADE_MANA_DEMON_STATE_ARMING) {
    return ARCADE_MANA_DEMON_STATE_ARMING;
  }
  if (normalized === 'w' || normalized === ARCADE_MANA_DEMON_STATE_WINDUP) {
    return ARCADE_MANA_DEMON_STATE_WINDUP;
  }
  if (normalized === 'd' || normalized === ARCADE_MANA_DEMON_STATE_DASH) {
    return ARCADE_MANA_DEMON_STATE_DASH;
  }
  if (normalized === 'k' || normalized === ARCADE_MANA_DEMON_STATE_DYING) {
    return ARCADE_MANA_DEMON_STATE_DYING;
  }
  if (normalized === 'p' || normalized === ARCADE_MANA_DEMON_STATE_SPINNING) {
    return ARCADE_MANA_DEMON_STATE_SPINNING;
  }
  return ARCADE_MANA_DEMON_STATE_IDLE;
}

function getArcadeDemonStateToken(state) {
  const normalizedState = normalizeArcadeDemonState(state);
  if (normalizedState === ARCADE_MANA_DEMON_STATE_SPAWN) {
    return 's';
  }
  if (normalizedState === ARCADE_MANA_DEMON_STATE_ARMING) {
    return 'a';
  }
  if (normalizedState === ARCADE_MANA_DEMON_STATE_WINDUP) {
    return 'w';
  }
  if (normalizedState === ARCADE_MANA_DEMON_STATE_DASH) {
    return 'd';
  }
  if (normalizedState === ARCADE_MANA_DEMON_STATE_DYING) {
    return 'k';
  }
  if (normalizedState === ARCADE_MANA_DEMON_STATE_SPINNING) {
    return 'p';
  }
  return 'i';
}

function parseArcadeDemonPath(value) {
  const raw = String(value || '').trim();
  if (!raw) {
    return [];
  }
  const entries = raw.split(';');
  const parsed = [];
  for (const entry of entries) {
    const parts = entry.split(',');
    if (parts.length < 4) {
      continue;
    }
    const x = normalizeArcadeGridCoord(parts[0]);
    const y = normalizeArcadeGridCoord(parts[1]);
    const state = normalizeArcadeDemonState(parts[2]);
    const stateStartedAt = normalizeArcadeTimestamp(parts[3]);
    const direction = normalizeArcadeDirectionVector(parts[4], parts[5]);
    const dashFromX = Number.isFinite(Number(parts[6])) ? normalizeArcadeGridCoord(parts[6]) : x;
    const dashFromY = Number.isFinite(Number(parts[7])) ? normalizeArcadeGridCoord(parts[7]) : y;
    const dashToX = Number.isFinite(Number(parts[8])) ? normalizeArcadeGridCoord(parts[8]) : x;
    const dashToY = Number.isFinite(Number(parts[9])) ? normalizeArcadeGridCoord(parts[9]) : y;
    const comboReady = String(parts[10] || '').trim() === '0' ? false : true;
    parsed.push({
      x,
      y,
      state,
      stateStartedAt,
      dirX: direction.x,
      dirY: direction.y,
      dashFromX,
      dashFromY,
      dashToX,
      dashToY,
      comboReady
    });
    if (parsed.length >= ARCADE_MANA_DEMON_MAX) {
      break;
    }
  }
  return parsed;
}

function encodeArcadeDemonPath(demons) {
  if (!Array.isArray(demons) || demons.length === 0) {
    return '';
  }
  const encodedParts = [];
  for (let index = 0; index < demons.length; index += 1) {
    const demon = demons[index];
    const x = normalizeArcadeGridCoord(demon?.x);
    const y = normalizeArcadeGridCoord(demon?.y);
    const state = getArcadeDemonStateToken(demon?.state);
    const stateStartedAt = normalizeArcadeTimestamp(demon?.stateStartedAt);
    const direction = normalizeArcadeDirectionVector(demon?.dirX, demon?.dirY);
    const dashFromX = normalizeArcadeGridCoord(
      Number.isFinite(Number(demon?.dashFromX)) ? demon.dashFromX : x
    );
    const dashFromY = normalizeArcadeGridCoord(
      Number.isFinite(Number(demon?.dashFromY)) ? demon.dashFromY : y
    );
    const dashToX = normalizeArcadeGridCoord(
      Number.isFinite(Number(demon?.dashToX)) ? demon.dashToX : x
    );
    const dashToY = normalizeArcadeGridCoord(
      Number.isFinite(Number(demon?.dashToY)) ? demon.dashToY : y
    );
    const comboReadyToken = demon?.comboReady === false ? '0' : '1';
    encodedParts.push(
      `${x},${y},${state},${stateStartedAt},${direction.x},${direction.y},${dashFromX},${dashFromY},${dashToX},${dashToY},${comboReadyToken}`
    );
    if (encodedParts.length >= ARCADE_MANA_DEMON_MAX) {
      break;
    }
  }
  return encodedParts.join(';');
}

function normalizeArcadeDemonPath(value) {
  return encodeArcadeDemonPath(parseArcadeDemonPath(value));
}

function normalizeArcadeManaPickupCount(value) {
  const numeric = Math.round(Number(value) || 0);
  if (!Number.isFinite(numeric)) {
    return 0;
  }
  return Math.max(0, numeric);
}

function normalizeArcadeBombState(value) {
  const normalized = String(value || '').trim().toLowerCase();
  if (normalized === 'g' || normalized === ARCADE_MANA_BOMB_STATE_SPAWN) {
    return ARCADE_MANA_BOMB_STATE_SPAWN;
  }
  if (normalized === 'a' || normalized === ARCADE_MANA_BOMB_STATE_ARMING) {
    return ARCADE_MANA_BOMB_STATE_ARMING;
  }
  if (normalized === 's' || normalized === ARCADE_MANA_BOMB_STATE_SPINNING) {
    return ARCADE_MANA_BOMB_STATE_SPINNING;
  }
  return ARCADE_MANA_BOMB_STATE_IDLE;
}

function getArcadeBombStateToken(state) {
  const normalizedState = normalizeArcadeBombState(state);
  if (normalizedState === ARCADE_MANA_BOMB_STATE_SPAWN) {
    return 'g';
  }
  if (normalizedState === ARCADE_MANA_BOMB_STATE_ARMING) {
    return 'a';
  }
  if (normalizedState === ARCADE_MANA_BOMB_STATE_SPINNING) {
    return 's';
  }
  return 'i';
}

function normalizeArcadeBombKind(value) {
  const normalized = String(value || '').trim().toLowerCase();
  if (normalized === 'p' || normalized === ARCADE_BOMB_KIND_POTION) {
    return ARCADE_BOMB_KIND_POTION;
  }
  return ARCADE_BOMB_KIND_BOMB;
}

function getArcadeBombKindToken(kind) {
  return normalizeArcadeBombKind(kind) === ARCADE_BOMB_KIND_POTION ? 'p' : 'b';
}

function parseArcadeBombPath(value) {
  const raw = String(value || '').trim();
  if (!raw) {
    return [];
  }
  const entries = raw.split(';');
  const parsed = [];
  for (const entry of entries) {
    const parts = entry.split(',');
    if (parts.length < 2) {
      continue;
    }
    const x = normalizeArcadeGridCoord(parts[0]);
    const y = normalizeArcadeGridCoord(parts[1]);
    const state = normalizeArcadeBombState(parts[2]);
    const stateStartedAt = normalizeArcadeTimestamp(parts[3]);
    const kind = normalizeArcadeBombKind(parts[4]);
    parsed.push({
      x,
      y,
      state,
      stateStartedAt,
      kind
    });
    if (parsed.length >= ARCADE_MANA_BOMB_MAX) {
      break;
    }
  }
  return parsed;
}

function encodeArcadeBombPath(bombs) {
  if (!Array.isArray(bombs) || bombs.length === 0) {
    return '';
  }
  const encodedParts = [];
  for (let index = 0; index < bombs.length; index += 1) {
    const bomb = bombs[index];
    const x = normalizeArcadeGridCoord(bomb?.x);
    const y = normalizeArcadeGridCoord(bomb?.y);
    const state = getArcadeBombStateToken(bomb?.state);
    const stateStartedAt = normalizeArcadeTimestamp(bomb?.stateStartedAt);
    const kind = getArcadeBombKindToken(bomb?.kind);
    encodedParts.push(`${x},${y},${state},${stateStartedAt},${kind}`);
    if (encodedParts.length >= ARCADE_MANA_BOMB_MAX) {
      break;
    }
  }
  return encodedParts.join(';');
}

function normalizeArcadeBombPath(value) {
  return encodeArcadeBombPath(parseArcadeBombPath(value));
}

function parseArcadeBombFxPath(value) {
  const raw = String(value || '').trim();
  if (!raw) {
    return [];
  }
  const entries = raw.split(';');
  const parsed = [];
  for (const entry of entries) {
    const parts = entry.split(',');
    if (parts.length < 3) {
      continue;
    }
    const x = normalizeArcadeGridCoord(parts[0]);
    const y = normalizeArcadeGridCoord(parts[1]);
    const startedAt = normalizeArcadeTimestamp(parts[2]);
    const seedRaw = Math.floor(Number(parts[3]) || 0);
    const seed = clamp(seedRaw, 1, 0x7fffffff);
    parsed.push({
      x,
      y,
      startedAt,
      seed
    });
    if (parsed.length >= ARCADE_MANA_BOMB_FX_MAX) {
      break;
    }
  }
  return parsed;
}

function encodeArcadeBombFxPath(effects) {
  if (!Array.isArray(effects) || effects.length === 0) {
    return '';
  }
  const encodedParts = [];
  for (let index = 0; index < effects.length; index += 1) {
    const effect = effects[index];
    const x = normalizeArcadeGridCoord(effect?.x);
    const y = normalizeArcadeGridCoord(effect?.y);
    const startedAt = normalizeArcadeTimestamp(effect?.startedAt);
    const seedRaw = Math.floor(Number(effect?.seed) || 0);
    const seed = clamp(seedRaw, 1, 0x7fffffff);
    encodedParts.push(`${x},${y},${startedAt},${seed}`);
    if (encodedParts.length >= ARCADE_MANA_BOMB_FX_MAX) {
      break;
    }
  }
  return encodedParts.join(';');
}

function normalizeArcadeBombFxPath(value) {
  return encodeArcadeBombFxPath(parseArcadeBombFxPath(value));
}

function parseArcadePickupPulsePath(value) {
  const raw = String(value || '').trim();
  if (!raw) {
    return [];
  }
  const entries = raw.split(';');
  const parsed = [];
  for (const entry of entries) {
    const parts = entry.split(',');
    if (parts.length < 3) {
      continue;
    }
    const x = normalizeArcadeGridCoord(parts[0]);
    const y = normalizeArcadeGridCoord(parts[1]);
    const startedAt = normalizeArcadeTimestamp(parts[2]);
    parsed.push({ x, y, startedAt });
    if (parsed.length >= ARCADE_MANA_PICKUP_PULSE_MAX) {
      break;
    }
  }
  return parsed;
}

function encodeArcadePickupPulsePath(pulses) {
  if (!Array.isArray(pulses) || pulses.length === 0) {
    return '';
  }
  const encodedParts = [];
  for (let index = 0; index < pulses.length; index += 1) {
    const pulse = pulses[index];
    const x = normalizeArcadeGridCoord(pulse?.x);
    const y = normalizeArcadeGridCoord(pulse?.y);
    const startedAt = normalizeArcadeTimestamp(pulse?.startedAt);
    encodedParts.push(`${x},${y},${startedAt}`);
    if (encodedParts.length >= ARCADE_MANA_PICKUP_PULSE_MAX) {
      break;
    }
  }
  return encodedParts.join(';');
}

function normalizeArcadePickupPulsePath(value) {
  return encodeArcadePickupPulsePath(parseArcadePickupPulsePath(value));
}

function isArcadeDemonActiveState(state) {
  const normalizedState = normalizeArcadeDemonState(state);
  return (
    normalizedState === ARCADE_MANA_DEMON_STATE_IDLE ||
    normalizedState === ARCADE_MANA_DEMON_STATE_WINDUP ||
    normalizedState === ARCADE_MANA_DEMON_STATE_DASH
  );
}

function getArcadeSquareBounds(segments) {
  if (!Array.isArray(segments) || segments.length === 0) {
    return null;
  }
  let minX = Infinity;
  let minY = Infinity;
  let maxX = -Infinity;
  let maxY = -Infinity;
  for (const segment of segments) {
    const x = normalizeArcadeGridCoord(segment?.x);
    const y = normalizeArcadeGridCoord(segment?.y);
    minX = Math.min(minX, x);
    minY = Math.min(minY, y);
    maxX = Math.max(maxX, x);
    maxY = Math.max(maxY, y);
  }
  if (!Number.isFinite(minX) || !Number.isFinite(minY) || !Number.isFinite(maxX) || !Number.isFinite(maxY)) {
    return null;
  }
  return { minX, minY, maxX, maxY };
}

function getArcadeDemonDashTiles(demon) {
  if (!demon || typeof demon !== 'object') {
    return [];
  }
  const state = normalizeArcadeDemonState(demon.state);
  const currentX = normalizeArcadeGridCoord(demon.x);
  const currentY = normalizeArcadeGridCoord(demon.y);
  if (state !== ARCADE_MANA_DEMON_STATE_DASH) {
    return [{ x: currentX, y: currentY }];
  }
  const fromX = normalizeArcadeGridCoord(
    Number.isFinite(Number(demon.dashFromX)) ? demon.dashFromX : currentX
  );
  const fromY = normalizeArcadeGridCoord(
    Number.isFinite(Number(demon.dashFromY)) ? demon.dashFromY : currentY
  );
  const toX = normalizeArcadeGridCoord(
    Number.isFinite(Number(demon.dashToX)) ? demon.dashToX : currentX
  );
  const toY = normalizeArcadeGridCoord(
    Number.isFinite(Number(demon.dashToY)) ? demon.dashToY : currentY
  );
  const direction = normalizeArcadeDirectionVector(
    Math.sign(toX - fromX) || demon?.dirX,
    Math.sign(toY - fromY) || demon?.dirY
  );
  if (direction.x === 0 && direction.y === 0) {
    return [{ x: currentX, y: currentY }];
  }
  const tiles = [];
  let cursorX = fromX;
  let cursorY = fromY;
  let safety = 0;
  while (
    (cursorX !== toX || cursorY !== toY) &&
    safety < ARCADE_MANA_GRID_SIZE
  ) {
    cursorX += direction.x;
    cursorY += direction.y;
    if (!canArcadeMoveToTile(cursorX, cursorY)) {
      break;
    }
    tiles.push({ x: cursorX, y: cursorY });
    safety += 1;
  }
  if (tiles.length === 0) {
    tiles.push({ x: currentX, y: currentY });
  }
  return tiles;
}

function getArcadeTileDistanceToBoardEdge(tileX, tileY) {
  const normalizedTileX = normalizeArcadeGridCoord(tileX);
  const normalizedTileY = normalizeArcadeGridCoord(tileY);
  const maxCoord = ARCADE_MANA_GRID_SIZE - 1;
  return Math.min(
    normalizedTileX,
    normalizedTileY,
    maxCoord - normalizedTileX,
    maxCoord - normalizedTileY
  );
}

function getArcadeDemonSpawnTile(excludedTiles = []) {
  const blocked = new Set();
  if (Array.isArray(excludedTiles)) {
    for (const tile of excludedTiles) {
      const x = normalizeArcadeGridCoord(tile?.x);
      const y = normalizeArcadeGridCoord(tile?.y);
      blocked.add(`${x},${y}`);
    }
  }
  const availableTiles = [];
  for (let y = 0; y < ARCADE_MANA_GRID_SIZE; y += 1) {
    for (let x = 0; x < ARCADE_MANA_GRID_SIZE; x += 1) {
      if (getArcadeTileDistanceToBoardEdge(x, y) === 0) {
        continue;
      }
      if (blocked.has(`${x},${y}`)) {
        continue;
      }
      availableTiles.push({ x, y });
    }
  }
  if (availableTiles.length > 0) {
    const randomIndex = getRandomIntInclusive(0, availableTiles.length - 1);
    return availableTiles[randomIndex];
  }
  return null;
}

function isArcadeCornerTile(tileX, tileY) {
  const x = normalizeArcadeGridCoord(tileX);
  const y = normalizeArcadeGridCoord(tileY);
  const maxCoord = ARCADE_MANA_GRID_SIZE - 1;
  return (x === 0 || x === maxCoord) && (y === 0 || y === maxCoord);
}

function getArcadeBombSpawnTile(excludedTiles = []) {
  const blocked = new Set();
  if (Array.isArray(excludedTiles)) {
    for (const tile of excludedTiles) {
      const x = normalizeArcadeGridCoord(tile?.x);
      const y = normalizeArcadeGridCoord(tile?.y);
      blocked.add(`${x},${y}`);
    }
  }
  const maxCoord = ARCADE_MANA_GRID_SIZE - 1;
  blocked.add(`0,0`);
  blocked.add(`${maxCoord},0`);
  blocked.add(`0,${maxCoord}`);
  blocked.add(`${maxCoord},${maxCoord}`);

  const candidates = [];
  for (let y = 0; y < ARCADE_MANA_GRID_SIZE; y += 1) {
    for (let x = 0; x < ARCADE_MANA_GRID_SIZE; x += 1) {
      if (blocked.has(`${x},${y}`)) {
        continue;
      }
      candidates.push({ x, y });
    }
  }
  if (candidates.length === 0) {
    return null;
  }
  const randomIndex = getRandomIntInclusive(0, candidates.length - 1);
  return candidates[randomIndex];
}

function getArcadeDemonAttackDirectionFromTile(
  tileX,
  tileY,
  occupiedTargetTileKeys = null,
  forbiddenManaTargetTileKeys = null
) {
  const originX = normalizeArcadeGridCoord(tileX);
  const originY = normalizeArcadeGridCoord(tileY);
  const originEdgeDistance = getArcadeTileDistanceToBoardEdge(originX, originY);
  const candidates = [];
  let hasAwayFromEdgeOption = false;
  for (const direction of ARCADE_MANA_DEMON_CARDINAL_DIRECTIONS) {
    const nextTileX = originX + direction.x;
    const nextTileY = originY + direction.y;
    if (canArcadeMoveToTile(nextTileX, nextTileY)) {
      const potentialTarget = getArcadeDemonDashTargetTile({
        x: originX,
        y: originY,
        dirX: direction.x,
        dirY: direction.y
      });
      const potentialTargetKey = getArcadeTileKey(potentialTarget.x, potentialTarget.y);
      if (
        occupiedTargetTileKeys instanceof Set &&
        occupiedTargetTileKeys.has(potentialTargetKey)
      ) {
        continue;
      }
      if (
        forbiddenManaTargetTileKeys instanceof Set &&
        forbiddenManaTargetTileKeys.has(potentialTargetKey)
      ) {
        continue;
      }
      const nextEdgeDistance = getArcadeTileDistanceToBoardEdge(nextTileX, nextTileY);
      const movesAwayFromEdge = nextEdgeDistance > originEdgeDistance;
      if (movesAwayFromEdge) {
        hasAwayFromEdgeOption = true;
      }
      candidates.push({
        x: direction.x,
        y: direction.y,
        awayFromEdge: movesAwayFromEdge
      });
    }
  }
  if (candidates.length === 0) {
    return { x: 0, y: 0 };
  }
  if (!hasAwayFromEdgeOption) {
    const randomIndex = getRandomIntInclusive(0, candidates.length - 1);
    return candidates[randomIndex];
  }
  let totalWeight = 0;
  const weightedCandidates = candidates.map((candidate) => {
    const weight = candidate.awayFromEdge
      ? ARCADE_MANA_DEMON_AWAY_FROM_EDGE_WEIGHT
      : ARCADE_MANA_DEMON_TOWARD_EDGE_WEIGHT;
    totalWeight += weight;
    return {
      ...candidate,
      cumulativeWeight: totalWeight
    };
  });
  let selection = Math.random() * totalWeight;
  for (const candidate of weightedCandidates) {
    if (selection <= candidate.cumulativeWeight) {
      return { x: candidate.x, y: candidate.y };
    }
  }
  const lastCandidate = weightedCandidates[weightedCandidates.length - 1];
  return { x: lastCandidate.x, y: lastCandidate.y };
}

function getArcadeDemonDashTargetTile(demon) {
  const originX = normalizeArcadeGridCoord(demon?.x);
  const originY = normalizeArcadeGridCoord(demon?.y);
  const direction = normalizeArcadeDirectionVector(demon?.dirX, demon?.dirY);
  if (direction.x === 0 && direction.y === 0) {
    return { x: originX, y: originY };
  }
  let targetX = originX;
  let targetY = originY;
  for (let step = 0; step < 2; step += 1) {
    const nextX = targetX + direction.x;
    const nextY = targetY + direction.y;
    if (!canArcadeMoveToTile(nextX, nextY)) {
      break;
    }
    targetX = nextX;
    targetY = nextY;
  }
  return { x: targetX, y: targetY };
}

function isArcadeReverseDirection(direction, referenceDirection) {
  const normalizedDirection = normalizeArcadeDirectionVector(direction?.x, direction?.y);
  const normalizedReference = normalizeArcadeDirectionVector(referenceDirection?.x, referenceDirection?.y);
  return (
    (normalizedDirection.x !== 0 || normalizedDirection.y !== 0) &&
    (normalizedReference.x !== 0 || normalizedReference.y !== 0) &&
    normalizedDirection.x === -normalizedReference.x &&
    normalizedDirection.y === -normalizedReference.y
  );
}

function areArcadeDirectionsEqual(directionA, directionB) {
  const normalizedA = normalizeArcadeDirectionVector(directionA?.x, directionA?.y);
  const normalizedB = normalizeArcadeDirectionVector(directionB?.x, directionB?.y);
  return normalizedA.x === normalizedB.x && normalizedA.y === normalizedB.y;
}

function getArcadeEffectiveHeadingForReverseBlock(dieState, baseDirection = null, tailSegments = null) {
  const normalizedBaseDirection = normalizeArcadeDirectionVector(baseDirection?.x, baseDirection?.y);
  if (normalizedBaseDirection.x !== 0 || normalizedBaseDirection.y !== 0) {
    return normalizedBaseDirection;
  }
  const parsedTailSegments = Array.isArray(tailSegments)
    ? tailSegments
    : parseArcadeManaTailPath(dieState?.arcadeMgTailPath);
  if (!Array.isArray(parsedTailSegments) || parsedTailSegments.length === 0) {
    return { x: 0, y: 0 };
  }
  const headTileX = normalizeArcadeGridCoord(dieState?.arcadeMgTileX);
  const headTileY = normalizeArcadeGridCoord(dieState?.arcadeMgTileY);
  const nearestTailSegment = parsedTailSegments[0];
  const deltaX = headTileX - normalizeArcadeGridCoord(nearestTailSegment?.x);
  const deltaY = headTileY - normalizeArcadeGridCoord(nearestTailSegment?.y);
  if (Math.abs(deltaX) + Math.abs(deltaY) !== 1) {
    return { x: 0, y: 0 };
  }
  return normalizeArcadeDirectionVector(deltaX, deltaY);
}

function getArcadeTileKey(x, y) {
  return `${normalizeArcadeGridCoord(x)},${normalizeArcadeGridCoord(y)}`;
}

function isArcadePointOnSquarePerimeter(tileX, tileY, left, top, size) {
  const right = left + size;
  const bottom = top + size;
  if (tileX < left || tileX > right || tileY < top || tileY > bottom) {
    return false;
  }
  return tileX === left || tileX === right || tileY === top || tileY === bottom;
}

function collectArcadeSquarePerimeterKeys(left, top, size) {
  const keys = [];
  const right = left + size;
  const bottom = top + size;
  for (let x = left; x <= right; x += 1) {
    keys.push(getArcadeTileKey(x, top));
    if (bottom !== top) {
      keys.push(getArcadeTileKey(x, bottom));
    }
  }
  for (let y = top + 1; y <= bottom - 1; y += 1) {
    keys.push(getArcadeTileKey(left, y));
    if (right !== left) {
      keys.push(getArcadeTileKey(right, y));
    }
  }
  return Array.from(new Set(keys));
}

function getArcadeSquareTailSegmentsAtIntersection(tileX, tileY, tailSegments) {
  // Require at least a 3x3 square perimeter (8 tiles). 2x2 loops are ignored.
  if (!Array.isArray(tailSegments) || tailSegments.length < 8) {
    return [];
  }
  const byKey = new Map();
  for (const segment of tailSegments) {
    byKey.set(getArcadeTileKey(segment?.x, segment?.y), {
      x: normalizeArcadeGridCoord(segment?.x),
      y: normalizeArcadeGridCoord(segment?.y),
      type: normalizeArcadeManaType(segment?.type)
    });
  }
  if (!byKey.has(getArcadeTileKey(tileX, tileY))) {
    return [];
  }
  for (let size = ARCADE_MANA_GRID_SIZE - 1; size >= 2; size -= 1) {
    for (let top = 0; top + size < ARCADE_MANA_GRID_SIZE; top += 1) {
      for (let left = 0; left + size < ARCADE_MANA_GRID_SIZE; left += 1) {
        if (!isArcadePointOnSquarePerimeter(tileX, tileY, left, top, size)) {
          continue;
        }
        const perimeterKeys = collectArcadeSquarePerimeterKeys(left, top, size);
        let validSquare = true;
        for (const key of perimeterKeys) {
          if (!byKey.has(key)) {
            validSquare = false;
            break;
          }
        }
        if (!validSquare) {
          continue;
        }
        const squareSegments = [];
        for (const key of perimeterKeys) {
          const segment = byKey.get(key);
          if (segment) {
            squareSegments.push({
              x: segment.x,
              y: segment.y,
              type: segment.type
            });
          }
        }
        return squareSegments;
      }
    }
  }
  return [];
}

function normalizeArcadePlayerToken(value) {
  return String(value || '').trim().slice(0, 128);
}

function getArcadeBestScoreForPlayerToken(token) {
  const normalizedToken = normalizeArcadePlayerToken(token);
  if (!normalizedToken) {
    return 0;
  }
  const entry = arcadeBestScoresByPlayerToken.get(normalizedToken);
  return Math.max(0, Math.round(Number(entry?.bestScore) || 0));
}

function getArcadeHighScoreEntries() {
  const entriesByNameKey = new Map();
  for (const [rawToken, rawEntry] of arcadeBestScoresByPlayerToken.entries()) {
    const token = normalizeArcadePlayerToken(rawToken);
    if (!token) {
      continue;
    }
    const bestScore = Math.max(0, Math.round(Number(rawEntry?.bestScore) || 0));
    const name = String(rawEntry?.name || '').trim().slice(0, 24);
    if (bestScore <= 0) {
      continue;
    }
    if (!name) {
      continue;
    }
    const entry = {
      token,
      bestScore,
      name,
      color: normalizeHexColor(rawEntry?.color || '#ff7a59'),
      updatedAt: Math.max(0, Math.floor(Number(rawEntry?.updatedAt) || 0))
    };
    const nameKey = name.toLowerCase();
    if (nameKey === 'anon') {
      const anonSessionKey = `${nameKey}:${token}`;
      const existingAnonSessionEntry = entriesByNameKey.get(anonSessionKey);
      if (!existingAnonSessionEntry) {
        entriesByNameKey.set(anonSessionKey, entry);
        continue;
      }
      if (entry.bestScore > existingAnonSessionEntry.bestScore) {
        entriesByNameKey.set(anonSessionKey, entry);
        continue;
      }
      if (
        entry.bestScore === existingAnonSessionEntry.bestScore &&
        entry.updatedAt > existingAnonSessionEntry.updatedAt
      ) {
        entriesByNameKey.set(anonSessionKey, entry);
      }
      continue;
    }
    const existing = entriesByNameKey.get(nameKey);
    if (!existing) {
      entriesByNameKey.set(nameKey, entry);
      continue;
    }
    if (entry.bestScore > existing.bestScore) {
      entriesByNameKey.set(nameKey, entry);
      continue;
    }
    if (entry.bestScore === existing.bestScore) {
      if (entry.updatedAt > existing.updatedAt) {
        entriesByNameKey.set(nameKey, entry);
        continue;
      }
      if (entry.updatedAt === existing.updatedAt && entry.token.localeCompare(existing.token) < 0) {
        entriesByNameKey.set(nameKey, entry);
      }
    }
  }
  const entries = Array.from(entriesByNameKey.values());
  entries.sort((a, b) => {
    if (b.bestScore !== a.bestScore) {
      return b.bestScore - a.bestScore;
    }
    if (a.updatedAt !== b.updatedAt) {
      return a.updatedAt - b.updatedAt;
    }
    const nameCompare = a.name.localeCompare(b.name);
    if (nameCompare !== 0) {
      return nameCompare;
    }
    return a.token.localeCompare(b.token);
  });
  return entries;
}

function getArcadeHighScoreSignature() {
  const entries = getArcadeHighScoreEntries();
  if (entries.length === 0) {
    return 'none';
  }
  return entries
    .map((entry) => `${entry.token}:${entry.bestScore}:${entry.updatedAt}:${entry.name}:${entry.color}`)
    .join('|');
}

function getRandomArcadeManaType() {
  return getRandomIntInclusive(0, 1) === 0 ? ARCADE_MANA_TYPE_WHITE : ARCADE_MANA_TYPE_BLACK;
}

function getArcadeManaSpawnTile(excludedTiles = []) {
  const blocked = new Set();
  if (Array.isArray(excludedTiles)) {
    for (const tile of excludedTiles) {
      const x = normalizeArcadeGridCoord(tile?.x);
      const y = normalizeArcadeGridCoord(tile?.y);
      blocked.add(`${x},${y}`);
    }
  }
  for (let attempt = 0; attempt < 320; attempt += 1) {
    const x = getRandomIntInclusive(0, ARCADE_MANA_GRID_SIZE - 1);
    const y = getRandomIntInclusive(0, ARCADE_MANA_GRID_SIZE - 1);
    if (Math.abs(x - ARCADE_MANA_CENTER_TILE) + Math.abs(y - ARCADE_MANA_CENTER_TILE) < ARCADE_MANA_MIN_SPAWN_MANHATTAN_DISTANCE) {
      continue;
    }
    if (blocked.has(`${x},${y}`)) {
      continue;
    }
    return { x, y };
  }
  for (let y = 0; y < ARCADE_MANA_GRID_SIZE; y += 1) {
    for (let x = 0; x < ARCADE_MANA_GRID_SIZE; x += 1) {
      if (Math.abs(x - ARCADE_MANA_CENTER_TILE) + Math.abs(y - ARCADE_MANA_CENTER_TILE) < ARCADE_MANA_MIN_SPAWN_MANHATTAN_DISTANCE) {
        continue;
      }
      if (blocked.has(`${x},${y}`)) {
        continue;
      }
      return { x, y };
    }
  }
  return { x: ARCADE_MANA_CENTER_TILE, y: ARCADE_MANA_CENTER_TILE };
}

function getArcadeManaStepMsForState(dieState) {
  const phaseActive = dieState?.arcadeMgPhaseActive === true;
  const scoreValue = Math.max(0, Math.round(Number(dieState?.arcadeMgSquareClearScore) || 0));
  return getArcadeManaStepMsForPhaseAndScore(phaseActive, scoreValue);
}

function getArcadeManaSpeedTierForScore(scoreValue) {
  const normalizedScore = Math.max(0, Math.round(Number(scoreValue) || 0));
  return Math.max(0, Math.floor(normalizedScore / ARCADE_MANA_SPEED_SCORE_INTERVAL));
}

function getArcadeManaStepMsForPhaseAndScore(phaseActive, scoreValue = 0) {
  const isPhase = phaseActive === true;
  const speedTier = getArcadeManaSpeedTierForScore(scoreValue);
  const baseStepMs = isPhase ? ARCADE_MANA_STEP_MS_PHASE : ARCADE_MANA_STEP_MS_NORMAL;
  const minStepMs = isPhase ? ARCADE_MANA_STEP_MS_PHASE_MIN : ARCADE_MANA_STEP_MS_NORMAL_MIN;
  const reducedStepMs = baseStepMs - speedTier * ARCADE_MANA_STEP_MS_SPEEDUP_PER_TIER;
  return Math.max(minStepMs, reducedStepMs);
}

function getArcadeManaPlayerRenderPosition(dieState, now = Date.now()) {
  const tileX = normalizeArcadeGridCoord(dieState?.arcadeMgTileX);
  const tileY = normalizeArcadeGridCoord(dieState?.arcadeMgTileY);
  const moveDirection = normalizeArcadeDirectionVector(dieState?.arcadeMgDirX, dieState?.arcadeMgDirY);
  const moveStartedAt = normalizeArcadeTimestamp(dieState?.arcadeMgMoveStartedAt);
  if ((moveDirection.x === 0 && moveDirection.y === 0) || moveStartedAt <= 0) {
    return {
      x: tileX,
      y: tileY
    };
  }
  const stepDurationMs = Math.max(1, getArcadeManaStepMsForState(dieState));
  const progress = clamp((Math.max(0, Number(now) || 0) - moveStartedAt) / stepDurationMs, 0, 1);
  return {
    x: tileX + moveDirection.x * progress,
    y: tileY + moveDirection.y * progress
  };
}

function getArcadeManaSmoothedRenderPosition(dieId, dieState, now = Date.now()) {
  const normalizedDieId = String(dieId || '').trim();
  if (!normalizedDieId) {
    return getArcadeManaPlayerRenderPosition(dieState, now);
  }
  const tileX = normalizeArcadeGridCoord(dieState?.arcadeMgTileX);
  const tileY = normalizeArcadeGridCoord(dieState?.arcadeMgTileY);
  const moveDirection = normalizeArcadeDirectionVector(dieState?.arcadeMgDirX, dieState?.arcadeMgDirY);
  const stepDurationMs = Math.max(1, getArcadeManaStepMsForState(dieState));
  const hasMotion = moveDirection.x !== 0 || moveDirection.y !== 0;
  const nowMs = Math.max(0, Number(now) || Date.now());
  let visualState = arcadeManaVisualStateByDieId.get(normalizedDieId);
  const stateChanged = !visualState ||
    visualState.tileX !== tileX ||
    visualState.tileY !== tileY ||
    visualState.dirX !== moveDirection.x ||
    visualState.dirY !== moveDirection.y ||
    Math.abs((Number(visualState.stepMs) || 0) - stepDurationMs) > 0.01;
  if (!visualState) {
    visualState = {
      tileX,
      tileY,
      dirX: moveDirection.x,
      dirY: moveDirection.y,
      stepMs: stepDurationMs,
      segmentStartedAt: nowMs,
      renderX: tileX,
      renderY: tileY,
      lastRenderAt: nowMs
    };
    arcadeManaVisualStateByDieId.set(normalizedDieId, visualState);
  } else if (stateChanged) {
    visualState.tileX = tileX;
    visualState.tileY = tileY;
    visualState.dirX = moveDirection.x;
    visualState.dirY = moveDirection.y;
    visualState.stepMs = stepDurationMs;
    visualState.segmentStartedAt = nowMs;
  }
  const segmentProgress = hasMotion
    ? clamp((nowMs - visualState.segmentStartedAt) / stepDurationMs, 0, 1)
    : 0;
  const targetX = tileX + moveDirection.x * segmentProgress;
  const targetY = tileY + moveDirection.y * segmentProgress;
  const lastRenderAt = Math.max(0, Number(visualState.lastRenderAt) || nowMs);
  const deltaSeconds = clamp((nowMs - lastRenderAt) / 1000, 0, 0.1);
  const blend = clamp(
    1 - Math.exp(-ARCADE_MANA_VISUAL_SMOOTHNESS_PER_SECOND * deltaSeconds),
    0.06,
    1
  );
  const distanceToTarget = Math.hypot(targetX - visualState.renderX, targetY - visualState.renderY);
  if (!Number.isFinite(distanceToTarget) || distanceToTarget > ARCADE_MANA_VISUAL_SNAP_DISTANCE_TILES) {
    visualState.renderX = targetX;
    visualState.renderY = targetY;
  } else {
    visualState.renderX += (targetX - visualState.renderX) * blend;
    visualState.renderY += (targetY - visualState.renderY) * blend;
  }
  visualState.lastRenderAt = nowMs;
  return {
    x: visualState.renderX,
    y: visualState.renderY
  };
}

function updateArcadeManaScorePopups(dieId, dieState, now = Date.now()) {
  const normalizedDieId = String(dieId || '').trim();
  if (!normalizedDieId) {
    return [];
  }
  const nowMs = Math.max(0, Number(now) || Date.now());
  const currentScore = Math.max(0, Math.round(Number(dieState?.arcadeMgSquareClearScore) || 0));
  let visualState = arcadeManaVisualStateByDieId.get(normalizedDieId);
  if (!visualState) {
    visualState = {
      tileX: normalizeArcadeGridCoord(dieState?.arcadeMgTileX),
      tileY: normalizeArcadeGridCoord(dieState?.arcadeMgTileY),
      dirX: normalizeArcadeDirectionVector(dieState?.arcadeMgDirX, dieState?.arcadeMgDirY).x,
      dirY: normalizeArcadeDirectionVector(dieState?.arcadeMgDirX, dieState?.arcadeMgDirY).y,
      stepMs: getArcadeManaStepMsForState(dieState),
      segmentStartedAt: nowMs,
      renderX: normalizeArcadeGridCoord(dieState?.arcadeMgTileX),
      renderY: normalizeArcadeGridCoord(dieState?.arcadeMgTileY),
      lastRenderAt: nowMs
    };
    arcadeManaVisualStateByDieId.set(normalizedDieId, visualState);
  }
  if (!Array.isArray(visualState.scorePopups)) {
    visualState.scorePopups = [];
  }
  if (!Number.isFinite(Number(visualState.lastScoreValue))) {
    visualState.lastScoreValue = currentScore;
  }
  const previousScore = Math.max(0, Math.round(Number(visualState.lastScoreValue) || 0));
  if (currentScore > previousScore) {
    const anchorX = normalizeArcadeGridCoord(dieState?.arcadeMgTileX) + 0.5;
    const anchorY = normalizeArcadeGridCoord(dieState?.arcadeMgTileY) + 0.5;
    visualState.scorePopups.push({
      value: currentScore - previousScore,
      startedAt: nowMs,
      anchorX,
      anchorY
    });
    if (visualState.scorePopups.length > ARCADE_MANA_SCORE_POPUP_MAX) {
      visualState.scorePopups = visualState.scorePopups.slice(-ARCADE_MANA_SCORE_POPUP_MAX);
    }
  }
  visualState.lastScoreValue = currentScore;
  visualState.scorePopups = visualState.scorePopups.filter((popup) => {
    const startedAt = Math.max(0, Number(popup?.startedAt) || 0);
    return nowMs - startedAt <= ARCADE_MANA_SCORE_POPUP_DURATION_MS;
  });
  return visualState.scorePopups;
}

function getArcadeSpriteImage(src) {
  const normalizedSrc = String(src || '').trim();
  if (!normalizedSrc) {
    return null;
  }
  let image = arcadeSpriteImageBySrc.get(normalizedSrc);
  if (image instanceof HTMLImageElement) {
    return image;
  }
  image = new Image();
  image.decoding = 'async';
  image.loading = 'eager';
  image.src = normalizedSrc;
  arcadeSpriteImageBySrc.set(normalizedSrc, image);
  return image;
}

function getArcadeScaledSpriteCanvas(src, width, height) {
  const normalizedSrc = String(src || '').trim();
  const scaledWidth = Math.max(1, Math.round(Number(width) || 0));
  const scaledHeight = Math.max(1, Math.round(Number(height) || 0));
  if (!normalizedSrc || !scaledWidth || !scaledHeight) {
    return null;
  }
  const cacheKey = `${normalizedSrc}|${scaledWidth}x${scaledHeight}`;
  const cached = arcadeManaScaledSpriteByKey.get(cacheKey);
  if (cached instanceof HTMLCanvasElement) {
    return cached;
  }
  const image = getArcadeSpriteImage(normalizedSrc);
  if (!(image instanceof HTMLImageElement) || !image.complete || image.naturalWidth <= 0 || image.naturalHeight <= 0) {
    return null;
  }
  const canvas = document.createElement('canvas');
  canvas.width = scaledWidth;
  canvas.height = scaledHeight;
  const ctx = canvas.getContext('2d');
  if (!(ctx instanceof CanvasRenderingContext2D)) {
    return null;
  }
  ctx.save();
  ctx.imageSmoothingEnabled = true;
  ctx.imageSmoothingQuality = 'high';
  ctx.clearRect(0, 0, scaledWidth, scaledHeight);
  ctx.drawImage(image, 0, 0, scaledWidth, scaledHeight);
  ctx.restore();
  arcadeManaScaledSpriteByKey.set(cacheKey, canvas);
  return canvas;
}

function isLabelDieLocked(dieState) {
  return isLabelDieState(dieState) && dieState?.labelLocked === true;
}

function normalizeSpinnerSegmentCount(value, fallbackValue = SPINNER_DEFAULT_SEGMENTS) {
  const parsed = Math.round(Number(value));
  if (Number.isFinite(parsed)) {
    return clamp(parsed, SPINNER_MIN_SEGMENTS, SPINNER_MAX_SEGMENTS);
  }
  const fallbackParsed = Math.round(Number(fallbackValue));
  if (Number.isFinite(fallbackParsed)) {
    return clamp(fallbackParsed, SPINNER_MIN_SEGMENTS, SPINNER_MAX_SEGMENTS);
  }
  return SPINNER_DEFAULT_SEGMENTS;
}

function normalizeSpinnerLabelText(value) {
  return String(value ?? '')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, SPINNER_LABEL_MAX_LENGTH);
}

function normalizeChipLabelText(value) {
  return String(value ?? '')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, CHIP_LABEL_MAX_LENGTH);
}

function getChipLabelMeasureContext() {
  if (chipLabelMeasureContext instanceof CanvasRenderingContext2D) {
    return chipLabelMeasureContext;
  }
  if (typeof document === 'undefined') {
    return null;
  }
  const canvas = document.createElement('canvas');
  const context = canvas.getContext('2d');
  if (!(context instanceof CanvasRenderingContext2D)) {
    return null;
  }
  chipLabelMeasureContext = context;
  return context;
}

function getChipLabelFittedFontSize(labelText, options = {}) {
  const normalizedLabel = normalizeChipLabelText(labelText) || '1';
  const maxWidth = Math.max(1, Number(options.maxWidth) || 40);
  const minFontSize = Math.max(1, Number(options.minFontSize) || 5.2);
  const maxFontSize = Math.max(minFontSize, Number(options.maxFontSize) || 20);
  const context = getChipLabelMeasureContext();
  if (!(context instanceof CanvasRenderingContext2D)) {
    const fallbackScale = clamp(5.3 / Math.max(normalizedLabel.length, 1), 0.2, 1);
    return clamp(maxFontSize * fallbackScale, minFontSize, maxFontSize);
  }
  let low = minFontSize;
  let high = maxFontSize;
  let best = minFontSize;
  for (let step = 0; step < 10; step += 1) {
    const mid = (low + high) / 2;
    context.font = `700 ${mid}px "Trebuchet MS", "Gill Sans", "Segoe UI", sans-serif`;
    const width = context.measureText(normalizedLabel).width;
    if (width <= maxWidth) {
      best = mid;
      low = mid;
    } else {
      high = mid;
    }
  }
  return clamp(best, minFontSize, maxFontSize);
}

function normalizeChipStackCount(value, fallbackValue = CHIP_SET_MIN_STACKS) {
  const parsed = Math.round(Number(value));
  if (Number.isFinite(parsed)) {
    return clamp(parsed, CHIP_SET_MIN_STACKS, CHIP_SET_MAX_STACKS);
  }
  const fallbackParsed = Math.round(Number(fallbackValue));
  if (Number.isFinite(fallbackParsed)) {
    return clamp(fallbackParsed, CHIP_SET_MIN_STACKS, CHIP_SET_MAX_STACKS);
  }
  return CHIP_SET_MIN_STACKS;
}

function normalizeChipStackQuantity(value, fallbackValue = CHIP_STACK_MIN_QUANTITY) {
  const parsed = Math.round(Number(value));
  if (Number.isFinite(parsed)) {
    return clamp(parsed, CHIP_STACK_MIN_QUANTITY, CHIP_STACK_MAX_QUANTITY);
  }
  const fallbackParsed = Math.round(Number(fallbackValue));
  if (Number.isFinite(fallbackParsed)) {
    return clamp(fallbackParsed, CHIP_STACK_MIN_QUANTITY, CHIP_STACK_MAX_QUANTITY);
  }
  return CHIP_STACK_MIN_QUANTITY;
}

function normalizeChipStacksPayload(stacksPayload, stackCount = CHIP_SET_MIN_STACKS, options = {}) {
  const normalizedStackCount = normalizeChipStackCount(stackCount);
  const source = Array.isArray(stacksPayload) ? stacksPayload : [];
  const fallbackQuantity = normalizeChipStackQuantity(
    options.quantity,
    CHIP_STACK_DEFAULTS[0]?.value ?? CHIP_STACK_MIN_QUANTITY
  );
  const stacks = [];
  for (let index = 0; index < normalizedStackCount; index += 1) {
    const baseSpec = CHIP_STACK_DEFAULTS[index] || CHIP_STACK_DEFAULTS[0];
    const sourceStack = source[index] && typeof source[index] === 'object' ? source[index] : {};
    const sourceCountRaw =
      sourceStack.count ?? sourceStack.quantity ?? options.quantity ?? fallbackQuantity;
    const normalizedCount = clamp(
      Math.max(0, Math.round(Number(sourceCountRaw) || 0)),
      0,
      CHIP_STACK_MAX_QUANTITY
    );
    const valueCandidate = Number(sourceStack.value);
    const normalizedValue = Number.isFinite(valueCandidate)
      ? Math.max(0, Math.round(valueCandidate))
      : baseSpec.value;
    const labelCandidate = normalizeChipLabelText(sourceStack.label);
    stacks.push({
      count: normalizedCount,
      value: normalizedValue,
      color: normalizeHexColor(sourceStack.color || baseSpec.color),
      label: labelCandidate || normalizeChipLabelText(baseSpec.label || String(baseSpec.value))
    });
  }
  return stacks;
}

function getChipSetWorldWidth(chipSetState) {
  const stackCount = normalizeChipStackCount(
    chipSetState?.stackCount,
    Array.isArray(chipSetState?.stacks) ? chipSetState.stacks.length : CHIP_SET_MIN_STACKS
  );
  return DIE_SIZE_CHIP + (stackCount - 1) * CHIP_STACK_SPACING;
}

function getChipSetCenterBounds(chipSetState) {
  const width = getChipSetWorldWidth(chipSetState);
  const halfWidth = width / 2;
  const halfHeight = CHIP_STACK_HALF_SIZE;
  return {
    minX: Math.min(halfWidth, WORLD_WIDTH - halfWidth),
    maxX: Math.max(halfWidth, WORLD_WIDTH - halfWidth),
    minY: Math.min(halfHeight, WORLD_HEIGHT - halfHeight),
    maxY: Math.max(halfHeight, WORLD_HEIGHT - halfHeight)
  };
}

function getChipStackCenterFromNormalized(chipSetState, stackIndex) {
  const stackCount = normalizeChipStackCount(
    chipSetState?.stackCount,
    Array.isArray(chipSetState?.stacks) ? chipSetState.stacks.length : CHIP_SET_MIN_STACKS
  );
  const clampedIndex = clamp(Math.round(Number(stackIndex) || 0), 0, stackCount - 1);
  const centerX = Number(chipSetState?.x);
  const centerY = Number(chipSetState?.y);
  const startX = (Number.isFinite(centerX) ? centerX : WORLD_WIDTH / 2) - ((stackCount - 1) * CHIP_STACK_SPACING) / 2;
  return {
    x: startX + clampedIndex * CHIP_STACK_SPACING,
    y: Number.isFinite(centerY) ? centerY : WORLD_HEIGHT / 2
  };
}

function normalizeChipSetPayload(payload) {
  const stackCount = normalizeChipStackCount(
    payload?.stackCount,
    Array.isArray(payload?.stacks) ? payload.stacks.length : CHIP_SET_MIN_STACKS
  );
  const stacks = normalizeChipStacksPayload(payload?.stacks, stackCount, {
    quantity: payload?.stackQuantity
  });
  const bounds = getChipSetCenterBounds({ stackCount, stacks });
  const normalizedX = Number(payload?.x);
  const normalizedY = Number(payload?.y);
  const normalizedZ = Math.round(Number(payload?.z) || 1);
  const holderClientId =
    typeof payload?.holderClientId === 'string' && payload.holderClientId ? payload.holderClientId : null;
  return {
    x: Number.isFinite(normalizedX)
      ? clamp(normalizedX, bounds.minX, bounds.maxX)
      : clamp(WORLD_WIDTH / 2, bounds.minX, bounds.maxX),
    y: Number.isFinite(normalizedY)
      ? clamp(normalizedY, bounds.minY, bounds.maxY)
      : clamp(WORLD_HEIGHT / 2, bounds.minY, bounds.maxY),
    z: clamp(Number.isFinite(normalizedZ) ? normalizedZ : 1, 1, DECK_UI_Z_INDEX - 1),
    holderClientId,
    stackCount,
    stacks
  };
}

function getChipStackCenter(chipSetState, stackIndex) {
  const normalized = normalizeChipSetPayload(chipSetState);
  return getChipStackCenterFromNormalized(normalized, stackIndex);
}

function normalizeChipNumericValue(value, fallbackValue = 1) {
  const parsed = Math.round(Number(value));
  if (Number.isFinite(parsed)) {
    return Math.max(0, parsed);
  }
  const fallbackParsed = Math.round(Number(fallbackValue));
  if (Number.isFinite(fallbackParsed)) {
    return Math.max(0, fallbackParsed);
  }
  return 1;
}

function doesChipMatchStackSpec(chipColor, chipValue, stackState) {
  if (!stackState || typeof stackState !== 'object') {
    return false;
  }
  const normalizedChipColor = normalizeHexColor(chipColor || '#ffffff');
  const stackColor = normalizeHexColor(stackState.color || '#ffffff');
  if (normalizedChipColor !== stackColor) {
    return false;
  }
  const normalizedChipValue = normalizeChipNumericValue(chipValue, 1);
  const stackValue = normalizeChipNumericValue(stackState.value, 1);
  if (normalizedChipValue !== stackValue) {
    return false;
  }
  const stackCount = Math.max(0, Math.round(Number(stackState.count) || 0));
  return stackCount < CHIP_STACK_MAX_QUANTITY;
}

function canLooseChipBeDroppedIntoStack(chipDieState, stackState) {
  if (!chipDieState || normalizeDieType(chipDieState.type) !== 'chip') {
    return false;
  }
  return doesChipMatchStackSpec(chipDieState.chipColor, chipDieState.chipValue, stackState);
}

function getChipStackDropTargetAtPosition(x, y, chipDieState = null) {
  let bestTarget = null;
  let bestDistance = Number.POSITIVE_INFINITY;
  const targetX = Number(x);
  const targetY = Number(y);
  if (!Number.isFinite(targetX) || !Number.isFinite(targetY)) {
    return null;
  }
  const hitRadius = DIE_SIZE_CHIP * 0.52;
  for (const [chipSetId, chipSetState] of chipSetsById.entries()) {
    const normalizedSet = normalizeChipSetPayload(chipSetState);
    if (isWorldPointHiddenBySecretAreaForLocalViewer(normalizedSet.x, normalizedSet.y)) {
      continue;
    }
    for (let stackIndex = 0; stackIndex < normalizedSet.stackCount; stackIndex += 1) {
      const stackState = normalizedSet.stacks[stackIndex];
      if (!stackState) {
        continue;
      }
      if (chipDieState && !canLooseChipBeDroppedIntoStack(chipDieState, stackState)) {
        continue;
      }
      const center = getChipStackCenterFromNormalized(normalizedSet, stackIndex);
      const deltaX = targetX - center.x;
      const deltaY = targetY - center.y;
      const distance = Math.hypot(deltaX, deltaY);
      if (Math.abs(deltaX) > hitRadius || Math.abs(deltaY) > hitRadius) {
        continue;
      }
      if (distance > hitRadius) {
        continue;
      }
      if (distance < bestDistance) {
        bestDistance = distance;
        bestTarget = {
          chipSetId,
          stackIndex
        };
      }
    }
  }
  return bestTarget;
}

function normalizeSpinnerLabels(labels, segmentCount) {
  const normalizedCount = normalizeSpinnerSegmentCount(segmentCount);
  const source = Array.isArray(labels) ? labels : [];
  const nextLabels = [];
  for (let index = 0; index < normalizedCount; index += 1) {
    nextLabels.push(normalizeSpinnerLabelText(source[index]));
  }
  return nextLabels;
}

function getSpinnerSegmentCount(dieState) {
  return normalizeSpinnerSegmentCount(dieState?.spinnerSegments, SPINNER_DEFAULT_SEGMENTS);
}

function getSpinnerLabels(dieState) {
  return normalizeSpinnerLabels(dieState?.spinnerLabels, getSpinnerSegmentCount(dieState));
}

function getSpinnerSegmentLabel(dieState, value) {
  const segments = getSpinnerSegmentCount(dieState);
  const index = clamp(Math.round(Number(value) || 1), 1, segments) - 1;
  const labels = getSpinnerLabels(dieState);
  const customLabel = normalizeSpinnerLabelText(labels[index]);
  return customLabel || String(index + 1);
}

function getSpinnerSegmentCenterAngle(value, segmentCount) {
  const segments = normalizeSpinnerSegmentCount(segmentCount);
  const index = clamp(Math.round(Number(value) || 1), 1, segments) - 1;
  const sliceAngle = 360 / segments;
  return index * sliceAngle;
}

function getSpinnerSegmentIndexForAngle(angle, segmentCount) {
  const segments = normalizeSpinnerSegmentCount(segmentCount);
  const sliceAngle = 360 / segments;
  const normalizedAngle = ((Number(angle) || 0) % 360 + 360) % 360;
  return ((Math.round(normalizedAngle / sliceAngle) % segments) + segments) % segments;
}

function normalizeSpinnerRollTurns(value) {
  const numeric = Math.round(Number(value));
  if (!Number.isFinite(numeric)) {
    return SPINNER_ROLL_MIN_TURNS;
  }
  return clamp(numeric, SPINNER_ROLL_MIN_TURNS, SPINNER_ROLL_MAX_TURNS);
}

function getSpinnerNeedleAngle(dieState, now = Date.now()) {
  if (normalizeDieType(dieState?.type) !== 'spinner') {
    return 0;
  }
  const segmentCount = getSpinnerSegmentCount(dieState);
  const finalValue = clamp(Math.round(Number(dieState?.value) || 1), 1, segmentCount);
  const finalAngle = getSpinnerSegmentCenterAngle(finalValue, segmentCount);
  if (!isDieRolling(dieState, now)) {
    return finalAngle;
  }
  const startedAt = Number(dieState?.rollStartedAt);
  const duration = Math.max(1, Number(dieState?.rollDurationMs) || SPINNER_ROLL_DURATION_MS);
  const progress = clamp((now - startedAt) / duration, 0, 1);
  const eased = 1 - Math.pow(1 - progress, 3);
  const startAngleRaw = Number(dieState?.spinnerStartAngle);
  const startAngle = Number.isFinite(startAngleRaw)
    ? startAngleRaw
    : finalAngle;
  const spinTurns = normalizeSpinnerRollTurns(dieState?.spinnerSpinTurns);
  const normalizedDelta = ((finalAngle - startAngle) % 360 + 360) % 360;
  const totalRotation = spinTurns * 360 + normalizedDelta;
  return startAngle + totalRotation * eased;
}

function getDieSides(type, payload = null) {
  const normalizedType = normalizeDieType(type);
  if (
    normalizedType === 'arcade' ||
    normalizedType === 'label' ||
    normalizedType === 'media' ||
    normalizedType === 'counter' ||
    normalizedType === 'timer' ||
    normalizedType === 'stack-point'
  ) {
    return 1;
  }
  if (normalizedType === 'marble') {
    return 1;
  }
  if (normalizedType === 'chip') {
    return 2;
  }
  if (normalizedType === 'spinner') {
    return getSpinnerSegmentCount(payload);
  }
  if (normalizedType === 'coin') {
    return 2;
  }
  return normalizedType === 'd20' ? 20 : 6;
}

function getDieSize(type) {
  const normalizedType = normalizeDieType(type);
  if (normalizedType === 'arcade') {
    return Math.max(DIE_SIZE_ARCADE_WIDTH, DIE_SIZE_ARCADE_HEIGHT);
  }
  if (normalizedType === 'label') {
    return LABEL_MIN_WORLD_WIDTH;
  }
  if (normalizedType === 'media') {
    return MEDIA_DEFAULT_WIDTH;
  }
  if (normalizedType === 'counter') {
    return Math.max(DIE_SIZE_COUNTER_WIDTH, DIE_SIZE_COUNTER_HEIGHT);
  }
  if (normalizedType === 'timer') {
    return Math.max(DIE_SIZE_TIMER_WIDTH, DIE_SIZE_TIMER_HEIGHT);
  }
  if (normalizedType === 'marble') {
    return DIE_SIZE_MARBLE;
  }
  if (normalizedType === 'stack-point') {
    return Math.max(DIE_SIZE_STACK_POINT_WIDTH, DIE_SIZE_STACK_POINT_HEIGHT);
  }
  if (normalizedType === 'spinner') {
    return DIE_SIZE_SPINNER;
  }
  if (normalizedType === 'coin') {
    return DIE_SIZE_COIN;
  }
  if (normalizedType === 'chip') {
    return DIE_SIZE_CHIP;
  }
  return normalizedType === 'd20' ? DIE_SIZE_D20 : DIE_SIZE_D6;
}

function getDefaultMediaDimensions(provider = '') {
  const normalizedProvider = normalizeMediaProvider(provider);
  if (normalizedProvider === 'uploaded-audio') {
    return { width: MEDIA_DEFAULT_WIDTH_UPLOADED_AUDIO, height: MEDIA_DEFAULT_HEIGHT_UPLOADED_AUDIO };
  }
  if (normalizedProvider === 'uploaded-video') {
    return { width: MEDIA_DEFAULT_WIDTH_UPLOADED_VIDEO, height: MEDIA_DEFAULT_HEIGHT_UPLOADED_VIDEO };
  }
  if (normalizedProvider === 'soundcloud') {
    return { width: 500, height: MEDIA_DEFAULT_HEIGHT_SOUNDCLOUD };
  }
  return { width: MEDIA_DEFAULT_WIDTH, height: MEDIA_DEFAULT_HEIGHT_YOUTUBE };
}

function clampCounterValue(value) {
  const numeric = Number(value);
  if (!Number.isFinite(numeric)) {
    return 0;
  }
  return clamp(Math.round(numeric), COUNTER_MIN_VALUE, COUNTER_MAX_VALUE);
}

function clampTimerElapsedMs(value) {
  const numeric = Number(value);
  if (!Number.isFinite(numeric)) {
    return 0;
  }
  return clamp(Math.round(numeric), 0, TIMER_MAX_ELAPSED_MS);
}

function normalizeTimerSplits(value) {
  const source = Array.isArray(value) ? value : [];
  const nextSplits = [];
  for (let index = 0; index < source.length && nextSplits.length < TIMER_SPLIT_LIMIT; index += 1) {
    nextSplits.push(clampTimerElapsedMs(source[index]));
  }
  return nextSplits;
}

function getTimerElapsedMs(dieState, now = Date.now()) {
  if (normalizeDieType(dieState?.type) !== 'timer') {
    return 0;
  }
  let elapsed = clampTimerElapsedMs(dieState?.timerElapsedMs);
  if (dieState?.timerRunning === true) {
    const startedAt = Number(dieState?.timerStartedAt);
    if (Number.isFinite(startedAt) && startedAt > 0) {
      elapsed = clampTimerElapsedMs(elapsed + Math.max(0, Math.round(now - startedAt)));
    }
  }
  return elapsed;
}

function getTimerDisplayDigits(elapsedMs) {
  const clamped = clampTimerElapsedMs(elapsedMs);
  const totalSeconds = Math.floor(clamped / 1000);
  const minutesTotal = clamp(Math.floor(totalSeconds / 60), 0, TIMER_MAX_MINUTES);
  const seconds = totalSeconds % 60;
  const milliseconds = clamped % 1000;
  return [
    Math.floor(minutesTotal / 10),
    minutesTotal % 10,
    Math.floor(seconds / 10),
    seconds % 10,
    Math.floor(milliseconds / 100),
    Math.floor(milliseconds / 10) % 10,
    milliseconds % 10
  ];
}

function getTimerControlIconSvg(action, isRunning = false, elapsedMs = 0) {
  if (action === 'reset') {
    return '<path d="M8.4 8.2A4.8 4.8 0 1 1 7.2 12" /><path d="M7.3 6.35V9.6H10.55" />';
  }
  if (action === 'pause') {
    if (isRunning) {
      return '<path d="M8.65 6.3V17.7" /><path d="M15.35 6.3V17.7" />';
    }
    return '<path d="M9.1 7.05L17.2 12L9.1 16.95Z" />';
  }
  if (action === 'split') {
    return '<path d="M12 5.7V18.3" /><path d="M7.05 13.35L12 18.3L16.95 13.35" />';
  }
  return '';
}

function getTimerControlLabel(action, isRunning = false, elapsedMs = 0) {
  if (action === 'pause') {
    if (isRunning) {
      return 'pause';
    }
    return clampTimerElapsedMs(elapsedMs) <= 0 ? 'start' : 'resume';
  }
  if (action === 'split') {
    return 'split';
  }
  if (action === 'reset') {
    return 'reset';
  }
  return action;
}

function formatTimerElapsedLabel(elapsedMs) {
  const digits = getTimerDisplayDigits(elapsedMs);
  return `${digits[0]}${digits[1]}:${digits[2]}${digits[3]}.${digits[4]}${digits[5]}${digits[6]}`;
}

function getTimerSplitLabel(splitIndex) {
  return `s${splitIndex}`;
}

function getTimerSplitOrderIndex(totalSplits, reverseIndex) {
  return reverseIndex + 1;
}

function getTimerSplitRows(splits) {
  const rows = [];
  for (let reverseIndex = splits.length - 1; reverseIndex >= 0; reverseIndex -= 1) {
    const splitIndex = getTimerSplitOrderIndex(splits.length, reverseIndex);
    rows.push({
      splitLabel: getTimerSplitLabel(splitIndex),
      timeLabel: formatTimerElapsedLabel(splits[reverseIndex])
    });
  }
  return rows;
}

function createTimerSplitRowElement(splitLabel, timeLabel) {
  const row = document.createElement('div');
  row.className = 'table-timer-split-row';
  const splitIndexText = document.createElement('span');
  splitIndexText.className = 'table-timer-split-index';
  splitIndexText.textContent = splitLabel;
  const splitValueText = document.createElement('span');
  splitValueText.className = 'table-timer-split-value';
  splitValueText.textContent = timeLabel;
  row.appendChild(splitIndexText);
  row.appendChild(splitValueText);
  return row;
}

function renderTimerSplitRows(splitsContainer, splits) {
  if (!(splitsContainer instanceof HTMLElement)) {
    return;
  }
  splitsContainer.textContent = '';
  if (splits.length === 0) {
    const empty = document.createElement('div');
    empty.className = 'table-timer-split-empty';
    empty.textContent = 'no splits';
    splitsContainer.appendChild(empty);
    return;
  }
  const fragment = document.createDocumentFragment();
  const rows = getTimerSplitRows(splits);
  for (const row of rows) {
    fragment.appendChild(createTimerSplitRowElement(row.splitLabel, row.timeLabel));
  }
  splitsContainer.appendChild(fragment);
}

function createTimerControlContent(action, isRunning = false, elapsedMs = 0) {
  const label = getTimerControlLabel(action, isRunning, elapsedMs);
  const iconSvg = getTimerControlIconSvg(action, isRunning, elapsedMs);
  const content = document.createElement('span');
  content.className = 'table-timer-control-content';
  const icon = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
  icon.setAttribute('class', 'table-timer-control-icon');
  icon.setAttribute('viewBox', '0 0 24 24');
  icon.setAttribute('fill', 'none');
  icon.setAttribute('aria-hidden', 'true');
  icon.innerHTML = iconSvg;
  const text = document.createElement('span');
  text.className = 'table-timer-control-label';
  text.setAttribute('data-timer-control-label', '1');
  text.textContent = label;
  content.appendChild(icon);
  content.appendChild(text);
  return content;
}

function setTimerControlLabel(controlElement, action, isRunning = false, elapsedMs = 0) {
  if (!(controlElement instanceof HTMLElement)) {
    return;
  }
  const nextLabel = getTimerControlLabel(action, isRunning, elapsedMs);
  const nextIconSvg = getTimerControlIconSvg(action, isRunning, elapsedMs);
  let iconElement = controlElement.querySelector('.table-timer-control-icon');
  let labelElement = controlElement.querySelector('[data-timer-control-label="1"]');
  if (!(labelElement instanceof HTMLElement) || !(iconElement instanceof SVGElement)) {
    const content = createTimerControlContent(action, isRunning, elapsedMs);
    controlElement.textContent = '';
    controlElement.appendChild(content);
    iconElement = controlElement.querySelector('.table-timer-control-icon');
    labelElement = controlElement.querySelector('[data-timer-control-label="1"]');
  }
  if (labelElement instanceof HTMLElement && labelElement.textContent !== nextLabel) {
    labelElement.textContent = nextLabel;
  }
  if (iconElement instanceof SVGElement && iconElement.innerHTML !== nextIconSvg) {
    iconElement.innerHTML = nextIconSvg;
  }
}

function clampMediaDimensions(widthValue, heightValue, provider = '') {
  const defaultDimensions = getDefaultMediaDimensions(provider);
  if (isFixedSizeMediaProvider(provider)) {
    return defaultDimensions;
  }
  let width = Number(widthValue);
  let height = Number(heightValue);
  if (!Number.isFinite(width) || width <= 0 || !Number.isFinite(height) || height <= 0) {
    width = defaultDimensions.width;
    height = defaultDimensions.height;
  }
  width = Math.max(MEDIA_MIN_WORLD_WIDTH, width);
  height = Math.max(MEDIA_MIN_WORLD_HEIGHT, height);
  const maxWidth = Math.max(MEDIA_MIN_WORLD_WIDTH, Math.min(MEDIA_MAX_WORLD_WIDTH, WORLD_WIDTH - 20));
  const maxHeight = Math.max(MEDIA_MIN_WORLD_HEIGHT, Math.min(MEDIA_MAX_WORLD_HEIGHT, WORLD_HEIGHT - 20));
  const scale = Math.min(1, maxWidth / width, maxHeight / height);
  return {
    width: clamp(width * scale, MEDIA_MIN_WORLD_WIDTH, maxWidth),
    height: clamp(height * scale, MEDIA_MIN_WORLD_HEIGHT, maxHeight)
  };
}

function normalizeLabelText(value) {
  const raw = String(value ?? '').replace(/\r\n?/g, '\n').slice(0, LABEL_TEXT_MAX_LENGTH);
  return raw;
}

function normalizeLabelVariant(value) {
  return String(value || '').trim().toLowerCase() === LABEL_VARIANT_HEADING
    ? LABEL_VARIANT_HEADING
    : LABEL_VARIANT_DEFAULT;
}

function isHeadingLabelState(value) {
  if (!value || typeof value !== 'object') {
    return false;
  }
  return normalizeLabelVariant(value.labelVariant) === LABEL_VARIANT_HEADING;
}

function getLabelDefaultTextForVariant(value) {
  const variantSource = value && typeof value === 'object' ? value.labelVariant : value;
  return normalizeLabelVariant(variantSource) === LABEL_VARIANT_HEADING
    ? LABEL_HEADING_DEFAULT_TEXT
    : LABEL_DEFAULT_TEXT;
}

function getLabelTextScale(valueOrState, fallback = LABEL_TEXT_SCALE_DEFAULT) {
  const rawValue =
    valueOrState && typeof valueOrState === 'object'
      ? Number(valueOrState.textScale)
      : Number(valueOrState);
  const fallbackValue = Number(fallback);
  const normalized = Number.isFinite(rawValue)
    ? rawValue
    : Number.isFinite(fallbackValue)
      ? fallbackValue
      : LABEL_TEXT_SCALE_DEFAULT;
  return clamp(normalized, LABEL_TEXT_SCALE_MIN, LABEL_TEXT_SCALE_MAX);
}

function getLabelFontSizePx(dieState) {
  const textScale = getLabelTextScale(dieState);
  const worldFontSize = LABEL_LINE_WORLD_HEIGHT * textScale * LABEL_FONT_SIZE_FACTOR;
  const screenFontSize = clamp(worldFontSize * camera.scale, 0.01, 1680);
  return snapToDevicePixel(screenFontSize, 0.01);
}

function measureLabelWorldDimensions(textValue, options = {}) {
  const normalizedText = normalizeLabelText(textValue);
  const lines = normalizedText.length > 0 ? normalizedText.split('\n') : [''];
  const textScale = getLabelTextScale(options.textScale, LABEL_TEXT_SCALE_DEFAULT);
  const charWorldWidth = Math.max(1, LABEL_CHAR_WORLD_WIDTH * textScale);
  const lineWorldHeight = Math.max(
    1,
    LABEL_LINE_WORLD_HEIGHT * textScale * LABEL_FONT_SIZE_FACTOR * LABEL_TEXT_LINE_HEIGHT
  );
  const paddingX = LABEL_PADDING_WORLD_X;
  const paddingY = LABEL_PADDING_WORLD_Y;
  const maxWidthConstraint = clamp(
    Number.isFinite(Number(options.maxWidth)) ? Number(options.maxWidth) : LABEL_MAX_WORLD_WIDTH,
    LABEL_MIN_WORLD_WIDTH,
    LABEL_MAX_WORLD_WIDTH
  );
  const maxCharsPerWrappedLine = Math.max(
    1,
    Math.floor((maxWidthConstraint - paddingX * 2) / charWorldWidth)
  );
  let wrappedLineCount = 0;
  let maxLineLength = 1;
  for (const line of lines) {
    const lineLength = Array.from(String(line || '')).length;
    maxLineLength = Math.max(maxLineLength, lineLength);
    wrappedLineCount += Math.max(1, Math.ceil(lineLength / maxCharsPerWrappedLine));
  }
  const measuredWidth =
    Math.min(maxLineLength, maxCharsPerWrappedLine) * charWorldWidth + paddingX * 2 + LABEL_MEASURE_BUFFER_X;
  const measuredHeight =
    Math.max(1, wrappedLineCount) * lineWorldHeight + paddingY * 2 + LABEL_MEASURE_BUFFER_Y;
  return {
    width: clamp(measuredWidth, LABEL_MIN_WORLD_WIDTH, maxWidthConstraint),
    height: clamp(measuredHeight, LABEL_MIN_WORLD_HEIGHT, LABEL_MAX_WORLD_HEIGHT)
  };
}

function findLabelTextScaleToFit(textValue, targetWidth, targetHeight, preferredScale = LABEL_TEXT_SCALE_DEFAULT) {
  const normalizedText = normalizeLabelText(textValue);
  const width = clamp(Number(targetWidth) || LABEL_MIN_WORLD_WIDTH, LABEL_MIN_WORLD_WIDTH, LABEL_MAX_WORLD_WIDTH);
  const height = clamp(Number(targetHeight) || LABEL_MIN_WORLD_HEIGHT, LABEL_MIN_WORLD_HEIGHT, LABEL_MAX_WORLD_HEIGHT);
  const preferred = getLabelTextScale(preferredScale, LABEL_TEXT_SCALE_DEFAULT);
  const minScale = LABEL_TEXT_SCALE_MIN;
  const fitsAtScale = (scale) => {
    const measured = measureLabelWorldDimensions(normalizedText, {
      textScale: scale,
      maxWidth: width
    });
    return measured.width <= width + 0.001 && measured.height <= height + 0.001;
  };
  if (fitsAtScale(preferred)) {
    return preferred;
  }
  if (!fitsAtScale(minScale)) {
    return minScale;
  }
  let low = minScale;
  let high = preferred;
  for (let iteration = 0; iteration < 18; iteration += 1) {
    const midpoint = (low + high) / 2;
    if (fitsAtScale(midpoint)) {
      low = midpoint;
    } else {
      high = midpoint;
    }
  }
  return getLabelTextScale(low);
}

function resolveLabelLayoutForBounds(textValue, targetWidth, targetHeight, preferredScale = LABEL_TEXT_SCALE_DEFAULT) {
  const normalizedText = normalizeLabelText(textValue);
  let width = clamp(Number(targetWidth) || LABEL_MIN_WORLD_WIDTH, LABEL_MIN_WORLD_WIDTH, LABEL_MAX_WORLD_WIDTH);
  let height = clamp(Number(targetHeight) || LABEL_MIN_WORLD_HEIGHT, LABEL_MIN_WORLD_HEIGHT, LABEL_MAX_WORLD_HEIGHT);
  let textScale = findLabelTextScaleToFit(normalizedText, width, height, preferredScale);
  let measured = measureLabelWorldDimensions(normalizedText, {
    textScale,
    maxWidth: width
  });
  width = clamp(Math.max(width, measured.width), LABEL_MIN_WORLD_WIDTH, LABEL_MAX_WORLD_WIDTH);
  height = clamp(Math.max(height, measured.height), LABEL_MIN_WORLD_HEIGHT, LABEL_MAX_WORLD_HEIGHT);
  if (textScale <= LABEL_TEXT_SCALE_MIN + 0.001) {
    const minimumMeasured = measureLabelWorldDimensions(normalizedText, {
      textScale: LABEL_TEXT_SCALE_MIN,
      maxWidth: width
    });
    width = clamp(Math.max(width, minimumMeasured.width), LABEL_MIN_WORLD_WIDTH, LABEL_MAX_WORLD_WIDTH);
    height = clamp(Math.max(height, minimumMeasured.height), LABEL_MIN_WORLD_HEIGHT, LABEL_MAX_WORLD_HEIGHT);
    measured = minimumMeasured;
  }
  return {
    text: normalizedText,
    textScale: getLabelTextScale(textScale),
    labelWidth: width,
    labelHeight: height,
    measuredWidth: measured.width,
    measuredHeight: measured.height
  };
}

function getDieWorldDimensions(typeOrPayload, payload = typeOrPayload) {
  const dieType =
    typeof typeOrPayload === 'string'
      ? normalizeDieType(typeOrPayload)
      : normalizeDieType(typeOrPayload?.type);
  if (dieType === 'arcade') {
    return {
      width: DIE_SIZE_ARCADE_WIDTH,
      height: DIE_SIZE_ARCADE_HEIGHT
    };
  }
  if (dieType === 'media') {
    return clampMediaDimensions(
      payload?.mediaWidth,
      payload?.mediaHeight,
      payload?.mediaProvider
    );
  }
  if (dieType === 'counter') {
    return {
      width: DIE_SIZE_COUNTER_WIDTH,
      height: DIE_SIZE_COUNTER_HEIGHT
    };
  }
  if (dieType === 'timer') {
    return {
      width: DIE_SIZE_TIMER_WIDTH,
      height: DIE_SIZE_TIMER_HEIGHT
    };
  }
  if (dieType === 'stack-point') {
    return {
      width: DIE_SIZE_STACK_POINT_WIDTH,
      height: DIE_SIZE_STACK_POINT_HEIGHT
    };
  }
  if (dieType !== 'label') {
    const size = getDieSize(dieType);
    return { width: size, height: size };
  }
  const normalizedText = normalizeLabelText(payload?.text);
  const measured = measureLabelWorldDimensions(normalizedText, {
    textScale: getLabelTextScale(payload, LABEL_TEXT_SCALE_DEFAULT)
  });
  const payloadWidth = Number(payload?.labelWidth);
  const payloadHeight = Number(payload?.labelHeight);
  return {
    width: Number.isFinite(payloadWidth)
      ? clamp(payloadWidth, LABEL_MIN_WORLD_WIDTH, LABEL_MAX_WORLD_WIDTH)
      : measured.width,
    height: Number.isFinite(payloadHeight)
      ? clamp(payloadHeight, LABEL_MIN_WORLD_HEIGHT, LABEL_MAX_WORLD_HEIGHT)
      : measured.height
  };
}

function getDieCenterBounds(dieType, width, height) {
  const normalizedType = normalizeDieType(dieType);
  const fallbackSize = getDieSize(normalizedType);
  const resolvedWidth = Math.max(1, Number(width) || fallbackSize);
  const resolvedHeight = Math.max(1, Number(height) || fallbackSize);
  const edgeOverflow = normalizedType === 'label' ? LABEL_EDGE_OVERFLOW : 0;
  const minX = resolvedWidth / 2 - edgeOverflow;
  const maxX = WORLD_WIDTH - resolvedWidth / 2 + edgeOverflow;
  const minY = resolvedHeight / 2 - edgeOverflow;
  const maxY = WORLD_HEIGHT - resolvedHeight / 2 + edgeOverflow;
  return {
    minX: Math.min(minX, maxX),
    maxX: Math.max(minX, maxX),
    minY: Math.min(minY, maxY),
    maxY: Math.max(minY, maxY)
  };
}

function getSecureRandomUint32() {
  if (typeof crypto?.getRandomValues === 'function') {
    const randomBuffer = new Uint32Array(1);
    crypto.getRandomValues(randomBuffer);
    return randomBuffer[0] >>> 0;
  }
  return Math.floor(Math.random() * 0x100000000) >>> 0;
}

function getRandomIntInclusive(minValue, maxValue) {
  const min = Math.ceil(Number(minValue));
  const max = Math.floor(Number(maxValue));
  if (!Number.isFinite(min) || !Number.isFinite(max)) {
    return 0;
  }
  if (max <= min) {
    return min;
  }
  const span = max - min + 1;
  const maxRandomExclusive = 0x100000000;
  if (span > 0 && span <= maxRandomExclusive) {
    const cutoff = maxRandomExclusive - (maxRandomExclusive % span);
    let sample = 0;
    do {
      sample = getSecureRandomUint32();
    } while (sample >= cutoff);
    return min + (sample % span);
  }
  return min + Math.floor(Math.random() * span);
}

function normalizeDicePayload(payload) {
  const type = normalizeDieType(payload?.type);
  const dimensions = getDieWorldDimensions(type, payload);
  const centerBounds = getDieCenterBounds(type, dimensions.width, dimensions.height);
  const spinnerSegments = type === 'spinner' ? normalizeSpinnerSegmentCount(payload?.spinnerSegments) : 0;
  const spinnerLabels = type === 'spinner' ? normalizeSpinnerLabels(payload?.spinnerLabels, spinnerSegments) : [];
  const spinnerResultVisible = type === 'spinner' && payload?.spinnerResultVisible === true;
  const spinnerHighlightVisible =
    type === 'spinner' &&
    (payload?.spinnerHighlightVisible === true || spinnerResultVisible);
  const spinnerStartAngle = type === 'spinner'
    ? (Number.isFinite(Number(payload?.spinnerStartAngle))
      ? Number(payload?.spinnerStartAngle)
      : getSpinnerSegmentCenterAngle(payload?.value, spinnerSegments))
    : 0;
  const spinnerSpinTurns = type === 'spinner' ? normalizeSpinnerRollTurns(payload?.spinnerSpinTurns) : 0;
  const arcadeMenuIndex =
    type === 'arcade'
      ? clamp(
        Math.round(Number(payload?.arcadeMenuIndex) || 0),
        0,
        Math.max(0, ARCADE_MENU_OPTION_LABELS.length - 1)
      )
      : 0;
  const arcadeJPressed = type === 'arcade' && payload?.arcadeJPressed === true;
  const arcadeKPressed = type === 'arcade' && payload?.arcadeKPressed === true;
  const arcadeScreen = type === 'arcade' ? normalizeArcadeScreen(payload?.arcadeScreen) : ARCADE_SCREEN_MAIN;
  const arcadeStickX = type === 'arcade' ? normalizeArcadeStickAxis(payload?.arcadeStickX) : 0;
  const arcadeStickY = type === 'arcade' ? normalizeArcadeStickAxis(payload?.arcadeStickY) : 0;
  const arcadeManaMenuIndex =
    type === 'arcade'
      ? normalizeArcadeManaMenuIndex(payload?.arcadeManaMenuIndex)
      : 0;
  const arcadeControllerClientId =
    type === 'arcade'
      ? String(payload?.arcadeControllerClientId || '').trim().slice(0, 128)
      : '';
  const arcadeControllerPlayerToken =
    type === 'arcade'
      ? normalizeArcadePlayerToken(payload?.arcadeControllerPlayerToken)
      : '';
  const arcadeControllerName =
    type === 'arcade'
      ? String(payload?.arcadeControllerName || '').trim().slice(0, 24)
      : '';
  const arcadeControllerColor =
    type === 'arcade'
      ? normalizeHexColor(payload?.arcadeControllerColor || '#ff7a59')
      : '#ff7a59';
  const arcadeMoveDirection = type === 'arcade'
    ? normalizeArcadeDirectionVector(payload?.arcadeMgDirX, payload?.arcadeMgDirY)
    : { x: 0, y: 0 };
  const arcadeQueuedDirection = type === 'arcade'
    ? normalizeArcadeDirectionVector(payload?.arcadeMgQueuedDirX, payload?.arcadeMgQueuedDirY)
    : { x: 0, y: 0 };
  const arcadeMgTileX = type === 'arcade' ? normalizeArcadeGridCoord(payload?.arcadeMgTileX) : ARCADE_MANA_CENTER_TILE;
  const arcadeMgTileY = type === 'arcade' ? normalizeArcadeGridCoord(payload?.arcadeMgTileY) : ARCADE_MANA_CENTER_TILE;
  const arcadeMgTailPath = type === 'arcade' ? normalizeArcadeManaTailPath(payload?.arcadeMgTailPath) : '';
  const arcadeMgLooseManaPath = type === 'arcade' ? normalizeArcadeManaTailPath(payload?.arcadeMgLooseManaPath) : '';
  const arcadeMgClearManaPath = type === 'arcade' ? normalizeArcadeManaTailPath(payload?.arcadeMgClearManaPath) : '';
  const arcadeMgDemonsPath = type === 'arcade' ? normalizeArcadeDemonPath(payload?.arcadeMgDemonsPath) : '';
  const arcadeMgBombPath = type === 'arcade' ? normalizeArcadeBombPath(payload?.arcadeMgBombPath) : '';
  const arcadeMgBombFxPath = type === 'arcade' ? normalizeArcadeBombFxPath(payload?.arcadeMgBombFxPath) : '';
  const arcadeMgPickupPulsePath = type === 'arcade' ? normalizeArcadePickupPulsePath(payload?.arcadeMgPickupPulsePath) : '';
  const arcadeMgLastPickupAt = type === 'arcade' ? normalizeArcadeTimestamp(payload?.arcadeMgLastPickupAt) : 0;
  const arcadeMgManaPickupCount = type === 'arcade' ? normalizeArcadeManaPickupCount(payload?.arcadeMgManaPickupCount) : 0;
  const arcadeMgHasSpawnedDemon = type === 'arcade' && payload?.arcadeMgHasSpawnedDemon === true;
  const arcadeMgNextDemonSpawnAt = type === 'arcade' ? normalizeArcadeTimestamp(payload?.arcadeMgNextDemonSpawnAt) : 0;
  const arcadeMgManaType = type === 'arcade' ? normalizeArcadeManaType(payload?.arcadeMgManaType) : ARCADE_MANA_TYPE_WHITE;
  const arcadeMgManaTileX = type === 'arcade' ? normalizeArcadeGridCoord(payload?.arcadeMgManaTileX) : ARCADE_MANA_CENTER_TILE;
  const arcadeMgManaTileY = type === 'arcade' ? normalizeArcadeGridCoord(payload?.arcadeMgManaTileY) : ARCADE_MANA_CENTER_TILE;
  const arcadeMgGameOver = type === 'arcade' && payload?.arcadeMgGameOver === true;
  const arcadeMgGameOverAt = type === 'arcade' ? normalizeArcadeTimestamp(payload?.arcadeMgGameOverAt) : 0;
  const arcadeMgGameOverFlip = type === 'arcade' && payload?.arcadeMgGameOverFlip === true;
  const arcadeMgNewHighScore = type === 'arcade' && payload?.arcadeMgNewHighScore === true;
  const arcadeMgSquareClearScore = type === 'arcade'
    ? Math.max(0, Math.round(Number(payload?.arcadeMgSquareClearScore) || 0))
    : 0;
  const arcadeMgComboCount = type === 'arcade'
    ? Math.max(0, Math.round(Number(payload?.arcadeMgComboCount) || 0))
    : 0;
  const arcadeMgComboLastScoredAt = type === 'arcade' ? normalizeArcadeTimestamp(payload?.arcadeMgComboLastScoredAt) : 0;
  const arcadeMgPhaseActive = type === 'arcade' && payload?.arcadeMgPhaseActive === true;
  const arcadeMgPhaseStartedAt = type === 'arcade' ? normalizeArcadeTimestamp(payload?.arcadeMgPhaseStartedAt) : 0;
  const arcadeMgPotionActive = type === 'arcade' && payload?.arcadeMgPotionActive === true;
  const arcadeMgPotionStartedAt = type === 'arcade' ? normalizeArcadeTimestamp(payload?.arcadeMgPotionStartedAt) : 0;
  const arcadeMgClearManaStartedAt = type === 'arcade' ? normalizeArcadeTimestamp(payload?.arcadeMgClearManaStartedAt) : 0;
  const arcadeMgMoveStartedAt = type === 'arcade' ? normalizeArcadeTimestamp(payload?.arcadeMgMoveStartedAt) : 0;
  const arcadeMgQueuedAt = type === 'arcade' ? normalizeArcadeTimestamp(payload?.arcadeMgQueuedAt) : 0;
  const arcadeMgInputQueuePath = type === 'arcade' ? normalizeArcadeInputQueuePath(payload?.arcadeMgInputQueuePath) : '';
  const sides = getDieSides(type, {
    spinnerSegments
  });
  const nextX = Number(payload?.x);
  const nextY = Number(payload?.y);
  const nextValue = Number(payload?.value);
  const nextZ = Math.round(Number(payload?.z) || 1);
  const holderClientId = typeof payload?.holderClientId === 'string' && payload.holderClientId ? payload.holderClientId : null;
  const drawLifted = payload?.drawLifted === true;
  const rollStartedAt = Number(payload?.rollStartedAt);
  const rollDurationMs = Number(payload?.rollDurationMs);
  const rollSeed = Math.floor(Number(payload?.rollSeed) || 0);
  const velocityX = type === 'marble' && Number.isFinite(Number(payload?.velocityX))
    ? clamp(Number(payload.velocityX), -MARBLE_FLICK_MAX_SPEED, MARBLE_FLICK_MAX_SPEED)
    : 0;
  const velocityY = type === 'marble' && Number.isFinite(Number(payload?.velocityY))
    ? clamp(Number(payload.velocityY), -MARBLE_FLICK_MAX_SPEED, MARBLE_FLICK_MAX_SPEED)
    : 0;
  const moving =
    type === 'marble' &&
    payload?.moving === true &&
    Boolean(holderClientId) &&
    Math.hypot(velocityX, velocityY) > MARBLE_FORCE_STOP_SPEED;
  const marbleHue = type === 'marble' ? normalizeMarbleHue(payload?.marbleHue) : MARBLE_DEFAULT_HUE;
  const labelVariant = type === 'label' ? normalizeLabelVariant(payload?.labelVariant) : LABEL_VARIANT_DEFAULT;
  const textColor = labelVariant === LABEL_VARIANT_HEADING
    ? HEADING_LABEL_TEXT_COLOR
    : normalizeHexColor(payload?.textColor || '#ff7a59');
  const text = normalizeLabelText(payload?.text);
  const chipColor = type === 'chip' ? normalizeHexColor(payload?.chipColor || '#ffffff') : '#ffffff';
  const chipLabel = type === 'chip'
    ? normalizeChipLabelText(payload?.chipLabel || payload?.chipValue || '1') || '1'
    : '';
  const chipValueRaw = Number(payload?.chipValue);
  const chipValue = type === 'chip'
    ? (Number.isFinite(chipValueRaw) ? Math.max(0, Math.round(chipValueRaw)) : 1)
    : 0;
  const chipSetId = type === 'chip' ? String(payload?.chipSetId || '').trim() : '';
  const chipStackIndexRaw = Number(payload?.chipStackIndex);
  const chipStackIndex = type === 'chip'
    ? (Number.isFinite(chipStackIndexRaw) ? Math.max(0, Math.round(chipStackIndexRaw)) : 0)
    : 0;
  const timerElapsedMs = type === 'timer' ? clampTimerElapsedMs(payload?.timerElapsedMs) : 0;
  const timerStartedAtRaw = type === 'timer' ? Number(payload?.timerStartedAt) : 0;
  const timerStartedAt = Number.isFinite(timerStartedAtRaw) && timerStartedAtRaw > 0 ? Math.floor(timerStartedAtRaw) : 0;
  const timerRunning = type === 'timer' && payload?.timerRunning === true && timerStartedAt > 0 && timerElapsedMs < TIMER_MAX_ELAPSED_MS;
  const timerSplits = type === 'timer' ? normalizeTimerSplits(payload?.timerSplits) : [];
  const timerSplitsVisible = type === 'timer' ? (payload?.timerSplitsVisible === true || timerSplits.length > 0) : false;
  const textScale = getLabelTextScale(payload?.textScale, LABEL_TEXT_SCALE_DEFAULT);
  const labelLocked = type === 'label' ? payload?.labelLocked === true : false;
  const labelRotation = type === 'label' ? normalizeStickerRotationDegrees(payload?.labelRotation) : 0;
  let mediaProvider = type === 'media' ? normalizeMediaProvider(payload?.mediaProvider) : '';
  let mediaSourceUrl = type === 'media' ? normalizeUploadedMediaSourceUrl(payload?.mediaSourceUrl, mediaProvider) : '';
  let mediaEmbedUrl = type === 'media' ? normalizeMediaSourceUrl(payload?.mediaEmbedUrl) : '';
  const mediaTitle = type === 'media' ? normalizeMediaTitle(payload?.mediaTitle) : '';
  const mediaMimeType = type === 'media' ? String(payload?.mediaMimeType || '').trim().slice(0, 120) : '';
  const mediaPosterUrl = type === 'media' ? normalizeUploadedMediaPosterUrl(payload?.mediaPosterUrl) : '';
  if (type === 'media' && mediaSourceUrl) {
    const parsedFromSource = parseEmbeddableMediaUrl(mediaSourceUrl);
    if (parsedFromSource) {
      mediaProvider = mediaProvider || normalizeMediaProvider(parsedFromSource.provider);
      mediaSourceUrl = normalizeMediaSourceUrl(parsedFromSource.sourceUrl) || mediaSourceUrl;
      mediaEmbedUrl = normalizeMediaSourceUrl(parsedFromSource.embedUrl) || mediaEmbedUrl;
    }
  }
  if (type === 'media' && !mediaSourceUrl && mediaEmbedUrl) {
    const parsedFromEmbed = parseEmbeddableMediaUrl(mediaEmbedUrl);
    if (parsedFromEmbed) {
      mediaProvider = mediaProvider || normalizeMediaProvider(parsedFromEmbed.provider);
      mediaSourceUrl = normalizeMediaSourceUrl(parsedFromEmbed.sourceUrl) || mediaSourceUrl;
      mediaEmbedUrl = normalizeMediaSourceUrl(parsedFromEmbed.embedUrl) || mediaEmbedUrl;
    }
  }
  if (type === 'media' && !mediaProvider && mediaEmbedUrl) {
    try {
      const embedHost = new URL(mediaEmbedUrl).hostname.toLowerCase();
      if (embedHost === 'www.youtube.com' || embedHost.endsWith('.youtube.com') || embedHost.endsWith('youtube-nocookie.com')) {
        mediaProvider = 'youtube';
      } else if (embedHost === 'w.soundcloud.com' || embedHost.endsWith('.soundcloud.com')) {
        mediaProvider = 'soundcloud';
      }
    } catch {
      // Ignore malformed embed URLs from legacy payloads.
    }
  }
  const mediaStartedAtRaw = type === 'media' ? Number(payload?.mediaStartedAt) : 0;
  const mediaStartNonceRaw = type === 'media' ? Number(payload?.mediaStartNonce) : 0;
  const mediaStartedAt = Number.isFinite(mediaStartedAtRaw) && mediaStartedAtRaw > 0 ? Math.floor(mediaStartedAtRaw) : 0;
  const mediaStartNonce = Number.isFinite(mediaStartNonceRaw) ? Math.floor(mediaStartNonceRaw) : 0;
  const normalizedHolderClientId = labelLocked ? null : holderClientId;
  const normalizedValue = type === 'counter'
    ? clampCounterValue(nextValue)
    : type === 'timer'
      ? 0
    : type === 'arcade'
      ? 1
    : type === 'chip'
      ? 1
    : type === 'stack-point'
      ? 1
    : clamp(Number.isFinite(nextValue) ? Math.round(nextValue) : 1, 1, sides);
  return {
    type,
    x: Number.isFinite(nextX)
      ? clamp(nextX, centerBounds.minX, centerBounds.maxX)
      : clamp(WORLD_WIDTH / 2, centerBounds.minX, centerBounds.maxX),
    y: Number.isFinite(nextY)
      ? clamp(nextY, centerBounds.minY, centerBounds.maxY)
      : clamp(WORLD_HEIGHT / 2, centerBounds.minY, centerBounds.maxY),
    z: clamp(Number.isFinite(nextZ) ? nextZ : 1, 1, DECK_UI_Z_INDEX - 1),
    value: normalizedValue,
    text,
    textColor,
    labelVariant,
    chipColor,
    chipLabel,
    chipValue,
    chipSetId,
    chipStackIndex,
    timerElapsedMs,
    timerRunning,
    timerStartedAt,
    timerSplits,
    timerSplitsVisible,
    textScale,
    labelLocked,
    labelRotation,
    labelWidth: dimensions.width,
    labelHeight: dimensions.height,
    mediaProvider,
    mediaSourceUrl,
    mediaEmbedUrl,
    mediaTitle,
    mediaMimeType,
    mediaPosterUrl,
    mediaStartedAt,
    mediaStartNonce,
    mediaWidth: dimensions.width,
    mediaHeight: dimensions.height,
    spinnerSegments,
    spinnerLabels,
    spinnerResultVisible,
    spinnerHighlightVisible,
    spinnerStartAngle,
    spinnerSpinTurns,
    arcadeMenuIndex,
    arcadeJPressed,
    arcadeKPressed,
    arcadeScreen,
    arcadeStickX,
    arcadeStickY,
    arcadeManaMenuIndex,
    arcadeControllerClientId,
    arcadeControllerPlayerToken,
    arcadeControllerName,
    arcadeControllerColor,
    arcadeMgTileX,
    arcadeMgTileY,
    arcadeMgTailPath,
    arcadeMgLooseManaPath,
    arcadeMgClearManaPath,
    arcadeMgDemonsPath,
    arcadeMgBombPath,
    arcadeMgBombFxPath,
    arcadeMgPickupPulsePath,
    arcadeMgLastPickupAt,
    arcadeMgManaPickupCount,
    arcadeMgHasSpawnedDemon,
    arcadeMgNextDemonSpawnAt,
    arcadeMgManaType,
    arcadeMgManaTileX,
    arcadeMgManaTileY,
    arcadeMgGameOver,
    arcadeMgGameOverAt,
    arcadeMgGameOverFlip,
    arcadeMgNewHighScore,
    arcadeMgSquareClearScore,
    arcadeMgComboCount,
    arcadeMgComboLastScoredAt,
    arcadeMgPhaseActive,
    arcadeMgPhaseStartedAt,
    arcadeMgPotionActive,
    arcadeMgPotionStartedAt,
    arcadeMgClearManaStartedAt,
    arcadeMgDirX: arcadeMoveDirection.x,
    arcadeMgDirY: arcadeMoveDirection.y,
    arcadeMgQueuedDirX: arcadeQueuedDirection.x,
    arcadeMgQueuedDirY: arcadeQueuedDirection.y,
    arcadeMgMoveStartedAt,
    arcadeMgQueuedAt,
    arcadeMgInputQueuePath,
    drawLifted,
    holderClientId: normalizedHolderClientId,
    moving,
    velocityX,
    velocityY,
    marbleHue,
    rollStartedAt:
      type === 'label' ||
      type === 'media' ||
      type === 'marble' ||
      type === 'counter' ||
      type === 'timer' ||
      type === 'arcade' ||
      type === 'stack-point'
        ? 0
        : Number.isFinite(rollStartedAt)
          ? Math.max(0, rollStartedAt)
          : 0,
    rollDurationMs: Number.isFinite(rollDurationMs) ? clamp(Math.round(rollDurationMs), 120, 3000) : DIE_ROLL_DURATION_MS,
    rollSeed: Number.isFinite(rollSeed) ? rollSeed : 0
  };
}

function isDieRolling(dieState, now = Date.now()) {
  if (!dieState || typeof dieState !== 'object') {
    return false;
  }
  const dieType = normalizeDieType(dieState.type);
  if (
    dieType === 'label' ||
    dieType === 'media' ||
    dieType === 'marble' ||
    dieType === 'counter' ||
    dieType === 'timer' ||
    dieType === 'arcade' ||
    dieType === 'stack-point'
  ) {
    return false;
  }
  const startedAt = Number(dieState.rollStartedAt);
  const duration = Number(dieState.rollDurationMs);
  if (!Number.isFinite(startedAt) || startedAt <= 0 || !Number.isFinite(duration) || duration <= 0) {
    return false;
  }
  return now < startedAt + duration;
}

function getPseudoRandomFromSeed(seedValue) {
  let seed = Math.floor(Number(seedValue) || 0) >>> 0;
  seed ^= seed >>> 16;
  seed = Math.imul(seed, 0x7feb352d) >>> 0;
  seed ^= seed >>> 15;
  seed = Math.imul(seed, 0x846ca68b) >>> 0;
  seed ^= seed >>> 16;
  return seed >>> 0;
}

function getRenderedDieValue(dieState, now = Date.now()) {
  const dieType = normalizeDieType(dieState?.type);
  if (dieType === 'counter') {
    return clampCounterValue(dieState?.value);
  }
  if (
    dieType === 'timer' ||
    dieType === 'arcade' ||
    dieType === 'label' ||
    dieType === 'media' ||
    dieType === 'marble'
  ) {
    return 1;
  }
  if (dieType === 'spinner') {
    const segmentCount = getSpinnerSegmentCount(dieState);
    return clamp(Math.round(Number(dieState?.value) || 1), 1, segmentCount);
  }
  const sides = getDieSides(dieType, dieState);
  const settledValue = clamp(Math.round(Number(dieState?.value) || 1), 1, sides);
  if (!isDieRolling(dieState, now)) {
    return settledValue;
  }
  const elapsed = Math.max(0, now - (Number(dieState?.rollStartedAt) || 0));
  const tick = Math.floor(elapsed / DIE_ROLL_STEP_MS);
  const mixedSeed = getPseudoRandomFromSeed((Number(dieState?.rollSeed) || 0) + tick * 2654435761);
  return (mixedSeed % sides) + 1;
}

function getTopDieZ() {
  let topZ = 0;
  for (const dieState of diceById.values()) {
    topZ = Math.max(topZ, Number(dieState?.z) || 0);
  }
  return topZ;
}

function buildCoolJpegsDeck(options = {}) {
  const {
    instanceId = 'default',
    deckId: requestedDeckId = '',
    center: requestedCenter = getDeckCenterPosition(),
    inDeck: startInDeck = true,
    zStart = 1
  } = options;
  const deck = {};
  const normalizedRequestedDeckId = normalizeDeckId(requestedDeckId);
  const safeId = String(instanceId || 'default').trim().toLowerCase().replace(/[^a-z0-9_-]/g, '') || 'default';
  const cardIdPrefix = normalizedRequestedDeckId || (safeId === 'default' ? DECK_KEY : `${DECK_KEY}-${safeId}`);
  const nextDeckId = normalizeDeckId(cardIdPrefix);
  const center = {
    x: clamp(Number(requestedCenter?.x) || WORLD_WIDTH / 2, CARD_WIDTH / 2, WORLD_WIDTH - CARD_WIDTH / 2),
    y: clamp(Number(requestedCenter?.y) || WORLD_HEIGHT / 2, CARD_HEIGHT / 2, WORLD_HEIGHT - CARD_HEIGHT / 2)
  };
  const baseZ = Number.isFinite(Number(zStart)) ? Number(zStart) : 1;
  for (let index = 0; index < COOL_JPEGS_FRONT_IMAGES.length; index += 1) {
    const cardId = `${cardIdPrefix}-${String(index + 1).padStart(3, '0')}`;
    const cardNumber = 1000 + index;
    const cardInfo = COOL_JPEGS_CARD_INFO_BY_NUMBER[cardNumber] || null;
    deck[cardId] = {
      x: center.x,
      y: center.y,
      z: baseZ + index,
      face: 'back',
      frontSrc: COOL_JPEGS_FRONT_IMAGES[index],
      cardFamily: CARD_FAMILY_COOL,
      artist: normalizeCoolJpegsArtistLabel(cardInfo?.artist || ''),
      auctionType: normalizeCoolJpegsAuctionType(cardInfo?.auctionType || ''),
      deckBackSrc: CARD_BACK_IMAGE_SRC,
      deckId: nextDeckId,
      inDeck: startInDeck,
      inDiscard: false,
      inAuction: false,
      auctionSlotIndex: 0,
      auctionSellerPlayerToken: '',
      drawLifted: false,
      holderClientId: null,
      handOwnerClientId: null,
      handOwnerPlayerToken: null,
      updatedAt: Date.now()
    };
  }
  return deck;
}

