  attackerAvatar.alt = 'attacker side';
  attackerAvatar.draggable = false;
  attackerAvatar.className = 'mons-hud-avatar';
  attackerClaimButton.appendChild(attackerAvatar);
  attackerButtonWrap.appendChild(attackerClaimButton);
