function setMediaAddValidationMessage(message = '', options = {}) {
  const normalizedMessage = String(message || '').trim();
  if (mediaAddError) {
    mediaAddError.textContent = normalizedMessage;
    mediaAddError.classList.toggle('hidden', !normalizedMessage);
  }
  const markInvalid = options.urlInvalid === true;
  mediaAddInput?.classList.toggle('is-invalid', markInvalid);
}

function setStudioUploadValidationMessage(message = '', options = {}) {
  const normalizedMessage = String(message || '').trim();
  if (studioUploadError) {
    studioUploadError.textContent = normalizedMessage;
    studioUploadError.classList.toggle('hidden', !normalizedMessage);
    studioUploadError.classList.toggle('is-status', options.status === true && Boolean(normalizedMessage));
  }
  const markInvalid = options.fileInvalid === true;
  const markCoverInvalid = options.coverInvalid === true;
  studioUploadDropzone?.classList.toggle('is-invalid', markInvalid);
  studioUploadCoverDropzone?.classList.toggle('is-invalid', markCoverInvalid);
}

function revokeStudioUploadPreviewUrl(kind = 'media') {
  const normalizedKind = String(kind || '').trim().toLowerCase();
  if (normalizedKind === 'cover') {
    if (activeStudioUploadCoverPreviewUrl) {
      URL.revokeObjectURL(activeStudioUploadCoverPreviewUrl);
      activeStudioUploadCoverPreviewUrl = '';
    }
    return;
  }
  if (activeStudioUploadPreviewUrl) {
    URL.revokeObjectURL(activeStudioUploadPreviewUrl);
    activeStudioUploadPreviewUrl = '';
  }
}

function clearStudioUploadDropzonePreview(dropzone) {
  if (!(dropzone instanceof HTMLElement)) {
    return;
  }
  dropzone.classList.remove('has-preview');
  const preview = dropzone.querySelector('.studio-upload-preview');
  if (preview instanceof HTMLElement) {
    preview.remove();
  }
}

function renderStudioUploadDropzonePreview(dropzone, file, previewUrl, previewKind) {
  if (!(dropzone instanceof HTMLElement)) {
    return;
  }
  clearStudioUploadDropzonePreview(dropzone);
  if (!(file instanceof File) || !previewUrl) {
    return;
  }
  const normalizedPreviewKind = String(previewKind || '').trim().toLowerCase();
  const preview = document.createElement('div');
  preview.className = `studio-upload-preview studio-upload-preview-kind-${normalizedPreviewKind || 'file'}`;
  const mediaStop = (event) => {
    event.stopPropagation();
  };
  if (normalizedPreviewKind === STUDIO_UPLOAD_KIND_VIDEO) {
    const video = document.createElement('video');
    video.className = 'studio-upload-preview-media';
    video.src = previewUrl;
    video.controls = true;
    video.muted = true;
    video.playsInline = true;
    video.setAttribute('playsinline', '');
    video.preload = 'metadata';
    video.addEventListener('pointerdown', mediaStop);
    video.addEventListener('click', mediaStop);
    preview.appendChild(video);
  } else if (normalizedPreviewKind === STUDIO_UPLOAD_KIND_AUDIO) {
    const audio = document.createElement('audio');
    audio.className = 'studio-upload-preview-audio';
    audio.src = previewUrl;
    audio.controls = true;
    audio.preload = 'metadata';
    audio.addEventListener('pointerdown', mediaStop);
    audio.addEventListener('click', mediaStop);
    preview.appendChild(audio);
  } else if (normalizedPreviewKind === 'image') {
    const image = document.createElement('img');
    image.className = 'studio-upload-preview-image';
    image.src = previewUrl;
    image.alt = '';
    image.decoding = 'async';
    image.draggable = false;
    preview.appendChild(image);
  }
  const caption = document.createElement('span');
  caption.className = 'studio-upload-preview-caption';
  caption.textContent = String(file.name || '').trim() || 'selected file';
  preview.appendChild(caption);
  dropzone.appendChild(preview);
  dropzone.classList.add('has-preview');
}

function syncStudioUploadModalUi() {
  const normalizedKind = normalizeStudioUploadKind(activeStudioUploadKind);
  const isAudioUpload = normalizedKind === STUDIO_UPLOAD_KIND_AUDIO;
  if (studioUploadTitle) {
    studioUploadTitle.textContent = normalizedKind === STUDIO_UPLOAD_KIND_VIDEO ? 'adding video' : 'adding audio';
  }
  if (studioUploadLabel) {
    studioUploadLabel.textContent = getStudioUploadLabelText(normalizedKind);
  }
  if (studioUploadDropzoneHint) {
    studioUploadDropzoneHint.textContent = getStudioUploadHintText(normalizedKind);
  }
  if (studioUploadInput) {
    studioUploadInput.accept = getStudioUploadAccept(normalizedKind);
    studioUploadInput.disabled = studioUploadSubmitting;
    studioUploadInput.value = '';
  }
  if (studioUploadCoverField) {
    studioUploadCoverField.classList.toggle('hidden', !isAudioUpload);
  }
  if (studioUploadCoverLabel) {
    studioUploadCoverLabel.textContent = getStudioUploadCoverLabelText();
  }
  if (studioUploadCoverDropzoneHint) {
    studioUploadCoverDropzoneHint.textContent = getStudioUploadCoverHintText();
  }
  if (studioUploadCoverInput) {
    studioUploadCoverInput.accept = STUDIO_UPLOAD_IMAGE_ACCEPT;
    studioUploadCoverInput.disabled = studioUploadSubmitting || !isAudioUpload;
    studioUploadCoverInput.value = '';
  }
  if (studioUploadSelectedFile) {
    const selectedFileName = activeStudioUploadFile instanceof File
      ? String(activeStudioUploadFile.name || '').trim() || 'selected file'
      : 'no file selected';
    if (studioUploadSelectedFileName) {
      studioUploadSelectedFileName.textContent = selectedFileName;
    } else {
      studioUploadSelectedFile.textContent = selectedFileName;
    }
    studioUploadClearButton?.classList.toggle('hidden', !(activeStudioUploadFile instanceof File));
  }
  if (studioUploadCoverSelectedFile) {
    studioUploadCoverSelectedFile.classList.toggle('hidden', !isAudioUpload);
    const selectedCoverName = activeStudioUploadCoverFile instanceof File
      ? String(activeStudioUploadCoverFile.name || '').trim() || 'selected cover'
      : 'no cover selected';
    if (studioUploadCoverSelectedFileName) {
      studioUploadCoverSelectedFileName.textContent = selectedCoverName;
    } else {
      studioUploadCoverSelectedFile.textContent = selectedCoverName;
    }
    studioUploadCoverClearButton?.classList.toggle('hidden', !isAudioUpload || !(activeStudioUploadCoverFile instanceof File));
  }
  if (studioUploadDropzone instanceof HTMLElement) {
    studioUploadDropzone.setAttribute('aria-disabled', studioUploadSubmitting ? 'true' : 'false');
    studioUploadDropzone.tabIndex = studioUploadSubmitting ? -1 : 0;
    renderStudioUploadDropzonePreview(
      studioUploadDropzone,
      activeStudioUploadFile,
      activeStudioUploadPreviewUrl,
      normalizedKind
    );
  }
  if (studioUploadCoverDropzone instanceof HTMLElement) {
    const coverDisabled = studioUploadSubmitting || !isAudioUpload;
    studioUploadCoverDropzone.setAttribute('aria-disabled', coverDisabled ? 'true' : 'false');
    studioUploadCoverDropzone.tabIndex = coverDisabled ? -1 : 0;
    renderStudioUploadDropzonePreview(
      studioUploadCoverDropzone,
      isAudioUpload ? activeStudioUploadCoverFile : null,
      isAudioUpload ? activeStudioUploadCoverPreviewUrl : '',
      'image'
    );
  }
  if (studioUploadConfirmButton instanceof HTMLButtonElement) {
    const canSubmit = activeStudioUploadFile instanceof File && !studioUploadSubmitting;
    studioUploadConfirmButton.disabled = !canSubmit;
    studioUploadConfirmButton.classList.toggle('is-disabled', !canSubmit);
  }
}

function clearStudioUploadSelection() {
  revokeStudioUploadPreviewUrl('media');
  revokeStudioUploadPreviewUrl('cover');
  activeStudioUploadFile = null;
  activeStudioUploadCoverFile = null;
  studioUploadSubmitting = false;
  studioUploadDropzone?.classList.remove('is-dragover');
  studioUploadCoverDropzone?.classList.remove('is-dragover');
  setStudioUploadValidationMessage('');
  syncStudioUploadModalUi();
}

function setActiveStudioUploadFile(file) {
  revokeStudioUploadPreviewUrl('media');
  if (file instanceof File && isAllowedStudioUploadFile(file, activeStudioUploadKind)) {
    activeStudioUploadFile = file;
    activeStudioUploadPreviewUrl = URL.createObjectURL(file);
    setStudioUploadValidationMessage('');
  } else if (file instanceof File) {
    activeStudioUploadFile = null;
    setStudioUploadValidationMessage(
      normalizeStudioUploadKind(activeStudioUploadKind) === STUDIO_UPLOAD_KIND_VIDEO
        ? 'choose an mp4, mov, m4v, or webm file.'
        : 'choose an mp3 or wav file.',
      { fileInvalid: true }
    );
  } else {
    activeStudioUploadFile = null;
    setStudioUploadValidationMessage('');
  }
  syncStudioUploadModalUi();
}

function setActiveStudioUploadCoverFile(file) {
  revokeStudioUploadPreviewUrl('cover');
  if (file instanceof File && isAllowedStudioCoverFile(file)) {
    activeStudioUploadCoverFile = file;
    activeStudioUploadCoverPreviewUrl = URL.createObjectURL(file);
    setStudioUploadValidationMessage('');
  } else if (file instanceof File) {
    activeStudioUploadCoverFile = null;
    setStudioUploadValidationMessage('choose a png, jpg, webp, or gif image.', { coverInvalid: true });
  } else {
    activeStudioUploadCoverFile = null;
    setStudioUploadValidationMessage('');
  }
  syncStudioUploadModalUi();
}

function getStickerPackEntry(packKey = activeStickerPackKey) {
  const normalizedPackKey = normalizeStickerPackKey(packKey);
  const entry = stickerCatalog?.[normalizedPackKey];
  if (!entry || typeof entry !== 'object') {
    return {
      all: [],
      byCategory: createEmptyStickerCategoryMap()
    };
  }
  const all = Array.isArray(entry.all) ? entry.all : [];
  const byCategory = entry.byCategory && typeof entry.byCategory === 'object' ? entry.byCategory : createEmptyStickerCategoryMap();
  return { all, byCategory };
}

function getStickerCategoryFilterSet(packKey = activeStickerPackKey) {
  const normalizedPackKey = normalizeStickerPackKey(packKey);
  if (normalizedPackKey === STICKER_PACK_PLAY_THINGS) {
    return null;
  }
  const allowedCategories = getStickerAvailableCategoriesForPack(normalizedPackKey);
  let filters = activeStickerCategoryFiltersByPack[normalizedPackKey];
  if (!(filters instanceof Set)) {
    filters = new Set(allowedCategories);
    activeStickerCategoryFiltersByPack[normalizedPackKey] = filters;
    return filters;
  }
  for (const category of Array.from(filters)) {
    if (!allowedCategories.includes(category)) {
      filters.delete(category);
    }
  }
  return filters;
}

function getStickerVisibleItemsForPack(packKey = activeStickerPackKey) {
  const normalizedPackKey = normalizeStickerPackKey(packKey);
  const packEntry = getStickerPackEntry(normalizedPackKey);
  if (normalizedPackKey === STICKER_PACK_PLAY_THINGS) {
    return [...packEntry.all];
  }
  const filters = getStickerCategoryFilterSet(normalizedPackKey);
  const visible = [];
  const availableCategories = getStickerAvailableCategoriesForPack(normalizedPackKey);
  for (const category of availableCategories) {
    if (!(filters instanceof Set) || !filters.has(category)) {
      continue;
    }
    const categoryItems = Array.isArray(packEntry.byCategory?.[category]) ? packEntry.byCategory[category] : [];
    if (categoryItems.length > 0) {
      visible.push(...categoryItems);
    }
  }
  return visible;
}

function getStickerSelectionPool(packKey = activeStickerPackKey) {
  const visibleItems = getStickerVisibleItemsForPack(packKey);
  return visibleItems.length > 0 ? visibleItems : [];
}

function getSelectedStickerItem() {
  const selectionPool = getStickerSelectionPool(activeStickerPackKey);
  if (!activeStickerAssetSrc) {
    return null;
  }
  return selectionPool.find((item) => item.src === activeStickerAssetSrc) || null;
}

function syncStickerAddConfirmButtonState() {
  if (!(stickerAddConfirmButton instanceof HTMLButtonElement)) {
    return;
  }
  const hasSelection = Boolean(getSelectedStickerItem());
  stickerAddConfirmButton.disabled = !hasSelection;
  stickerAddConfirmButton.classList.toggle('is-disabled', !hasSelection);
}

function setActiveStickerAsset(src) {
  const normalizedSrc = String(src || '').trim();
  const selectionPool = getStickerSelectionPool(activeStickerPackKey);
  const hasMatch = selectionPool.some((item) => item.src === normalizedSrc);
  activeStickerAssetSrc = hasMatch ? normalizedSrc : '';
  if (!(stickerAddGallery instanceof HTMLElement)) {
    syncStickerAddConfirmButtonState();
    return;
  }
  const itemButtons = stickerAddGallery.querySelectorAll('.sticker-add-item');
  for (const itemButton of itemButtons) {
    const isActive = itemButton.getAttribute('data-sticker-src') === activeStickerAssetSrc;
    itemButton.classList.toggle('is-active', isActive);
    itemButton.setAttribute('aria-selected', isActive ? 'true' : 'false');
  }
  syncStickerAddConfirmButtonState();
}

function syncStickerPackTabsUi() {
  if (!(stickerPackTabs instanceof HTMLElement)) {
    return;
  }
  const packButtons = stickerPackTabs.querySelectorAll('.sticker-pack-tab[data-sticker-pack]');
  for (const button of packButtons) {
    const packKey = normalizeStickerPackKey(button.getAttribute('data-sticker-pack'));
    const isActive = packKey === activeStickerPackKey;
    button.classList.toggle('is-active', isActive);
    button.setAttribute('aria-selected', isActive ? 'true' : 'false');
  }
}

function syncStickerCategoryTabsUi() {
  if (!(stickerCategoryTabs instanceof HTMLElement)) {
    return;
  }
  const showCategoryFilters = activeStickerPackKey !== STICKER_PACK_PLAY_THINGS;
  const availableCategories = getStickerAvailableCategoriesForPack(activeStickerPackKey);
  stickerCategoryTabs.classList.toggle('hidden', !showCategoryFilters);
  const gridColumns = Math.max(1, availableCategories.length || 1);
  stickerCategoryTabs.style.gridTemplateColumns = `repeat(${gridColumns}, minmax(0, 1fr))`;
  const activeFilters = getStickerCategoryFilterSet(activeStickerPackKey);
  const categoryButtons = stickerCategoryTabs.querySelectorAll('.sticker-category-tab[data-sticker-category]');
  for (const button of categoryButtons) {
    const category = normalizeStickerCategoryKey(button.getAttribute('data-sticker-category'));
    const isAvailable = showCategoryFilters && category && availableCategories.includes(category);
    const isActive = isAvailable && activeFilters instanceof Set && activeFilters.has(category);
    button.classList.toggle('hidden', !isAvailable);
    button.disabled = !isAvailable;
    button.classList.toggle('is-active', isActive);
    button.setAttribute('aria-pressed', isActive ? 'true' : 'false');
  }
}

function ensureStickerAddGallery() {
  if (!(stickerAddGallery instanceof HTMLElement)) {
    return;
  }
  stickerAddGallery.textContent = '';
  const items = getStickerVisibleItemsForPack(activeStickerPackKey);
  for (const stickerItem of items) {
    const itemButton = document.createElement('button');
    itemButton.type = 'button';
    itemButton.className = 'sticker-add-item';
    itemButton.setAttribute('data-sticker-src', stickerItem.src);
    itemButton.setAttribute('data-sticker-pack', stickerItem.pack);
    itemButton.setAttribute('data-sticker-category', stickerItem.category || 'other');
    itemButton.setAttribute('role', 'option');
    itemButton.setAttribute('aria-selected', 'false');

    const itemImage = document.createElement('img');
    itemImage.src = stickerItem.previewSrc || stickerItem.src;
    itemImage.alt = stickerItem.label;
    itemImage.loading = 'lazy';
    itemImage.decoding = 'async';
    itemImage.draggable = false;
    itemButton.appendChild(itemImage);

    itemButton.addEventListener('click', () => {
      const shouldDeselect = activeStickerAssetSrc === stickerItem.src;
      setActiveStickerAsset(shouldDeselect ? '' : stickerItem.src);
    });

    stickerAddGallery.appendChild(itemButton);
  }
  setActiveStickerAsset(activeStickerAssetSrc);
}

function setActiveStickerPack(packKey, options = {}) {
  const normalizedPackKey = normalizeStickerPackKey(packKey);
  activeStickerPackKey = normalizedPackKey;
  if (normalizedPackKey !== STICKER_PACK_PLAY_THINGS) {
    getStickerCategoryFilterSet(normalizedPackKey);
  }
  syncStickerPackTabsUi();
  syncStickerCategoryTabsUi();
  if (options.refreshGallery !== false) {
    ensureStickerAddGallery();
  }
}

function toggleStickerCategoryFilter(category) {
  if (activeStickerPackKey === STICKER_PACK_PLAY_THINGS) {
    return;
  }
  const normalizedCategory = normalizeStickerCategoryKey(category);
  if (!normalizedCategory) {
    return;
  }
  const allowedCategories = getStickerAvailableCategoriesForPack(activeStickerPackKey);
  if (!allowedCategories.includes(normalizedCategory)) {
    return;
  }
  const filters = getStickerCategoryFilterSet(activeStickerPackKey);
  if (!(filters instanceof Set)) {
    return;
  }
  const allEnabled =
    allowedCategories.length > 0 &&
    allowedCategories.every((allowedCategory) => filters.has(allowedCategory));
  if (allEnabled) {
    filters.clear();
    filters.add(normalizedCategory);
  } else if (filters.has(normalizedCategory)) {
    filters.delete(normalizedCategory);
  } else {
    filters.add(normalizedCategory);
  }
  if (filters.size === 0) {
    for (const allowedCategory of allowedCategories) {
      filters.add(allowedCategory);
    }
  }
  syncStickerCategoryTabsUi();
  ensureStickerAddGallery();
}

async function loadStickerManifestIfNeeded() {
  if (stickerManifestLoaded) {
    return;
  }
  if (stickerManifestLoadPromise) {
    await stickerManifestLoadPromise;
    return;
  }
  stickerManifestLoadPromise = (async () => {
    try {
      const response = await fetch(STICKER_MANIFEST_URL, { cache: 'no-store' });
      if (!response.ok) {
        throw new Error(`failed to load sticker manifest (${response.status})`);
      }
      const payload = await response.json();
      stickerCatalog = mergeStickerCatalogWithManifest(payload);
      stickerManifestLoaded = true;
    } catch (error) {
      console.warn('Sticker manifest unavailable; falling back to default stickers.', error);
      stickerCatalog = cloneStickerCatalog(DEFAULT_STICKER_CATALOG);
    } finally {
      if (isStickerAddModalOpen()) {
        setActiveStickerPack(activeStickerPackKey);
      }
      warmStickerTileShufflePreviewCache();
      stickerManifestLoadPromise = null;
    }
  })();
  await stickerManifestLoadPromise;
}

