function openInstanceWarningModal() {
  if (!instanceWarningModal) {
    return Promise.resolve(true);
  }
  closeMonsItemChoiceModal();
  if (instanceWarningResolver) {
    // Recover from stale/pending resolver state so this interaction never no-ops.
    closeInstanceWarningModal(false);
  }
  instanceWarningModal.classList.remove('hidden');
  return new Promise((resolve) => {
    instanceWarningResolver = resolve;
  });
}

function hasGameInstanceOnTable(gameKey) {
  const requestedDeckKind =
    gameKey === POKER_DECK_KEY
      ? DECK_KIND_POKER
      : gameKey === CODEGAME_DECK_KEY
        ? DECK_KIND_CODEGAME
        : gameKey === DECK_KEY
          ? DECK_KIND_COOL
          : '';
  if (!requestedDeckKind) {
    return false;
  }
  // Treat a game instance as present only when gameplay cards for that deck
  // are actually on the table/hand, not merely because a stale deck node exists.
  for (const [cardId, cardState] of cards.entries()) {
    if (!cardState || typeof cardState !== 'object' || isVisualImageComponentCard(cardState)) {
      continue;
    }
    if (isHexitamaActionCardState(cardState, cardId)) {
      continue;
    }
    const cardFamily = getCardFamily(cardState, cardId);
    if (cardFamily === requestedDeckKind) {
      return true;
    }
  }
  return false;
}

async function confirmAdditionalInstanceWarningIfNeeded(gameKey) {
  if (!hasGameInstanceOnTable(gameKey)) {
    return true;
  }
  return openInstanceWarningModal();
}

async function handleGameOptionsReset() {
  if (!activeGameOptionsTarget) {
    return;
  }
  const targetMonsGameId = getMonsGameIdFromGameOptionsTarget(activeGameOptionsTarget);
  if (targetMonsGameId) {
    await resetSuperMetalMonsGame(targetMonsGameId);
    return;
  }
  const targetTaflGameId = getTaflGameIdFromGameOptionsTarget(activeGameOptionsTarget);
  if (targetTaflGameId) {
    await resetHnefataflGame(targetTaflGameId);
    return;
  }
  const targetGoGameId = getGoGameIdFromGameOptionsTarget(activeGameOptionsTarget);
  if (targetGoGameId) {
    await resetGoGame(targetGoGameId);
    return;
  }
  const targetHexitamaGameId = getHexitamaGameIdFromGameOptionsTarget(activeGameOptionsTarget);
  if (targetHexitamaGameId) {
    await resetHexitamaGame(targetHexitamaGameId);
    return;
  }
  const targetDeckId = getDeckIdFromGameOptionsTarget(activeGameOptionsTarget);
  await resetCoolJpegsGame(targetDeckId || activeDeckId);
}

async function handleGameOptionsPutAway() {
  if (!activeGameOptionsTarget) {
    return;
  }
  const targetMonsGameId = getMonsGameIdFromGameOptionsTarget(activeGameOptionsTarget);
  if (targetMonsGameId) {
    await putAwaySuperMetalMonsGame(targetMonsGameId);
    return;
  }
  const targetTaflGameId = getTaflGameIdFromGameOptionsTarget(activeGameOptionsTarget);
  if (targetTaflGameId) {
    await putAwayHnefataflGame(targetTaflGameId);
    return;
  }
  const targetGoGameId = getGoGameIdFromGameOptionsTarget(activeGameOptionsTarget);
  if (targetGoGameId) {
    await putAwayGoGame(targetGoGameId);
    return;
  }
  const targetHexitamaGameId = getHexitamaGameIdFromGameOptionsTarget(activeGameOptionsTarget);
  if (targetHexitamaGameId) {
    await putAwayHexitamaGame(targetHexitamaGameId);
    return;
  }
  const targetDeckId = getDeckIdFromGameOptionsTarget(activeGameOptionsTarget);
  await putAwayCoolJpegsGame(targetDeckId || activeDeckId);
}

