function getHexitamaGameDeleteFadeElements(gameId = activeHexitamaGameId) {
  const targetGameId = normalizeHexitamaGameId(gameId || activeHexitamaGameId);
  const hexitamaUi = hexitamaBoardElementsById.get(targetGameId);
  const elements = [];
  if (hexitamaUi) {
    elements.push(hexitamaUi.shell, hexitamaUi.playButton, hexitamaUi.moveButton, hexitamaUi.optionsButton);
  }
  for (const cardId of getHexitamaActionCardIdsForGame(targetGameId)) {
    elements.push(cardElements.get(cardId), handCardElements.get(cardId));
  }
  return getUniqueConnectedElements(elements);
}

  function getMonsPieceDeleteFadeElement(pieceId, gameId = activeMonsGameId) {
    const targetPieceId = String(pieceId || '').trim();
    if (!targetPieceId) {
      return null;
    }
    const targetGameId = normalizeMonsGameId(gameId || activeMonsGameId);
    const candidateSvgs = [];
    if (targetGameId === normalizeMonsGameId(activeMonsGameId) && monsBoardSvg instanceof SVGElement) {
      candidateSvgs.push(monsBoardSvg);
    }
    const ghostBoardUi = monsGhostBoardElementsById.get(targetGameId);
    if (ghostBoardUi?.boardSvg instanceof SVGElement) {
      candidateSvgs.push(ghostBoardUi.boardSvg);
    }
    for (const svg of candidateSvgs) {
      const pieceNodes = svg.querySelectorAll('[data-mons-piece-id]');
      for (const node of pieceNodes) {
        if (!(node instanceof Element)) {
          continue;
        }
        if (node.getAttribute('data-mons-piece-id') === targetPieceId) {
          return node;
        }
      }
    }
    return null;
  }

  async function deleteCardInRemoveMode(cardId) {
    const targetCardId = String(cardId || '').trim();
    if (!targetCardId) {
      return;
    }
    const cardSnapshot = cloneDeleteUndoPayload(cards.get(targetCardId));
    const attachedDrawingsById = {};
    const attachedDrawingElements = [];
    if (isNoteComponentCard(cardSnapshot)) {
      for (const [strokeId, strokeState] of drawingStrokes.entries()) {
        if (String(strokeState?.attachedCardId || '').trim() !== targetCardId) {
          continue;
        }
        const strokeSnapshot = cloneDeleteUndoPayload(strokeState);
        if (!strokeSnapshot) {
          continue;
        }
        attachedDrawingsById[strokeId] = strokeSnapshot;
        attachedDrawingElements.push(drawingStrokeElements.get(strokeId));
      }
    }
    const fadeElements = [cardElements.get(targetCardId), handCardElements.get(targetCardId), ...attachedDrawingElements];
    const didDelete = await runDeleteWithFade(
      `card:${targetCardId}`,
      fadeElements,
      async () => {
        const updatesByPath = {
          [`cards/${targetCardId}`]: null
        };
        for (const strokeId of Object.keys(attachedDrawingsById)) {
          updatesByPath[`drawings/${strokeId}`] = null;
        }
        await update(ref(db, roomPath), updatesByPath);
      }
    );
    if (didDelete && cardSnapshot) {
      pushDeleteModeUndoEntry({
        kind: 'card',
        cardId: targetCardId,
        cardPayload: cardSnapshot,
        drawingsById: attachedDrawingsById
      });
    }
  }

