            demon.stateStartedAt = now;
            demon.dirX = 0;
            demon.dirY = 0;
            demon.dashFromX = demon.x;
            demon.dashFromY = demon.y;
            demon.dashToX = demon.x;
            demon.dashToY = demon.y;
