  async function loadImageNaturalSize(src) {
    const normalizedSrc = normalizeImageComponentSrc(src);
    if (!normalizedSrc) {
      return { width: CARD_WIDTH, height: CARD_HEIGHT };
    }
    const finishPendingLoad = beginElementAssetLoad();
    return new Promise((resolve) => {
      const image = new Image();
      image.decoding = 'async';
      let settled = false;
      const finalize = (success) => {
        if (settled) {
          return;
        }
        settled = true;
        finishPendingLoad();
        if (success && Number.isFinite(image.naturalWidth) && Number.isFinite(image.naturalHeight) && image.naturalWidth > 0 && image.naturalHeight > 0) {
          resolve(clampImageComponentSize(image.naturalWidth, image.naturalHeight));
          return;
        }
        resolve({ width: CARD_WIDTH, height: CARD_HEIGHT });
      };
      image.onload = () => finalize(true);
      image.onerror = () => finalize(false);
      image.src = normalizedSrc;
      if (image.complete) {
        finalize(image.naturalWidth > 0 && image.naturalHeight > 0);
      }
    });
  }

  const uploadStudioStorageFile = async (file, options = {}) => {
    const storageGroup = String(options.storageGroup || 'upload').trim() || 'upload';
    const safeName = String(file.name || 'upload').replace(/[^a-zA-Z0-9._-]+/g, '-').slice(-120) || 'upload';
    const storagePath = `rooms/${roomId}/swagstudio/${storageGroup}/${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}-${safeName}`;
    const uploadRef = storageRef(storage, storagePath);
    const uploadTask = uploadBytesResumable(uploadRef, file, {
      contentType: options.contentType || file.type || undefined,
      customMetadata: {
        roomId,
        roomType: isSwagStudioRoom ? SWAG_STUDIO_ROOM_ID : 'table',
        ...(options.customMetadata && typeof options.customMetadata === 'object' ? options.customMetadata : {})
      }
    });
    await new Promise((resolve, reject) => {
      let settled = false;
      let noProgressTimerId = 0;
      let totalTimerId = 0;
      const clearTimers = () => {
        if (noProgressTimerId) {
          window.clearTimeout(noProgressTimerId);
          noProgressTimerId = 0;
        }
        if (totalTimerId) {
          window.clearTimeout(totalTimerId);
          totalTimerId = 0;
        }
      };
      const finish = (callback, value) => {
        if (settled) {
          return;
        }
        settled = true;
        clearTimers();
        callback(value);
      };
      const failForStall = () => {
        try {
          uploadTask.cancel();
        } catch {
          // Ignore cancellation errors; the timeout error is clearer.
        }
        finish(reject, new Error('Firebase Storage did not start uploading.'));
      };
      noProgressTimerId = window.setTimeout(failForStall, STUDIO_UPLOAD_STORAGE_NO_PROGRESS_TIMEOUT_MS);
      totalTimerId = window.setTimeout(() => {
        try {
          uploadTask.cancel();
        } catch {
          // Ignore cancellation errors; the timeout error is clearer.
        }
        finish(reject, new Error('Firebase Storage upload timed out.'));
      }, STUDIO_UPLOAD_STORAGE_TOTAL_TIMEOUT_MS);
      uploadTask.on(
        'state_changed',
        (snapshot) => {
          if (settled) {
            return;
          }
          if (typeof options.onProgress !== 'function') {
            if ((Number(snapshot.bytesTransferred) || 0) > 0 && noProgressTimerId) {
              window.clearTimeout(noProgressTimerId);
              noProgressTimerId = 0;
            }
            return;
          }
          const totalBytes = Math.max(1, Number(snapshot.totalBytes) || 1);
          const bytesTransferred = Number(snapshot.bytesTransferred) || 0;
          if (bytesTransferred > 0 && noProgressTimerId) {
            window.clearTimeout(noProgressTimerId);
            noProgressTimerId = 0;
          }
          const fraction = clamp(bytesTransferred / totalBytes, 0, 1);
          options.onProgress(fraction);
        },
        (error) => {
          finish(reject, error);
        },
        () => {
          finish(resolve);
        }
      );
    });
    const downloadUrl = await getDownloadURL(uploadTask.snapshot.ref);
    return {
      downloadUrl,
      mimeType: String(file.type || '').trim().slice(0, 120)
    };
  };

  const uploadStudioMediaFileToDatabase = async (kind, file, onProgress = null) => {
    const normalizedKind = normalizeStudioUploadKind(kind);
    const fallbackMimeType = getStudioUploadMimeType(file, normalizedKind);
    const dataUrl = await readStudioUploadFileAsDataUrl(file, {
      maxBytes: STUDIO_UPLOAD_DATABASE_FALLBACK_MAX_BYTES,
      onProgress
    });
    const fallbackSourceUrl =
      normalizeMediaDataUrl(dataUrl, normalizedKind) ||
      normalizeMediaDataUrl(rewriteDataUrlMimeType(dataUrl, fallbackMimeType), normalizedKind);
    if (!fallbackSourceUrl) {
      throw new Error('Could not prepare the selected media file.');
    }
    return {
      title: normalizeMediaTitle(normalizeStudioMediaFileName(file.name)),
      sourceUrl: fallbackSourceUrl,
      mimeType: fallbackMimeType.slice(0, 120)
    };
  };

  const uploadStudioCoverImageFileToDatabase = async (file, onProgress = null) => {
    const fallbackMimeType = getStudioCoverMimeType(file);
    const dataUrl = await readStudioUploadFileAsDataUrl(file, {
      maxBytes: STUDIO_UPLOAD_DATABASE_COVER_FALLBACK_MAX_BYTES,
      onProgress
    });
    const fallbackSourceUrl =
      normalizeMediaDataUrl(dataUrl, 'image') ||
      normalizeMediaDataUrl(rewriteDataUrlMimeType(dataUrl, fallbackMimeType), 'image');
    if (!fallbackSourceUrl) {
      throw new Error('Could not prepare the selected cover image.');
    }
    return {
      sourceUrl: fallbackSourceUrl,
      mimeType: fallbackMimeType.slice(0, 120)
    };
  };

  uploadStudioMediaFile = async (kind, file, onProgress = null) => {
    const normalizedKind = normalizeStudioUploadKind(kind);
    if (!(file instanceof File) || !isAllowedStudioUploadFile(file, normalizedKind)) {
      throw new Error(
        normalizedKind === STUDIO_UPLOAD_KIND_VIDEO
          ? 'Choose an mp4, mov, m4v, or webm file.'
          : 'Choose an mp3 or wav file.'
      );
    }
    try {
      const uploaded = await uploadStudioStorageFile(file, {
        storageGroup: normalizedKind,
        contentType: getStudioUploadMimeType(file, normalizedKind),
        customMetadata: {
          mediaKind: normalizedKind
        },
        onProgress
      });
      return {
        title: normalizeMediaTitle(normalizeStudioMediaFileName(file.name)),
        sourceUrl: normalizeMediaSourceUrl(uploaded.downloadUrl),
        mimeType: uploaded.mimeType
      };
    } catch (error) {
      console.warn('Firebase Storage upload failed; using database fallback for studio media.', error);
      return uploadStudioMediaFileToDatabase(normalizedKind, file, onProgress);
    }
  };

  uploadStudioCoverImageFile = async (file, onProgress = null) => {
    if (!(file instanceof File) || !isAllowedStudioCoverFile(file)) {
      throw new Error('Choose a png, jpg, webp, or gif image.');
    }
    try {
      const uploaded = await uploadStudioStorageFile(file, {
        storageGroup: 'audio-cover',
        contentType: getStudioCoverMimeType(file),
        customMetadata: {
          mediaKind: 'audio-cover'
        },
        onProgress
      });
      return {
        sourceUrl: normalizeMediaSourceUrl(uploaded.downloadUrl),
        mimeType: uploaded.mimeType
      };
    } catch (error) {
      console.warn('Firebase Storage upload failed; using database fallback for studio cover art.', error);
      return uploadStudioCoverImageFileToDatabase(file, onProgress);
    }
  };

  resolveStudioUploadedMediaSpawnDimensions = async (kind, file) => {
    const normalizedKind = normalizeStudioUploadKind(kind);
    return getDefaultMediaDimensions(
      normalizedKind === STUDIO_UPLOAD_KIND_VIDEO ? 'uploaded-video' : 'uploaded-audio'
    );
  };

  spawnChipStacksComponent = async (options = {}) => {
    const stackCount = normalizeChipStackCount(options.stackCount, CHIP_SET_MIN_STACKS);
    const quantity = normalizeChipStackQuantity(options.quantity, CHIP_STACK_MIN_QUANTITY);
    const labels = Array.isArray(options.labels) ? options.labels : [];
    const seedStacks = normalizeChipStacksPayload([], stackCount, { quantity }).map((stack, index) => ({
      ...stack,
      label:
        normalizeChipLabelText(labels[index]) ||
        normalizeChipLabelText(stack.label || stack.value || String(index + 1)) ||
        String(index + 1)
    }));
    const viewportCenter = getViewportWorldCenter();
    const provisionalChipSet = normalizeChipSetPayload({
      x: viewportCenter.x,
      y: viewportCenter.y,
      stackCount,
      stacks: seedStacks
    });
    const provisionalBounds = getChipSetCenterBounds(provisionalChipSet);
    let spawnX = provisionalChipSet.x;
    let spawnY = provisionalChipSet.y;
    if (isWorldPointHiddenBySecretAreaForLocalViewer(spawnX, spawnY)) {
      const candidateOffsets = [
        [220, 0],
        [-220, 0],
        [0, 220],
        [0, -220],
        [320, 180],
        [-320, 180],
        [320, -180],
        [-320, -180],
        [420, 0],
        [-420, 0],
        [0, 420],
        [0, -420]
      ];
      for (const [offsetX, offsetY] of candidateOffsets) {
        const candidateX = clamp(viewportCenter.x + offsetX, provisionalBounds.minX, provisionalBounds.maxX);
        const candidateY = clamp(viewportCenter.y + offsetY, provisionalBounds.minY, provisionalBounds.maxY);
        if (!isWorldPointHiddenBySecretAreaForLocalViewer(candidateX, candidateY)) {
          spawnX = candidateX;
          spawnY = candidateY;
          break;
        }
      }
    }
    const seededChipSet = normalizeChipSetPayload({
      x: spawnX,
      y: spawnY,
      stackCount,
      stacks: seedStacks
    });
    const indicatorId = createSpawnLoadingIndicator({
      worldX: seededChipSet.x,
      worldY: seededChipSet.y,
      worldWidth: getChipSetWorldWidth(seededChipSet),
      worldHeight: DIE_SIZE_CHIP
    });
    let createdChipSetId = '';
    let createdChipSetPayload = null;
    try {
      await runTransaction(
        chipSetsRef,
        (currentChipSets) => {
          const baseChipSets = currentChipSets && typeof currentChipSets === 'object' ? { ...currentChipSets } : {};
          let nextTopZ = getTopObjectZ();
          for (const payload of Object.values(baseChipSets)) {
            nextTopZ = Math.max(nextTopZ, Number(payload?.z) || 0);
          }
          let nextChipSetId = `chipset-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 9)}`;
          while (Object.prototype.hasOwnProperty.call(baseChipSets, nextChipSetId)) {
            nextChipSetId = `chipset-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 9)}`;
          }
          createdChipSetId = nextChipSetId;
          const nextChipSetPayload = {
            ...seededChipSet,
            z: nextTopZ + 1,
            holderClientId: null,
            updatedAt: Date.now()
          };
          createdChipSetPayload = nextChipSetPayload;
          baseChipSets[nextChipSetId] = nextChipSetPayload;
          return baseChipSets;
        },
        { applyLocally: false }
      );
      if (createdChipSetId && createdChipSetPayload && hasLoadedInitialCardsSnapshot) {
        chipSetsById.set(createdChipSetId, normalizeChipSetPayload(createdChipSetPayload));
        renderChipSets();
        syncClearTableButtonState();
      }
      finalizeSpawnLoadingIndicator(indicatorId, () => Boolean(createdChipSetId) && chipSetsById.has(createdChipSetId));
    } catch (error) {
      failSpawnLoadingIndicator(indicatorId);
      throw error;
    }
  };

  spawnDice = async (type = 'd6', count = 1) => {
    const normalizedType = normalizeDieType(type);
    const normalizedCount = clamp(Math.round(Number(count) || 1), 1, 5);
    const dieDimensions = getDieWorldDimensions(normalizedType);
    const viewportCenter = getViewportWorldCenter();
    const spawnCenterX = clamp(viewportCenter.x, dieDimensions.width / 2, WORLD_WIDTH - dieDimensions.width / 2);
    const spawnCenterY = clamp(viewportCenter.y, dieDimensions.height / 2, WORLD_HEIGHT - dieDimensions.height / 2);
    const totalSpan = (normalizedCount - 1) * DICE_SPAWN_GAP;
    const spawnWorldWidth = dieDimensions.width + totalSpan;
    const indicatorId = createSpawnLoadingIndicator({
      worldX: spawnCenterX,
      worldY: spawnCenterY,
      worldWidth: spawnWorldWidth,
      worldHeight: dieDimensions.height
    });
    let createdDieIds = [];
    try {
      if (normalizedType === 'marble' && normalizedCount === 1) {
        let nextDieId = `die-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 9)}`;
        while (diceById.has(nextDieId)) {
          nextDieId = `die-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 9)}`;
        }
        createdDieIds = [nextDieId];
        const createdAt = Date.now();
        const marblePayload = {
          type: 'marble',
          x: spawnCenterX,
          y: spawnCenterY,
          z: getTopObjectZ() + 1,
          value: 1,
          holderClientId: null,
          moving: false,
          velocityX: 0,
          velocityY: 0,
          marbleHue: getRandomMarbleHue(),
          rollStartedAt: 0,
          rollDurationMs: DIE_ROLL_DURATION_MS,
          rollSeed: Math.floor(Math.random() * 0x7fffffff),
          updatedAt: createdAt
        };
        await set(ref(db, `${roomPath}/dice/${nextDieId}`), marblePayload);
        // Optimistic local insert avoids "missing marble" during high write contention.
        diceById.set(nextDieId, normalizeDicePayload(marblePayload));
        renderDieElement(nextDieId);
        finalizeSpawnLoadingIndicator(indicatorId, () => Boolean(createdDieIds[0]) && diceById.has(createdDieIds[0]));
        return;
      }
      await runTransaction(
        diceRef,
        (currentDice) => {
          const baseDice = currentDice && typeof currentDice === 'object' ? { ...currentDice } : {};
          let nextTopZ = getTopObjectZ();
          for (const payload of Object.values(baseDice)) {
            nextTopZ = Math.max(nextTopZ, Number(payload?.z) || 0);
          }
          const generatedIds = [];
          const startX = spawnCenterX - totalSpan / 2;
          for (let index = 0; index < normalizedCount; index += 1) {
            let nextDieId = `die-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 9)}`;
            while (Object.prototype.hasOwnProperty.call(baseDice, nextDieId)) {
              nextDieId = `die-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 9)}`;
            }
            generatedIds.push(nextDieId);
            const sides = getDieSides(normalizedType);
            const x = clamp(
              startX + index * DICE_SPAWN_GAP,
              dieDimensions.width / 2,
              WORLD_WIDTH - dieDimensions.width / 2
            );
            const y = spawnCenterY;
            nextTopZ += 1;
            const createdAt = Date.now();
            const initialValue =
              normalizedType === 'counter'
                ? 0
                : normalizedType === 'timer'
                  ? 0
                : normalizedType === 'arcade'
                  ? 1
                : 1 + Math.floor(Math.random() * sides);
            baseDice[nextDieId] = {
              type: normalizedType,
              x,
              y,
              z: nextTopZ,
              value: initialValue,
              holderClientId: null,
              ...(normalizedType === 'timer'
                ? {
                  timerElapsedMs: 0,
                  timerRunning: false,
                  timerStartedAt: 0,
                  timerSplits: [],
                  timerSplitsVisible: false
                }
                : {}),
              ...(normalizedType === 'arcade'
                ? {
                  arcadeMenuIndex: 0,
                  arcadeJPressed: false,
                  arcadeKPressed: false,
                  arcadeScreen: ARCADE_SCREEN_MAIN,
                  arcadeStickX: 0,
                  arcadeStickY: 0,
                  arcadeManaMenuIndex: 0,
                  arcadeControllerClientId: '',
                  arcadeControllerPlayerToken: '',
                  arcadeControllerName: '',
                  arcadeControllerColor: '#ff7a59',
                  arcadeMgTileX: ARCADE_MANA_CENTER_TILE,
                  arcadeMgTileY: ARCADE_MANA_CENTER_TILE,
                  arcadeMgTailPath: '',
                  arcadeMgLooseManaPath: '',
                  arcadeMgClearManaPath: '',
                  arcadeMgDemonsPath: '',
                  arcadeMgBombPath: '',
                  arcadeMgBombFxPath: '',
                  arcadeMgPickupPulsePath: '',
                  arcadeMgLastPickupAt: 0,
                  arcadeMgManaPickupCount: 0,
                  arcadeMgHasSpawnedDemon: false,
                  arcadeMgNextDemonSpawnAt: 0,
                  arcadeMgManaType: ARCADE_MANA_TYPE_WHITE,
                  arcadeMgManaTileX: ARCADE_MANA_CENTER_TILE,
                  arcadeMgManaTileY: ARCADE_MANA_CENTER_TILE,
                  arcadeMgGameOver: false,
                  arcadeMgGameOverAt: 0,
                  arcadeMgGameOverFlip: false,
                  arcadeMgNewHighScore: false,
                  arcadeMgSquareClearScore: 0,
                  arcadeMgComboCount: 0,
                  arcadeMgComboLastScoredAt: 0,
                  arcadeMgPhaseActive: false,
                  arcadeMgPhaseStartedAt: 0,
                  arcadeMgPotionActive: false,
                  arcadeMgPotionStartedAt: 0,
                  arcadeMgClearManaStartedAt: 0,
                  arcadeMgDirX: 0,
                  arcadeMgDirY: 0,
                  arcadeMgQueuedDirX: 0,
                  arcadeMgQueuedDirY: 0,
                  arcadeMgMoveStartedAt: 0,
                  arcadeMgQueuedAt: 0,
                  arcadeMgInputQueuePath: ''
                }
                : {}),
              ...(normalizedType === 'marble'
                ? {
                  moving: false,
                  velocityX: 0,
                  velocityY: 0,
                  marbleHue: getRandomMarbleHue()
                }
                : {}),
              rollStartedAt: 0,
              rollDurationMs: DIE_ROLL_DURATION_MS,
              rollSeed: Math.floor(Math.random() * 0x7fffffff),
              updatedAt: createdAt
            };
          }
          createdDieIds = generatedIds;
          return baseDice;
        },
        { applyLocally: false }
      );
      finalizeSpawnLoadingIndicator(
        indicatorId,
        () => createdDieIds.length > 0 && createdDieIds.every((dieId) => diceById.has(dieId))
      );
    } catch (error) {
      failSpawnLoadingIndicator(indicatorId);
      throw error;
    }
  };
